window.PM_DATA={"secciones":[{"nombre":"基礎","grupos":[{"nombre":"運動の基礎","icono":"🧭","temas":[1,2,3,4]},{"nombre":"評価","icono":"📋","temas":[5,6,7,8,9]}]},{"nombre":"部位別の特殊テスト","grupos":[{"nombre":"肩関節","icono":"💪","temas":[10,11,12]},{"nombre":"肘・手関節・手","icono":"✋","temas":[13,14]},{"nombre":"脊椎・骨盤","icono":"🦴","temas":[15,16,17]},{"nombre":"股関節・膝関節","icono":"🦵","temas":[18,19,20]},{"nombre":"足関節・足部","icono":"🦶","temas":[21]},{"nombre":"神経学的テスト","icono":"🧠","temas":[22]}]},{"nombre":"疾患・外傷とリハビリ","grupos":[{"nombre":"肩関節","icono":"💪","temas":[23,24,25]},{"nombre":"スポーツ・腱・筋","icono":"🏃","temas":[26,27,28,29,30]},{"nombre":"整形外科・外傷","icono":"🦴","temas":[31,32,33]},{"nombre":"脊椎","icono":"🧍","temas":[34,35,36]},{"nombre":"神経","icono":"🧠","temas":[37,38,39,40,41]}]},{"nombre":"治療と介入","grupos":[{"nombre":"手技と物理療法","icono":"🤲","temas":[42,43,44,45,46,47]},{"nombre":"運動療法と専門領域","icono":"🩺","temas":[48,49,50,51,52,53]},{"nombre":"臨床ケース","icono":"🧩","temas":[54]}]}],"temas":{"1":{"id":1,"title":"運動面と運動軸","lead":"身体の運動は3つの基本面と、それに垂直な運動軸で記述します。面と軸の対応は、評価・記録・動作分析すべての土台です。","sheet":{"kind":"basics","items":[{"h":"基準の肢位","t":"面と軸は解剖学的立位肢位を基準に定義します。ROM測定の0°は基本肢位（前腕は中間位）なので、両者の違いに注意します。"},{"h":"矢状面","t":"身体を左右に分ける面です。屈曲・伸展、足関節の背屈・底屈が起こり、運動軸は前額-水平軸です。"},{"h":"前額面","t":"身体を前後に分ける面です。外転・内転、体幹の側屈が起こり、運動軸は矢状-水平軸です。"},{"h":"水平面","t":"身体を上下に分ける面です。内旋・外旋、体幹の回旋、肩の水平屈曲・水平伸展が起こり、運動軸は垂直軸です。"},{"h":"面と軸の関係","t":"運動軸は必ずその運動面に垂直に通ります。面と軸を対で覚えると、初めて見る運動でも整理できます。"},{"h":"複合運動","t":"実際の動作は複数の面にまたがります。歩行や投球などは、面ごとに分けて観察し、組み合わせとして分析します。"}]},"keypoints":["矢状面＝屈曲・伸展、軸は前額-水平軸","前額面＝外転・内転、軸は矢状-水平軸","水平面＝回旋、軸は垂直軸","運動軸は常にその運動面に垂直に通る","動作分析は面ごとに分けて観察する"],"case":{"text":"20歳、陸上選手。背臥位で下肢をまっすぐ前方へ挙上する運動（股関節）を記録したい。どの面と軸で記載するか。","answer":"股関節の前方挙上は屈曲で、矢状面の運動、軸は前額-水平軸です。前額面の外転と混同しないよう、身体を左右に分ける面の運動かどうかで判断します。"},"questions":[{"level":"基礎","q":"外転・内転が起こる運動面はどれか。","options":["矢状面","前額面","水平面","斜位面"],"answer":1,"exp":"前額面は身体を前後に分ける面で、外転・内転が起こります。運動軸は矢状-水平軸です。"},{"level":"基礎","q":"水平面で起こる回旋運動の運動軸はどれか。","options":["前額-水平軸","矢状-水平軸","斜軸","垂直軸"],"answer":3,"exp":"水平面の運動（回旋）は、その面に垂直な垂直軸のまわりで起こります。"},{"level":"中級","q":"矢状面で起こる運動はどれか。","options":["体幹の側屈","足関節の背屈","股関節の外旋","肩関節の外転"],"answer":1,"exp":"背屈・底屈は屈曲・伸展と同じく矢状面の運動です。側屈と外転は前額面、外旋は水平面の運動です。"},{"level":"中級","q":"肩関節の水平屈曲が起こる運動面はどれか。","options":["矢状面","前額面","水平面","どの面にも属さない"],"answer":2,"exp":"水平屈曲・水平伸展は、肩90°外転位で上肢を水平面上で動かす運動で、軸は垂直軸です。"},{"level":"臨床","q":"上腕下垂位・肘90°屈曲で肩関節外旋を測定する。運動面と軸の組み合わせで正しいのはどれか。","options":["矢状面・前額-水平軸","前額面・矢状-水平軸","水平面・垂直軸","水平面・前額-水平軸"],"answer":2,"exp":"下垂位での肩の内旋・外旋は水平面の運動で、上腕の長軸（垂直軸）まわりに起こります。"},{"level":"臨床","q":"歩行観察で、立脚期に骨盤が遊脚側へ下がる所見を認めた。主に観察している面はどれか。","options":["前額面","矢状面","水平面","面は特定できない"],"answer":0,"exp":"骨盤の左右の傾きは前額面の運動で、前方か後方から観察します。中殿筋の機能低下を考える所見です。"}],"seccion":"基礎","grupo":"運動の基礎","icono":"🧭","mapa":"img/mapas/t01.jpg","fichas":[],"secuencias":[]},"2":{"id":2,"title":"バイオメカニクス","lead":"バイオメカニクスは、力と運動の関係から身体の動きを理解する学問です。てこ・モーメント・重心を押さえると、運動療法の負荷設計が明確になります。","sheet":{"kind":"basics","items":[{"h":"力のモーメント","t":"関節を回転させる作用は力のモーメント（トルク）です。力の大きさと、回転軸から力の作用線までの垂直距離（レバーアーム）の積で決まります。"},{"h":"てこの3種","t":"第1のてこは支点、第2は作用点、第3は力点が中央にあります。人体の多くの筋は第3のてこで、力よりも速さと可動範囲に有利です。"},{"h":"重心","t":"立位の身体重心は骨盤内、第2仙椎のやや前方にあるとされます。重心線が支持基底面の中にあるほど姿勢は安定します。"},{"h":"運動連鎖","t":"開放性運動連鎖（OKC）は遠位部が自由な運動、閉鎖性運動連鎖（CKC）は遠位部が床などに固定された運動です。目的に応じて使い分けます。"},{"h":"筋の収縮様式","t":"求心性収縮は筋が短縮しながら、遠心性収縮は伸張されながら張力を発揮します。等尺性収縮は関節運動を伴いません。"},{"h":"臨床への応用","t":"重りを遠位に付けるほどレバーアームが長くなり負荷が増えます。運動療法の負荷は、重さだけでなく位置でも調整できます。"}]},"keypoints":["モーメントは力×レバーアームで決まる","人体の多くの筋は第3のてこ（速さに有利）","重心線が支持基底面内なら姿勢は安定","下降動作の多くは遠心性収縮で制御する","負荷は重さだけでなく位置でも調整できる"],"case":{"text":"65歳女性、変形性膝関節症。背臥位で足関節部に重錘を巻いてSLR訓練を行うと、疲労が強く代償動作が出る。","answer":"重錘を下腿近位へ移すとレバーアームが短くなり、同じ重さでも股関節屈曲モーメントが減ります。痛みと代償を確認しながら段階的に負荷を上げ、回数だけを増やす対応は避けます。"},"questions":[{"level":"基礎","q":"支点が力点と作用点の間にあるてこはどれか。","options":["第1のてこ","第2のてこ","第3のてこ","輪軸"],"answer":0,"exp":"第1のてこは支点が中央にあり、頭部の前後の釣り合いが代表例です。"},{"level":"基礎","q":"上腕二頭筋による肘関節屈曲が代表例となるてこはどれか。","options":["第1のてこ","第2のてこ","第3のてこ","滑車"],"answer":2,"exp":"肘関節（支点）と手の重り（作用点）の間に筋の付着（力点）があるため、第3のてこです。"},{"level":"中級","q":"関節モーメントの大きさを決める組み合わせとして正しいのはどれか。","options":["力の大きさと速度","筋長と筋断面積","力の大きさとレバーアーム","質量と温度"],"answer":2,"exp":"モーメントは、力の大きさと回転軸から作用線までの垂直距離（レバーアーム）の積です。"},{"level":"中級","q":"スクワットの下降期に大腿四頭筋が行う主な収縮様式はどれか。","options":["求心性収縮","等尺性収縮","等速性収縮","遠心性収縮"],"answer":3,"exp":"下降期は膝が屈曲し、大腿四頭筋は伸張されながら体重を支えるため遠心性収縮です。"},{"level":"臨床","q":"高齢者が前方の物を取ろうとしてふらついた。重心の観点で最も適切な説明はどれか。","options":["重心線が支持基底面の端に近づいた","支持基底面が広がりすぎた","重心が低くなりすぎた","求心性収縮が増えた"],"answer":0,"exp":"前方へのリーチで重心線が支持基底面の前端に近づき、安定性が低下します。"},{"level":"臨床","q":"端座位で重錘を使った膝伸展運動を行う。重さを変えずに負荷を下げる方法はどれか。","options":["重錘を足関節へ移す","重錘を下腿近位へ移す","運動速度を上げる","最終域での保持を長くする"],"answer":1,"exp":"重錘を膝に近づけるとレバーアームが短くなり、同じ重さでもモーメントが小さくなります。"}],"seccion":"基礎","grupo":"運動の基礎","icono":"🧭","mapa":"img/mapas/t02.jpg","fichas":[],"secuencias":[]},"3":{"id":3,"title":"関節可動域（ゴニオメトリー）","lead":"関節可動域測定は、ゴニオメーターで関節の動く範囲を角度で記録する評価です。障害の把握、目標設定、効果判定の基準になります。","sheet":{"kind":"basics","items":[{"h":"基本ルール","t":"基本肢位を0°とし、5°刻みで記録します。原則として他動運動で測定し、自動運動で測った場合はその旨を明記します。"},{"h":"基本軸と移動軸","t":"関節ごとに決められた基本軸と移動軸にゴニオメーターの両アームを合わせ、角度計の中心を関節の運動軸に合わせます。"},{"h":"参考可動域","t":"日本整形外科学会・日本リハビリテーション医学会の参考可動域を目安にします。年齢や個人差があるため、必ず反対側と比較します。"},{"h":"代償運動","t":"体幹の反りや骨盤の傾きなどの代償が入ると値が大きく出ます。近位部をしっかり固定し、代償を除いて測定します。"},{"h":"エンドフィール","t":"最終域の抵抗感（骨性・軟部組織性・結合組織性など）と痛みの有無を確認し、可動域を制限している因子を推定します。"},{"h":"記録と再評価","t":"測定肢位、他動か自動か、痛みの出現角度を記録します。再評価は同じ肢位・同じ方法で行うと比較しやすくなります。"}]},"keypoints":["0°は基本肢位、記録は5°刻み","原則は他動運動、自動運動なら明記する","近位部を固定して代償を除く","参考可動域は目安。必ず反対側と比較する","エンドフィールと痛みで制限因子を推定する"],"case":{"text":"40歳男性、肩関節周囲炎。肩関節屈曲の測定中に体幹が後方へ反り、測定値が健側とほぼ同じに見える。","answer":"体幹伸展の代償で値が過大になっている可能性があります。体幹を固定して再測定し、痛みの出現角度とエンドフィールも記録します。代償込みの値で「改善した」と判断しないことが重要です。"},"questions":[{"level":"基礎","q":"肩関節屈曲の参考可動域として正しいのはどれか。","options":["90°","120°","150°","180°"],"answer":3,"exp":"肩関節の屈曲と外転の参考可動域はいずれも180°です。"},{"level":"基礎","q":"足関節背屈の参考可動域として正しいのはどれか。","options":["10°","20°","30°","45°"],"answer":1,"exp":"足関節背屈の参考可動域は20°です。測定は必ず中間位（0°）から行います。"},{"level":"中級","q":"関節可動域測定の原則として正しいのはどれか。","options":["自動運動で測定する","1°刻みで記録する","基本肢位を0°とする","反対側との比較は不要"],"answer":2,"exp":"基本肢位を0°とし、原則として他動運動で、5°刻みで記録します。反対側と比較します。"},{"level":"中級","q":"最終域で硬く急に止まる骨性のエンドフィールが示すものはどれか。","options":["筋スパズム","骨同士の接触","関節包の伸張","軟部組織の接触"],"answer":1,"exp":"骨性のエンドフィールは骨と骨がぶつかって止まる感覚で、正常では肘関節伸展が代表例です。"},{"level":"臨床","q":"股関節外転の測定中に骨盤が傾き、値が大きく出た。まず行う対応はどれか。","options":["そのまま記録する","骨盤を固定して再測定する","自動運動に変えて測る","測定を中止する"],"answer":1,"exp":"骨盤の代償が入ると外転角度は過大になります。骨盤を固定して再測定します。"},{"level":"臨床","q":"膝の術後、他動屈曲の最終域で痛みが出現した。記録として最も適切なのはどれか。","options":["角度だけを記録する","健側の値を記録する","痛みが消えるまで記録しない","痛みの出現角度も記録する"],"answer":3,"exp":"可動域の値に加え、痛みの出現角度と性質を記録すると、制限因子の推定と再評価に役立ちます。"}],"seccion":"基礎","grupo":"運動の基礎","icono":"🧭","mapa":"img/mapas/t03.jpg","fichas":[],"secuencias":[]},"4":{"id":4,"title":"徒手筋力検査（0〜5）","lead":"徒手筋力検査（MMT）は、重力と徒手抵抗を用いて筋力を0〜5の6段階で判定する評価です。筋力低下の程度と分布を把握できます。","sheet":{"kind":"basics","items":[{"h":"6段階の基準","t":"0は収縮なし、1は収縮のみ、2は重力を除けば全可動域、3は重力に抗して全可動域、4は中等度の抵抗、5は最大抵抗に抗する正常筋力です。"},{"h":"検査の順序","t":"まず抗重力位で段階3が可能かを確認します。可能なら抵抗を加えて4・5を判定し、不可能なら重力を除いた肢位で2以下を判定します。"},{"h":"抵抗のかけ方","t":"抵抗は運動方向と反対向きに、分節の遠位部へ加えます。急に加えず、徐々に強めながら保持できるかを確認します。"},{"h":"固定と代償","t":"近位部を固定し、他の筋による代償運動が出ていないかを観察します。代償で動いた場合は、その段階とは判定しません。"},{"h":"段階3の意味","t":"段階3は自分の分節の重さに抗して動かせる境界で、「重力の壁」と呼ばれます。動作の可否を考える目安の一つです。"},{"h":"限界","t":"MMTは検者の主観を含み、段階4以上の差は検出しにくい評価です。痛みや筋緊張の異常があれば、所見とあわせて記録します。"}]},"keypoints":["まず抗重力で段階3を確認する","段階3が「重力の壁」","抵抗は運動と反対向きに遠位部へ加える","近位部を固定し代償運動を見逃さない","中枢神経疾患ではMMT単独で判定しない"],"case":{"text":"70歳男性、入院による廃用。端座位で膝伸展を全可動域行えるが、下腿遠位に軽い抵抗を加えると保持できない。","answer":"重力に抗して全可動域を動かせるが抵抗には抗せないため、段階3と判定します。抵抗を急に強くかけたり、体幹を後ろへ倒すなどの代償を見逃したりしないよう注意します。"},"questions":[{"level":"基礎","q":"「収縮は見える・触れるが関節運動はない」段階はどれか。","options":["段階0","段階1","段階2","段階3"],"answer":1,"exp":"段階1は筋収縮を視診・触診で確認できるが、関節運動が起こらない状態です。"},{"level":"基礎","q":"重力に抗して全可動域を動かせるが、抵抗には抗せない段階はどれか。","options":["段階4","段階2","段階3","段階5"],"answer":2,"exp":"段階3は抗重力で全可動域を動かせる段階で、「重力の壁」と呼ばれます。"},{"level":"中級","q":"MMTで最初に確認するのが一般的な段階はどれか。","options":["段階1","段階5","段階0","段階3"],"answer":3,"exp":"まず抗重力位で段階3が可能かを確認し、その結果で抵抗を加えるか重力除去位へ移るかを決めます。"},{"level":"中級","q":"MMTで抵抗を加える位置として適切なのはどれか。","options":["関節の直上","分節の近位部","分節の遠位部","固定している部位"],"answer":2,"exp":"抵抗は運動方向と反対向きに、レバーアームが長くなる分節の遠位部へ加えます。"},{"level":"臨床","q":"側臥位では股関節外転で下肢を持ち上げられないが、背臥位では全可動域を外転できる。段階はどれか。","options":["段階1","段階2","段階3","段階4"],"answer":1,"exp":"抗重力位（側臥位）では不可能で、重力を除いた背臥位で全可動域を動かせるので段階2です。"},{"level":"臨床","q":"痙縮の強い片麻痺患者の上肢筋力を評価したい。最も適切な考え方はどれか。","options":["MMT単独では判定しにくい","MMTの段階5を目標にする","抵抗を強くかけて判定する","非麻痺側の評価は不要"],"answer":0,"exp":"中枢神経疾患では筋緊張や共同運動の影響でMMTの前提が成り立ちにくく、運動麻痺の評価を併用します。"}],"seccion":"基礎","grupo":"運動の基礎","icono":"🧭","mapa":"img/mapas/t04.jpg","fichas":[],"secuencias":[]},"5":{"id":5,"title":"問診","lead":"問診は症状の経過・性質・生活背景を聞き取り、仮説を立てる評価の出発点です。その後の検査の選択と安全確認を左右します。","sheet":{"kind":"basics","items":[{"h":"目的","t":"主訴と経過から病態の仮説を立て、検査の優先順位を決めます。同時に、医師への連絡が必要な危険信号がないかを確認します。"},{"h":"主訴と現病歴","t":"主訴は本人の言葉で記録します。発症の時期ときっかけ（外傷か徐々にか）、その後の経過（改善・悪化・変化なし）を聞きます。"},{"h":"痛みの評価","t":"部位、性質、強さ（NRSなど）、増悪・軽減因子、1日の中での変動、夜間痛の有無を確認します。"},{"h":"既往歴と服薬","t":"既往歴、手術歴、合併症、服薬を確認します。抗凝固薬やステロイドの使用は、介入時の注意点になります。"},{"h":"生活背景","t":"仕事、家庭での役割、住環境、活動量を聞きます。本人と家族のニード・ホープを目標設定に反映します。"},{"h":"聞き方","t":"開かれた質問から始め、閉じた質問で確認します。専門用語を避け、要約して返すと情報の食い違いを防げます。"}]},"keypoints":["主訴は本人の言葉のまま記録する","発症のきっかけと経過を必ず聞く","夜間痛・体重減少など危険信号を確認する","服薬（抗凝固薬など）は介入の注意点","開かれた質問から始め、閉じた質問で確認"],"case":{"text":"55歳男性、2か月前からの腰痛。「最近は夜も痛くて眠れない。何もしていないのに体重が5kg減った」と話す。","answer":"安静で軽減しない夜間痛と原因不明の体重減少はレッドフラッグです。運動療法を始める前に医師へ報告・相談します。問診で得た危険信号を、その後の検査結果で打ち消さないことが大切です。"},"questions":[{"level":"基礎","q":"問診で最初に聴取し、本人の言葉のまま記録するものはどれか。","options":["既往歴","主訴","家族歴","服薬"],"answer":1,"exp":"主訴は患者が一番困っていることで、解釈を加えず本人の言葉で記録します。"},{"level":"基礎","q":"痛みの強さを0〜10の数字で答えてもらう評価はどれか。","options":["MMT","ROM","NRS","ADL"],"answer":2,"exp":"NRS（数値評価スケール）は痛みの強さを0〜10で表してもらう方法です。"},{"level":"中級","q":"開かれた質問として適切なのはどれか。","options":["「痛いのは右ですか」","「夜は痛みますか」","「薬は飲んでいますか」","「どんなときに痛みますか」"],"answer":3,"exp":"開かれた質問は「はい・いいえ」で答えられない質問で、患者から多くの情報を引き出せます。"},{"level":"中級","q":"介入時の注意点として、問診で特に確認すべき情報はどれか。","options":["抗凝固薬の服用","利き手","通勤手段","趣味の有無"],"answer":0,"exp":"抗凝固薬の服用は出血や内出血のリスクに関わり、徒手的な介入などの注意点になります。"},{"level":"臨床","q":"腰痛の患者が「夜も痛くて眠れず、体重が5kg減った」と話す。最も適切な対応はどれか。","options":["運動療法をすぐ始める","温熱療法で経過をみる","医師へ報告・相談する","次回まで様子をみる"],"answer":2,"exp":"安静で軽減しない夜間痛と原因不明の体重減少はレッドフラッグで、治療前に医師へ相談します。"},{"level":"臨床","q":"骨粗鬆症のある70歳女性。転倒後から股関節が痛み、歩けない。まず考えるべきことはどれか。","options":["筋力低下による痛み","骨折の可能性","変形性関節症の悪化","心理的な要因"],"answer":1,"exp":"骨粗鬆症がある人の転倒後の痛みと歩行困難は骨折を疑い、医師の評価を優先します。"}],"seccion":"基礎","grupo":"評価","icono":"📋","mapa":"img/mapas/t05.jpg","fichas":[],"secuencias":[]},"6":{"id":6,"title":"レッドフラッグ","lead":"レッドフラッグは、重い疾患が隠れている可能性を示す警告サインです。見つけたら、理学療法を進める前に医師へ相談します。","sheet":{"kind":"basics","items":[{"h":"定義","t":"悪性腫瘍、感染、骨折、馬尾症候群など、緊急性の高い病態を疑わせる徴候です。単独よりも複数の組み合わせで重みが増します。"},{"h":"悪性腫瘍","t":"がんの既往、原因不明の体重減少、安静でも改善しない夜間痛などを確認します。年齢や全身状態もあわせて考えます。"},{"h":"感染","t":"発熱を伴う腰背部痛、免疫抑制状態、最近の感染症や侵襲的な処置の既往に注意します。"},{"h":"骨折","t":"強い外傷の後や、骨粗鬆症がある人の軽い転倒後の痛みは骨折を疑います。ステロイドの長期使用も確認します。"},{"h":"馬尾症候群","t":"膀胱直腸障害、サドル領域の感覚消失、進行する下肢の筋力低下は緊急性が高く、直ちに医師へ連絡します。"},{"h":"対応","t":"所見と経過を記録し、医師へ報告・相談します。患者に過度な不安を与えないよう、受診の必要性を丁寧に説明します。"}]},"keypoints":["安静でも改善しない夜間痛は要注意","原因不明の体重減少は腫瘍を疑う手がかり","膀胱直腸障害・サドル麻痺は緊急","外傷や骨粗鬆症があれば骨折を疑う","レッドフラッグありは治療前に医師へ相談"],"case":{"text":"45歳女性、腰痛と右下肢痛。今朝から排尿しにくく、肛門周囲がしびれると訴える。","answer":"膀胱直腸障害とサドル領域の感覚障害は、馬尾症候群を疑うサインです。評価や運動を続けず、直ちに医師へ連絡します。「様子をみる」対応は避けます。"},"questions":[{"level":"基礎","q":"腰背部痛のレッドフラッグに該当するのはどれか。","options":["動くと痛む腰痛","原因不明の体重減少","長時間の座位で増す痛み","運動翌日の筋肉痛"],"answer":1,"exp":"原因不明の体重減少は、悪性腫瘍などを疑うレッドフラッグの一つです。"},{"level":"基礎","q":"レッドフラッグを認めたときの対応として正しいのはどれか。","options":["運動の強度を下げて続ける","物理療法に切り替える","次回まで様子をみる","治療前に医師へ相談する"],"answer":3,"exp":"レッドフラッグがある場合は、理学療法を進める前に医師へ相談します。"},{"level":"中級","q":"馬尾症候群を疑う所見の組み合わせはどれか。","options":["膀胱直腸障害とサドル領域の感覚消失","頸部痛と肩こり","膝の腫れと階段での痛み","肩の夜間痛と挙上制限"],"answer":0,"exp":"膀胱直腸障害とサドル領域（会陰部・肛門周囲）の感覚消失は、馬尾の圧迫を疑う緊急のサインです。"},{"level":"中級","q":"骨折を最も疑うべき状況はどれか。","options":["デスクワーク後の腰の張り","運動翌日の筋肉痛","骨粗鬆症の人の転倒後の背部痛","寒い日の膝のこわばり"],"answer":2,"exp":"骨粗鬆症がある人は軽い外力でも骨折することがあり、転倒後の痛みは骨折を疑います。"},{"level":"臨床","q":"腰痛の患者が「今朝から尿が出にくく、肛門のまわりがしびれる」と訴えた。対応はどれか。","options":["評価を最後まで続ける","体幹の運動療法を始める","直ちに医師へ連絡する","翌週まで経過をみる"],"answer":2,"exp":"膀胱直腸障害とサドル領域の感覚障害は馬尾症候群を疑う所見で、直ちに医師へ連絡します。"},{"level":"臨床","q":"がんの既往がある68歳男性。1か月前から安静でも軽減しない夜間の背部痛がある。判断はどれか。","options":["姿勢による痛み","医師に相談すべきサイン","筋力強化で改善する痛み","温熱で経過をみる痛み"],"answer":1,"exp":"がんの既往と安静で軽減しない夜間痛の組み合わせは、転移などを否定できず医師への相談が必要です。"}],"seccion":"基礎","grupo":"評価","icono":"📋","mapa":"img/mapas/t06.jpg","fichas":[],"secuencias":[]},"7":{"id":7,"title":"姿勢評価","lead":"姿勢評価は、立位や座位での身体のアライメントを観察し、問題の手がかりを得る評価です。症状との関係は、他の検査で確かめることが前提です。","sheet":{"kind":"basics","items":[{"h":"目的","t":"アライメントの偏りを把握し、筋の短縮や筋力低下、痛みとの関係について仮説を立てます。"},{"h":"側方の基準","t":"理想的な立位では、重心線が耳垂・肩峰・大転子・膝関節前部（膝蓋骨後面）・外果の前方を通るとされます。"},{"h":"後方の観察","t":"頭部の傾き、肩と骨盤の高さ、脊柱の側方偏位、下肢の左右差を観察します。必要に応じて前屈させて確認します。"},{"h":"不良姿勢の例","t":"円背、頭部前方位、骨盤前傾と腰椎前弯の強い姿勢、平背などがあります。関連する筋の短縮や弱化とあわせて評価します。"},{"h":"解釈の注意","t":"姿勢に偏りがあっても症状のない人は多く、所見だけで痛みの原因と決めつけません。可動域や筋力の検査で確かめます。"},{"h":"記録","t":"観察した方向と肢位、ランドマークの位置を記録します。写真を使う場合は、同じ条件で撮影して比較します。"}]},"keypoints":["側方・後方・前方の3方向から観察する","重心線は耳垂・肩峰・大転子を通る","後方では肩と骨盤の高さの左右差を見る","前屈での肋骨隆起は構築性側弯を疑う","姿勢だけで痛みの原因と決めつけない"],"case":{"text":"30歳女性、デスクワーク。頸部痛があり、側方から見ると耳垂が肩峰より明らかに前方にある。","answer":"頭部前方位の所見です。ただし姿勢だけで原因と断定せず、頸部の可動域、症状を再現する動作、しびれや筋力低下などの神経症状を確認します。神経症状があれば医師と連携します。"},"questions":[{"level":"基礎","q":"理想的な立位で、側方からの重心線が通る位置はどれか。","options":["鼻尖","肩甲骨下角","耳垂","踵骨の後端"],"answer":2,"exp":"側方からの重心線は、耳垂・肩峰・大転子・膝関節前部・外果の前方を通るのが理想とされます。"},{"level":"基礎","q":"後方からの観察で主に確認するものはどれか。","options":["頭部前方位","肩と骨盤の高さの左右差","腰椎前弯の程度","膝の過伸展"],"answer":1,"exp":"後方からは、肩と骨盤の高さや脊柱の側方偏位など、左右差を観察します。"},{"level":"中級","q":"理想的な立位で、側方からの重心線について正しいのはどれか。","options":["外果の後方を通る","膝関節の後方を通る","肩甲骨内側縁を通る","大転子を通る"],"answer":3,"exp":"重心線は大転子を通り、膝関節の前部、外果の前方を通るとされます。"},{"level":"中級","q":"姿勢評価の解釈として適切なのはどれか。","options":["偏りがあれば痛みの原因とする","他の検査で症状との関係を確かめる","一方向から観察すれば十分","写真は毎回条件を変えて撮る"],"answer":1,"exp":"姿勢の偏りは症状のない人にもみられるため、可動域や筋力などの検査で関係を確かめます。"},{"level":"臨床","q":"頸部痛の患者で、耳垂が肩峰より明らかに前方にある。次に行うこととして最も適切なのはどれか。","options":["頸部の可動域と神経症状を確認する","姿勢の指導だけを行う","すぐに牽引療法を行う","経過観察とする"],"answer":0,"exp":"頭部前方位は手がかりにすぎません。可動域や神経症状を確認し、症状との関係を評価します。"},{"level":"臨床","q":"後方から見ると肩と骨盤の高さに左右差があり、前屈で片側の肋骨隆起を認めた。疑うものはどれか。","options":["頭部前方位","円背","構築性側弯症","平背"],"answer":2,"exp":"前屈での肋骨隆起は椎体の回旋を伴う構築性側弯症を示唆し、医師の評価につなげます。"}],"seccion":"基礎","grupo":"評価","icono":"📋","mapa":"img/mapas/t07.jpg","fichas":[],"secuencias":[]},"8":{"id":8,"title":"歩行分析","lead":"歩行分析は、歩行周期の各相で関節運動と筋活動を観察し、問題を特定する評価です。転倒予防と動作改善の方針につながります。","sheet":{"kind":"basics","items":[{"h":"歩行周期","t":"一側の初期接地から同側の次の初期接地までを1周期とします。立脚期と遊脚期に分かれ、両脚支持期を2回含みます。"},{"h":"相の区分","t":"立脚期は初期接地・荷重応答期・立脚中期・立脚終期・前遊脚期、遊脚期は遊脚初期・遊脚中期・遊脚終期に分けます。"},{"h":"観察の手順","t":"前方・後方・側方から観察し、一度に1つの関節や相に注目します。歩行速度、歩幅、リズム、補助具の使用も記録します。"},{"h":"代表的な異常","t":"トレンデレンブルグ歩行（中殿筋）、鶏歩（下垂足の代償）、分回し歩行、すくみ足、小刻み歩行などがあります。"},{"h":"筋活動の要点","t":"荷重応答期は大腿四頭筋が膝の屈曲を、前脛骨筋が足部の下降を遠心性に制御します。立脚終期は下腿三頭筋が働きます。"},{"h":"数値での評価","t":"10m歩行テストやTUGで速度や移動能力を数値化します。観察結果とあわせて、転倒リスクも判断します。"}]},"keypoints":["1周期は初期接地から同側の次の初期接地まで","立脚期は約60％、遊脚期は約40％","観察は3方向から、一度に1か所に注目","トレンデレンブルグ歩行は中殿筋を疑う","鶏歩は下垂足（前脛骨筋の弱化）の代償"],"case":{"text":"60歳男性、腓骨神経麻痺。遊脚期に股関節と膝関節を大きく屈曲し、足を高く持ち上げて歩く。つまずきが増えている。","answer":"下垂足を代償する鶏歩です。足関節背屈の筋力、感覚、転倒リスクを評価します。装具の検討は医師・義肢装具士と連携して行い、自己判断で決めないようにします。"},"questions":[{"level":"基礎","q":"1歩行周期のうち、立脚期が占めるおおよその割合はどれか。","options":["約40％","約50％","約60％","約80％"],"answer":2,"exp":"通常の歩行では立脚期が約60％、遊脚期が約40％を占めます。"},{"level":"基礎","q":"片脚で体重を支え、身体重心が最も高くなる相はどれか。","options":["初期接地","立脚中期","前遊脚期","遊脚中期"],"answer":1,"exp":"立脚中期は支持脚の真上を身体が通過する時期で、重心が最も高くなります。"},{"level":"中級","q":"荷重応答期に膝関節の屈曲を遠心性に制御する主な筋はどれか。","options":["大腿四頭筋","ハムストリングス","腸腰筋","下腿三頭筋"],"answer":0,"exp":"荷重応答期は膝が軽く屈曲して衝撃を吸収し、大腿四頭筋が遠心性に制御します。"},{"level":"中級","q":"トレンデレンブルグ歩行で弱化が疑われる筋はどれか。","options":["大殿筋","大腿四頭筋","前脛骨筋","中殿筋"],"answer":3,"exp":"中殿筋の筋力低下では、立脚期に遊脚側の骨盤が下がるトレンデレンブルグ徴候がみられます。"},{"level":"臨床","q":"遊脚期に股・膝関節を過度に屈曲し、足を高く上げて歩く。考えられる原因はどれか。","options":["大腿四頭筋の筋力低下","前脛骨筋の筋力低下","中殿筋の筋力低下","大殿筋の筋力低下"],"answer":1,"exp":"前脛骨筋の弱化による下垂足で、つま先が床に引っかからないよう脚を高く上げる鶏歩になります。"},{"level":"臨床","q":"パーキンソン病の患者で、歩き始めや方向転換のときに足が床に貼りついたように出なくなる。この現象はどれか。","options":["分回し歩行","鶏歩","すくみ足","動揺性歩行"],"answer":2,"exp":"すくみ足はパーキンソン病に特徴的で、歩き始めや方向転換、狭い場所で起こりやすい現象です。"}],"seccion":"基礎","grupo":"評価","icono":"📋","mapa":"img/mapas/t08.jpg","fichas":[],"secuencias":[]},"9":{"id":9,"title":"神経学的検査","lead":"神経学的検査は、感覚・筋力・反射を髄節ごとに調べ、障害の部位とレベルを推定する評価です。進行する神経症状の早期発見にも欠かせません。","sheet":{"kind":"basics","items":[{"h":"目的","t":"感覚・筋力・反射の所見を組み合わせ、末梢神経、神経根、脊髄、脳のどこに障害があるかを推定します。"},{"h":"感覚検査","t":"触覚、痛覚、温度覚、位置覚、振動覚を調べ、デルマトームに沿って左右・上下で比較します。"},{"h":"髄節の代表筋","t":"C5は肩外転、C6は手関節背屈、C7は肘伸展、L4は足関節背屈、L5は母趾伸展、S1は足関節底屈が代表的です。"},{"h":"深部腱反射","t":"上腕二頭筋腱反射（C5）、腕橈骨筋反射（C6）、上腕三頭筋腱反射（C7）、膝蓋腱反射（L4）、アキレス腱反射（S1）が基本です。"},{"h":"上位と下位","t":"上位運動ニューロン障害では腱反射亢進や病的反射、下位運動ニューロン障害では腱反射の低下・消失と筋萎縮がみられます。"},{"h":"注意点","t":"急に進む筋力低下、広がる感覚障害、膀胱直腸障害は速やかに医師へ連絡します。所見は経時的に記録します。"}]},"keypoints":["感覚・筋力・反射を必ず左右で比較する","膝蓋腱反射はL4、アキレス腱反射はS1","L5は母趾伸展の筋力と感覚で判断する","反射亢進・病的反射は上位運動ニューロン","進行する筋力低下はすぐ医師へ連絡する"],"case":{"text":"50歳男性、腰痛と右下腿外側から足背のしびれ。右の母趾伸展筋力が低下し、膝蓋腱反射とアキレス腱反射に左右差はない。","answer":"L5神経根の障害が疑われます。L5には代表的な腱反射がないため、感覚と母趾伸展の筋力で判断します。筋力低下が進む場合や膀胱直腸障害が出た場合は、直ちに医師へ連絡します。"},"questions":[{"level":"基礎","q":"上位運動ニューロン障害を示唆する病的反射はどれか。","options":["膝蓋腱反射","腹壁反射","バビンスキー反射","角膜反射"],"answer":2,"exp":"バビンスキー反射は足底をこすると母趾が背屈する病的反射で、上位運動ニューロン障害を示唆します。"},{"level":"基礎","q":"デルマトームに沿って左右を比較する検査はどれか。","options":["腱反射","感覚検査","MMT","ROM測定"],"answer":1,"exp":"デルマトームは各髄節が支配する皮膚の領域で、感覚検査で左右・上下を比較します。"},{"level":"中級","q":"アキレス腱反射が主に反映する髄節はどれか。","options":["L3","L4","L5","S1"],"answer":3,"exp":"アキレス腱反射は主にS1、膝蓋腱反射は主にL4を反映します。"},{"level":"中級","q":"下位運動ニューロン障害の所見として正しいのはどれか。","options":["腱反射亢進","病的反射陽性","筋萎縮","痙縮"],"answer":2,"exp":"下位運動ニューロン障害では、腱反射の低下・消失、筋萎縮、筋緊張低下がみられます。"},{"level":"臨床","q":"下腿外側から足背のしびれと母趾伸展の筋力低下があり、腱反射に左右差はない。障害レベルはどれか。","options":["L3","L4","L5","S1"],"answer":2,"exp":"下腿外側〜足背の感覚と母趾伸展はL5の所見です。L5には代表的な腱反射がありません。"},{"level":"臨床","q":"頸部痛と両手のしびれに加え、下肢の腱反射亢進とバビンスキー反射陽性を認めた。疑うものはどれか。","options":["頸髄の障害（脊髄症）","単一神経根の障害","手根管症候群","筋膜性の痛み"],"answer":0,"exp":"下肢の反射亢進と病的反射は上位運動ニューロン障害で、頸髄の圧迫などを疑い医師へつなげます。"}],"seccion":"基礎","grupo":"評価","icono":"📋","mapa":"img/mapas/t09.jpg","fichas":[],"secuencias":[]},"10":{"id":10,"title":"腱板","lead":"腱板は肩関節を安定させる4つの筋の腱です。どの筋が傷んでいるかをテストで見分けることが、評価と運動療法の出発点になります。","sheet":{"kind":"tests","tests":[{"name":"ジョーブテスト","alias":"エンプティカンテスト","steps":"肩甲骨面で肩を90°外転し、母指を下に向けた内旋位で保持させ、検者が上から下へ抵抗を加える。","positive":"痛み、または抵抗に抗して保持できない筋力低下","tissue":"棘上筋","point":"痛みと筋力低下を分けて記録する。インピンジメントでも痛みが出る点に注意。"},{"name":"外旋抵抗テスト","alias":"","steps":"肘90°屈曲・上腕下垂位で、外旋しようとする前腕に検者が内側へ向けて抵抗を加える。","positive":"外旋時の痛み、または健側より明らかな筋力低下","tissue":"棘下筋・小円筋","point":"他動で外旋位に置いても保持できない（外旋ラグ）場合は大きな断裂を疑う。"},{"name":"リフトオフテスト","alias":"ガーバー・リフトオフテスト","steps":"手の甲を腰部に当てた肢位から、手を背中から後方へ離すよう指示する。","positive":"手を背中から離せない、または痛みが出る","tissue":"肩甲下筋","point":"内旋の可動域が不足し手が背中に回らない場合は、ベリープレステストで代用する。"},{"name":"ドロップアームテスト","alias":"","steps":"検者が肩を他動的に約90°外転位まで挙上し、そこから患者にゆっくり腕を下ろさせる。","positive":"途中で保持できず腕が落下する、または強い痛み","tissue":"腱板（主に棘上筋）の断裂","point":"大きな断裂を示唆する所見。単独で断定せず、他のテストや画像所見と合わせる。"}]},"keypoints":["痛みと筋力低下を分けて記録し、必ず健側と比べる","ジョーブは肩甲骨面・母指下向きで棘上筋をみる","外旋抵抗は棘下筋・小円筋、リフトオフは肩甲下筋","1つのテストで断定せず、複数の所見を組み合わせる","外傷後に急に挙上できない例は医師の評価へつなぐ"],"case":{"text":"58歳男性。転倒して右手をついた後から右肩が挙がらない。他動の可動域はほぼ保たれるが自動挙上は困難。ジョーブテストで筋力低下、ドロップアームテスト陽性。","answer":"他動可動域が保たれ自動運動のみ困難なことから、拘縮より腱板断裂を疑う。テストだけで断定せず医師の診察・画像検査につなぐ。痛みを誘発する強い抵抗運動の反復は避ける。"},"questions":[{"level":"基礎","q":"ジョーブテスト（肩甲骨面で90°、母指を下に）で主に評価する筋はどれか。","options":["棘上筋","棘下筋","肩甲下筋","小円筋"],"answer":0,"exp":"肩甲骨面で90°外転し母指を下に向けた肢位で抵抗を加え、棘上筋を評価する。"},{"level":"基礎","q":"手の甲を腰に当てて離すガーバー・リフトオフテストで評価する筋はどれか。","options":["大円筋","棘上筋","肩甲下筋","三角筋"],"answer":2,"exp":"手を背中から離す動作は肩の内旋で、主な内旋筋である肩甲下筋を評価する。"},{"level":"中級","q":"肘90°屈曲・上腕下垂位で抵抗に抗した外旋を行うテストで評価するのはどれか。","options":["棘上筋のみ","棘下筋・小円筋","肩甲下筋","上腕二頭筋長頭"],"answer":1,"exp":"抵抗に抗した外旋は、外旋筋である棘下筋と小円筋の痛み・筋力低下をみる。"},{"level":"中級","q":"ドロップアームテスト陽性が示唆するものとして最も適切なのはどれか。","options":["肩関節前方不安定性","上腕二頭筋長頭腱炎","肩鎖関節の障害","腱板の断裂"],"answer":3,"exp":"挙上位から腕をゆっくり下ろせず落下するのは、腱板（主に棘上筋）の断裂を示唆する。"},{"level":"臨床","q":"62歳女性。手を背中に回せるが、背中から後方へ離せない。外旋抵抗は正常。最も疑われる損傷部位はどれか。","options":["棘上筋","肩甲下筋","棘下筋","小円筋"],"answer":1,"exp":"リフトオフテスト陽性で外旋は正常。内旋筋である肩甲下筋の障害を最も疑う。"},{"level":"臨床","q":"65歳男性、肩の挙上困難。他動可動域は保たれ、ジョーブテストで著明な筋力低下。最も適切な対応はどれか。","options":["最大抵抗の筋力強化を始める","医師へ情報提供し評価を依頼","強いストレッチを繰り返す","様子を見るよう伝える"],"answer":1,"exp":"腱板断裂が疑われ、診断と方針決定には医師の評価・画像検査が必要。強い負荷は避ける。"}],"seccion":"部位別の特殊テスト","grupo":"肩関節","icono":"💪","mapa":"img/mapas/t10.jpg","fichas":[{"nombre":"ジョーブテスト","img":"img/fichas/jobe.jpg"}],"secuencias":[{"nombre":"ジョーブテスト","rotulo":"評価","texto":"棘上筋","frames":["img/mov/teste-jobe-1.jpg","img/mov/teste-jobe-2.jpg","img/mov/teste-jobe-3.jpg"]}]},"11":{"id":11,"title":"インピンジメント・不安定性","lead":"挙上時の痛みは肩峰下での挟み込み、外旋時の不安感は前方不安定性を示します。痛みと不安感を区別して評価することが大切です。","sheet":{"kind":"tests","tests":[{"name":"ニアーテスト","alias":"ニアーインピンジメントサイン","steps":"肩甲骨を上から押さえて固定し、肩内旋位のまま上肢を他動的に前方へ最大挙上する。","positive":"挙上時の肩前上方の痛み","tissue":"肩峰下の腱板・滑液包","point":"大結節が肩峰下に押し込まれて痛みが出る。陽性でも断裂の有無は判別できない。"},{"name":"ホーキンステスト","alias":"ホーキンス・ケネディテスト","steps":"肩・肘を90°屈曲位とし、検者が前腕を下方へ押して肩を他動的に内旋させる。","positive":"内旋時の肩前上方〜外側の痛み","tissue":"棘上筋腱・肩峰下滑液包","point":"ニアーテストと組み合わせて判断する。痛みの部位と再現性を確認する。"},{"name":"アプリヘンションテスト","alias":"前方不安感テスト","steps":"背臥位で肩90°外転・肘90°屈曲とし、検者がゆっくり肩を外旋していく。","positive":"脱臼しそうな不安感、防御的な筋収縮","tissue":"肩関節前方の関節包・関節唇","point":"陽性は痛みではなく不安感で判断する。脱臼歴のある例ではゆっくり愛護的に行う。"},{"name":"リロケーションテスト","alias":"","steps":"アプリヘンションテストの肢位で、上腕骨頭を前方から後方へ押さえながら外旋する。","positive":"不安感が軽減し、さらに外旋できる","tissue":"肩関節前方の不安定性","point":"アプリヘンションテストに続けて行い、不安感の変化で前方不安定性を裏づける。"}]},"keypoints":["ニアーとホーキンスは肩峰下での挟み込みの痛みをみる","不安定性のテストは痛みより不安感の出現を重視する","陽性でも腱板断裂の有無や程度は判別できない","脱臼歴がある例では外旋の強制をゆっくり行う","問診・他のテスト・画像所見と統合して判断する"],"case":{"text":"19歳男性、ラグビー選手。タックルで腕を外転外旋位に強制されて以来、同じ肢位で「抜けそう」と訴える。アプリヘンションテストで不安感があり、リロケーションテストで軽減する。","answer":"肩関節前方不安定性を疑う所見で、インピンジメントの痛みとは区別する。外転外旋位を強制する動作は避け、医師の評価を前提に腱板・肩甲骨周囲筋の安定化から進める。"},"questions":[{"level":"基礎","q":"肩峰下インピンジメントで挟み込まれやすい構造はどれか。","options":["上腕三頭筋腱","大円筋","棘上筋腱","広背筋"],"answer":2,"exp":"挙上時に肩峰の下で棘上筋腱や肩峰下滑液包が挟み込まれ、痛みが出る。"},{"level":"基礎","q":"ホーキンステストで肩に加える運動はどれか。","options":["90°屈曲位での内旋","下垂位での外旋","水平外転","伸展"],"answer":0,"exp":"肩・肘90°屈曲位から肩を他動的に内旋し、大結節を烏口肩峰アーチ下に押し込む。"},{"level":"中級","q":"アプリヘンションテストの陽性所見はどれか。","options":["挙上時の肩前上方の痛み","脱臼しそうな不安感","肘屈曲時の痛み","腕の落下"],"answer":1,"exp":"外転外旋位で脱臼しそうな不安感や防御的な筋収縮が出れば陽性で、前方不安定性を示す。"},{"level":"中級","q":"リロケーションテストで不安感が軽減した場合に示唆されるのはどれか。","options":["腱板断裂","肩鎖関節障害","凍結肩","肩関節前方不安定性"],"answer":3,"exp":"骨頭を後方へ押さえると不安感が減ることは、前方不安定性を裏づける所見となる。"},{"level":"臨床","q":"45歳男性、頭上作業で肩前上方が痛む。ニアーとホーキンスで痛みがあり、筋力は保たれる。最も考えられるのはどれか。","options":["前方不安定性","肩峰下インピンジメント","頸椎神経根症","肩鎖関節脱臼"],"answer":1,"exp":"挙上・内旋での肩前上方の痛みと保たれた筋力から、肩峰下インピンジメントが最も考えられる。"},{"level":"臨床","q":"20歳女性、肩の前方脱臼を2回経験。アプリヘンションテストを行う際に最も適切なのはどれか。","options":["素早く最大外旋まで強制する","不安感が出た時点で止める","痛みが出るまで外旋を続ける","反動をつけて行う"],"answer":1,"exp":"目的は不安感の確認であり、出た時点で中止する。強制すると再脱臼の危険がある。"}],"seccion":"部位別の特殊テスト","grupo":"肩関節","icono":"💪","mapa":"img/mapas/t11.jpg","fichas":[{"nombre":"ニアーテスト","img":"img/fichas/neer.jpg"},{"nombre":"ホーキンステスト","img":"img/fichas/hawkins.jpg"}],"secuencias":[]},"12":{"id":12,"title":"上腕二頭筋・関節唇","lead":"上腕二頭筋長頭腱は結節間溝を通って上方関節唇に付きます。投球やけん引で痛めやすく、腱と関節唇を区別して評価します。","sheet":{"kind":"tests","tests":[{"name":"スピードテスト","alias":"","steps":"肘伸展・前腕回外位で肩を前方へ挙上させ、検者が前腕に下方への抵抗を加える。","positive":"結節間溝部の痛み","tissue":"上腕二頭筋長頭腱","point":"上方関節唇の損傷でも痛みが出ることがある。圧痛の部位と合わせて判断する。"},{"name":"ヤーガソンテスト","alias":"","steps":"肘90°屈曲・前腕回内位から、検者の抵抗に抗して前腕を回外させる。","positive":"結節間溝部の痛み、または腱が外れる感覚","tissue":"上腕二頭筋長頭腱・横上腕靭帯","point":"腱の亜脱臼ではクリック感を伴うことがある。痛みの部位を必ず確認する。"},{"name":"オブライエンテスト","alias":"アクティブ・コンプレッションテスト","steps":"肩90°屈曲・軽度水平内転・母指下向きで下方へ抵抗し、次に手掌を上に向けて繰り返す。","positive":"母指下向きで深部痛やクリック、手掌上向きで軽減","tissue":"上方関節唇・肩鎖関節","point":"肩上部の痛みは肩鎖関節、肩の深部の痛みは関節唇を示唆する。部位を区別する。"},{"name":"クランクテスト","alias":"","steps":"肩を大きく挙上した位置で、上腕骨の長軸方向に圧を加えながら内旋・外旋する。","positive":"痛みやクリック（引っかかり感）の再現","tissue":"関節唇","point":"関節唇損傷はテスト単独では確定しにくく、画像所見と合わせて判断する。"}]},"keypoints":["長頭腱は結節間溝を通り関節上結節と上方関節唇に付く","スピードとヤーガソンは結節間溝部の痛みを確認する","オブライエンは痛みの部位で関節唇と肩鎖関節を区別","クリックや引っかかり感の有無も記録する","関節唇損傷はテストのみで確定せず画像と統合する"],"case":{"text":"22歳男性、野球の投手。投球時に肩深部の痛みと引っかかり感。オブライエンテストで母指下向き時に深部痛があり、手掌上向きで軽減。スピードテストでも痛みがある。","answer":"上方関節唇（SLAP）損傷を疑う。肩上部の痛みなら肩鎖関節由来を考える。投球継続の可否は独断せず医師につなぎ、痛みを誘発する投球動作は控えるよう伝える。"},"questions":[{"level":"基礎","q":"上腕二頭筋長頭腱が通る溝はどれか。","options":["関節窩","結節間溝","橈骨神経溝","肩峰"],"answer":1,"exp":"長頭腱は上腕骨の大結節と小結節の間にある結節間溝を通り、関節内へ入る。"},{"level":"基礎","q":"上腕二頭筋長頭腱が関節上結節とともに付着する構造はどれか。","options":["上方関節唇","下関節上腕靭帯","肩鎖靭帯","烏口鎖骨靭帯"],"answer":0,"exp":"長頭腱は関節上結節と上方関節唇に付くため、腱の障害と関節唇損傷が合併しやすい。"},{"level":"中級","q":"ヤーガソンテストで抵抗を加える運動はどれか。","options":["肩外転","手関節背屈","前腕回外","肘伸展"],"answer":2,"exp":"肘90°屈曲位で前腕の回外に抵抗を加え、結節間溝部の痛みで長頭腱の障害をみる。"},{"level":"中級","q":"オブライエンテストで肩上部の痛みが出た場合に疑うのはどれか。","options":["上方関節唇損傷","肩鎖関節の障害","腱板断裂","前方不安定性"],"answer":1,"exp":"肩上部の痛みは肩鎖関節、肩の深部の痛みは上方関節唇の損傷を示唆する。"},{"level":"臨床","q":"25歳男性、バレーボール選手。スパイク時に肩深部の痛みとクリック。オブライエンテストで深部痛。最も疑われるのはどれか。","options":["肩鎖関節障害","凍結肩","頸椎症","SLAP損傷"],"answer":3,"exp":"オーバーヘッド動作での深部痛・クリックとオブライエン陽性（深部痛）からSLAP損傷を疑う。"},{"level":"臨床","q":"40歳男性。重い物を持ち上げた際に上腕前面で断裂音があり、力こぶが下方へ移動した。最も適切な対応はどれか。","options":["最大抵抗の筋力強化を行う","ヤーガソンテストを反復する","医師の診察につなぐ","温めて様子を見る"],"answer":2,"exp":"長頭腱断裂が疑われる所見で、まず医師の診察が必要。負荷をかける評価・運動は避ける。"}],"seccion":"部位別の特殊テスト","grupo":"肩関節","icono":"💪","mapa":"img/mapas/t12.jpg","fichas":[],"secuencias":[]},"13":{"id":13,"title":"肘関節","lead":"肘の痛みは外側の伸筋群、内側の屈筋群と靭帯、そして尺骨神経に分けて考えます。痛む部位とテストを結びつけて評価します。","sheet":{"kind":"tests","tests":[{"name":"トムセンテスト","alias":"","steps":"肘伸展位・手関節軽度背屈位で拳を握らせ、検者が手背を掌屈方向へ押して抵抗を加える。","positive":"上腕骨外側上顆周囲の痛み","tissue":"短橈側手根伸筋の起始部","point":"上腕骨外側上顆炎の評価。中指伸展テストやチェアテストと組み合わせる。"},{"name":"中指伸展テスト","alias":"","steps":"肘伸展位で中指を伸展させ、検者が中指の基節部を掌側へ押して抵抗を加える。","positive":"上腕骨外側上顆周囲の痛み","tissue":"短橈側手根伸筋・総指伸筋の起始部","point":"トムセンテストと同様に外側上顆炎で陽性となる。痛みの再現部位を確認する。"},{"name":"外反ストレステスト","alias":"","steps":"肘を軽度屈曲位とし、上腕を固定して前腕に外反方向のストレスを加える。","positive":"肘内側の痛み、または健側より大きい動揺性","tissue":"内側側副靭帯","point":"投球障害肘の評価で用いる。必ず健側と比較し、痛みと動揺性を分けて記録する。"},{"name":"ティネル徴候（肘部管）","alias":"","steps":"内側上顆と肘頭の間にある肘部管を、指先や打腱器で軽く叩打する。","positive":"小指・環指尺側へ放散するしびれ","tissue":"尺骨神経（肘部管）","point":"肘部管症候群の評価。肘屈曲テストやフローマン徴候と合わせて判断する。"}]},"keypoints":["外側上顆の痛みは手関節・手指伸筋の起始部を疑う","外反ストレスは軽度屈曲位で行い、健側と比較する","尺骨神経の症状は小指・環指尺側のしびれで確認する","痛みと動揺性（不安定性）を分けて記録する","しびれの持続や手内筋の萎縮は医師につなぐサイン"],"case":{"text":"45歳女性、事務職。タオルを絞る、カバンを持ち上げると肘外側が痛む。外側上顆に圧痛があり、トムセンテストと中指伸展テストで痛みが再現する。","answer":"上腕骨外側上顆炎を疑う所見。痛みを誘発する把持動作の反復を控え、負荷を調整する。しびれや腫脹、夜間の強い痛みを伴う場合は他の疾患も考え医師につなぐ。"},"questions":[{"level":"基礎","q":"上腕骨外側上顆に起始する筋群はどれか。","options":["手関節屈筋群","手関節伸筋群","上腕二頭筋","円回内筋"],"answer":1,"exp":"外側上顆には手関節・手指の伸筋群が起始し、内側上顆には屈筋群と円回内筋が起始する。"},{"level":"基礎","q":"肘部管を通る神経はどれか。","options":["正中神経","橈骨神経","尺骨神経","筋皮神経"],"answer":2,"exp":"尺骨神経は内側上顆の後方にある肘部管を通るため、肘内側の叩打で小指側にしびれが出る。"},{"level":"中級","q":"トムセンテストで抵抗を加える運動はどれか。","options":["手関節背屈","手関節掌屈","前腕回内","肘屈曲"],"answer":0,"exp":"手関節背屈に抵抗を加え、伸筋群起始部である外側上顆周囲の痛みの再現をみる。"},{"level":"中級","q":"外反ストレステストで主に評価する組織はどれか。","options":["外側側副靭帯","輪状靭帯","橈骨頭","内側側副靭帯"],"answer":3,"exp":"前腕に外反ストレスを加えると肘内側が引き伸ばされ、内側側副靭帯の痛み・動揺性をみる。"},{"level":"臨床","q":"14歳男子、野球の投手。投球時に肘内側の痛み。外反ストレスで内側に痛みが出る。最も疑われるのはどれか。","options":["上腕骨外側上顆炎","内側型野球肘","肘内障","橈骨頭骨折"],"answer":1,"exp":"投球動作の反復と外反ストレスでの内側痛から、内側型野球肘（内側の靭帯・骨端の障害）を疑う。"},{"level":"臨床","q":"50歳男性。肘内側を叩くと小指にしびれが走り、手指の細かい動作もしにくい。最も適切な対応はどれか。","options":["肘を長時間屈曲位に保つ","しびれは様子を見る","医師に情報提供する","肘内側を強く揉む"],"answer":2,"exp":"尺骨神経障害で巧緻性低下を伴う例は医師の評価が必要。肘の持続屈曲や圧迫は症状を悪化させる。"}],"seccion":"部位別の特殊テスト","grupo":"肘・手関節・手","icono":"✋","mapa":"img/mapas/t13.jpg","fichas":[],"secuencias":[]},"14":{"id":14,"title":"手関節・手","lead":"手のしびれや痛みは、どの神経・腱が関わるかを分布から推定します。手根管症候群や腱鞘炎は臨床でも国試でも頻出です。","sheet":{"kind":"tests","tests":[{"name":"ファーレンテスト","alias":"ファレンテスト","steps":"両手の手背を合わせて手関節を最大掌屈位に一定時間保持し、しびれの出現を観察する。","positive":"母指〜環指橈側のしびれの出現・増悪","tissue":"正中神経（手根管）","point":"手根管症候群の評価。しびれの範囲が正中神経領域に一致するかを確認する。"},{"name":"ティネル徴候（手関節）","alias":"ティネルサイン","steps":"手関節掌側の手根管部を、指先や打腱器で軽く叩打する。","positive":"正中神経領域の指先へ放散するしびれ","tissue":"正中神経（手根管）","point":"神経の圧迫部位や再生の推定にも用いる。叩打は強くしすぎない。"},{"name":"フィンケルシュタインテスト","alias":"","steps":"母指を他の指で握り込ませ（または検者が母指を把持し）、手関節を他動的に尺屈させる。","positive":"橈骨茎状突起部の強い痛み","tissue":"長母指外転筋・短母指伸筋腱","point":"ドケルバン病の評価。握り込み法はアイヒホッフテストとも呼ばれる。健側と比較する。"},{"name":"フローマン徴候","alias":"","steps":"両手の母指と示指で紙を挟ませ、検者が紙を引き抜くように引っ張る。","positive":"母指IP関節が屈曲して紙を保持しようとする","tissue":"尺骨神経（母指内転筋）","point":"母指内転筋の筋力低下を、正中神経支配の長母指屈筋で代償する現象をみる。"}]},"keypoints":["しびれの分布で正中・尺骨・橈骨神経を区別する","ファーレンとティネルは手根管での正中神経をみる","フィンケルシュタインは母指の腱鞘炎の評価に用いる","両側で実施し、健側と比較して判断する","母指球筋の萎縮や持続するしびれは医師につなぐ"],"case":{"text":"52歳女性。明け方に母指〜中指がしびれ、手を振ると楽になる。ファーレンテストで同じ部位にしびれが出現し、手根管部のティネル徴候も陽性。","answer":"手根管症候群を疑う。しびれが小指に及ぶ、頸部の動きで変化する場合は他の部位も考える。母指球の萎縮や筋力低下があれば医師につなぎ、手関節の強い圧迫は避ける。"},"questions":[{"level":"基礎","q":"手根管を通る神経はどれか。","options":["尺骨神経","正中神経","橈骨神経","筋皮神経"],"answer":1,"exp":"手根管は屈筋腱と正中神経が通るトンネルで、ここでの圧迫が手根管症候群となる。"},{"level":"基礎","q":"フィンケルシュタインテストで痛みが出る部位はどれか。","options":["橈骨茎状突起部","尺骨茎状突起部","豆状骨部","第5中手骨頭"],"answer":0,"exp":"母指の腱（長母指外転筋・短母指伸筋）が通る橈骨茎状突起部に痛みが出る。"},{"level":"中級","q":"フローマン徴候で評価する神経はどれか。","options":["正中神経","橈骨神経","腋窩神経","尺骨神経"],"answer":3,"exp":"尺骨神経支配の母指内転筋が弱いと、長母指屈筋で代償し母指IP関節が屈曲する。"},{"level":"中級","q":"ファーレンテストの陽性所見はどれか。","options":["小指のしびれ","手背全体の痛み","母指〜環指橈側のしびれ","手関節の不安定感"],"answer":2,"exp":"手関節の掌屈保持で手根管内圧が高まり、正中神経領域（母指〜環指橈側）にしびれが出る。"},{"level":"臨床","q":"30歳女性。出産後、育児で母指を使うと手関節の母指側が痛む。母指を握り込んで尺屈すると痛む。最も疑われるのはどれか。","options":["手根管症候群","三角線維軟骨複合体損傷","ドケルバン病","ばね指"],"answer":2,"exp":"母指の使いすぎと、握り込み尺屈での橈骨茎状突起部痛から、ドケルバン病を疑う。"},{"level":"臨床","q":"60歳男性。小指と環指尺側にしびれがあり、紙を挟むと母指IP関節が屈曲する。障害が疑われる神経はどれか。","options":["正中神経","橈骨神経","後骨間神経","尺骨神経"],"answer":3,"exp":"小指・環指尺側のしびれとフローマン徴候陽性は、尺骨神経障害を示す所見である。"}],"seccion":"部位別の特殊テスト","grupo":"肘・手関節・手","icono":"✋","mapa":"img/mapas/t14.jpg","fichas":[{"nombre":"ファーレンテスト","img":"img/fichas/phalen.jpg"},{"nombre":"フィンケルシュタインテスト","img":"img/fichas/finkelstein.jpg"},{"nombre":"ティネル徴候（手関節）","img":"img/fichas/tinel-punho.jpg"}],"secuencias":[]},"15":{"id":15,"title":"頸椎","lead":"頸部から腕への痛み・しびれは神経根の圧迫で起こることがあります。誘発と軽減の両方のテストで、神経根症状かを確かめます。","sheet":{"kind":"tests","tests":[{"name":"スパーリングテスト","alias":"椎間孔圧迫テスト","steps":"座位で頸部を患側へ側屈（軽度伸展・回旋）させ、検者が頭頂部から下方へ圧迫を加える。","positive":"患側上肢への放散痛・しびれの再現","tissue":"頸部神経根（椎間孔部）","point":"頸部痛のみの再現は陽性としない。強い痛みやめまいが出たら直ちに中止する。"},{"name":"ジャクソンテスト","alias":"ジャクソン圧迫テスト","steps":"座位で頸部を軽度伸展位とし、検者が頭頂部から下方へ圧迫を加える。","positive":"上肢への放散痛・しびれの再現","tissue":"頸部神経根","point":"伸展で椎間孔が狭くなることを利用する。スパーリングテストと組み合わせる。"},{"name":"頸椎牽引テスト","alias":"ディストラクションテスト","steps":"座位で検者が下顎と後頭部を支え、頭部を上方へゆっくり牽引する。","positive":"上肢の放散痛・しびれが軽減する","tissue":"頸部神経根（椎間孔での圧迫）","point":"軽減すれば陽性。牽引で症状が悪化する場合は他の要因も考えて中止する。"},{"name":"肩外転テスト","alias":"バコディ徴候","steps":"座位で患側の手を頭の上に乗せる肢位をとらせ、上肢症状の変化をみる。","positive":"上肢の放散痛・しびれが軽減する","tissue":"頸部神経根","point":"神経根の緊張が緩み症状が和らぐ。患者が自然にこの姿勢をとっていることもある。"}]},"keypoints":["上肢への放散痛・しびれの再現で神経根症状と判断","圧迫テストは愛護的に行い、強い症状が出たら中止","牽引や肩外転で症状が軽くなるかも確認する","皮膚分節・筋力・腱反射と合わせて障害高位を推定","両手のしびれや歩行障害は脊髄症を疑い医師へ"],"case":{"text":"48歳男性、デスクワーク。頸部痛と右母指〜前腕外側のしびれ。スパーリングテストで右上肢にしびれが再現し、頭部の牽引で軽減する。","answer":"頸部神経根症を疑い、しびれの分布からC6領域が考えられる。腱反射・筋力も確認する。両手の巧緻性低下や歩行障害があれば脊髄症を疑い医師へつなぐ。強い圧迫の反復は避ける。"},"questions":[{"level":"基礎","q":"スパーリングテストで頭部を圧迫する際の頸部の肢位はどれか。","options":["患側への側屈","健側への側屈","最大屈曲","中間位で牽引"],"answer":0,"exp":"患側へ側屈（軽度伸展）させて椎間孔を狭め、頭部を圧迫して神経根症状を誘発する。"},{"level":"基礎","q":"頸部の伸展・患側側屈で狭くなり、神経根を圧迫しやすい部位はどれか。","options":["椎体前縁","椎間孔","棘突起間","横突起先端"],"answer":1,"exp":"神経根は椎間孔を通って出るため、伸展・側屈で椎間孔が狭まると圧迫されやすい。"},{"level":"中級","q":"頸椎牽引テストの陽性所見はどれか。","options":["上肢症状の増悪","めまいの出現","上肢症状の軽減","頸部の可動域増大"],"answer":2,"exp":"牽引で椎間孔が広がり、神経根の圧迫が減って上肢の痛み・しびれが軽くなれば陽性。"},{"level":"中級","q":"スパーリングテストを陽性と判断する所見はどれか。","options":["頸部のみの痛み","肩のこり感","頸部の筋緊張","患側上肢への放散痛"],"answer":3,"exp":"陽性は上肢への放散痛・しびれの再現。頸部局所の痛みのみでは陽性としない。"},{"level":"臨床","q":"50歳女性、頸部痛と左中指のしびれ。左上腕三頭筋腱反射が低下している。最も疑われる神経根はどれか。","options":["C5","C6","C7","C8"],"answer":2,"exp":"中指の感覚障害と上腕三頭筋腱反射の低下はC7神経根の障害を示す。"},{"level":"臨床","q":"65歳男性。両手のしびれとボタン掛けの困難があり、歩くとふらつく。最も適切な対応はどれか。","options":["医師に情報提供する","頸部を強く牽引する","スパーリングを繰り返す","頸部の徒手矯正を行う"],"answer":0,"exp":"両側の手指巧緻性低下と歩行障害は頸髄症を疑うサイン。誘発テストを控え医師へつなぐ。"}],"seccion":"部位別の特殊テスト","grupo":"脊椎・骨盤","icono":"🦴","mapa":"img/mapas/t15.jpg","fichas":[],"secuencias":[]},"16":{"id":16,"title":"腰椎","lead":"腰痛に下肢の痛みやしびれを伴うときは、神経根の関与を評価します。テストの再現症状と神経学的所見から障害高位を推定します。","sheet":{"kind":"tests","tests":[{"name":"SLRテスト","alias":"下肢伸展挙上テスト（ラセーグ徴候）","steps":"背臥位で膝伸展位のまま、検者が下肢をゆっくり他動的に挙上する。","positive":"殿部〜下腿への放散痛・しびれの再現","tissue":"L5・S1神経根、坐骨神経","point":"大腿後面のつっぱり感はハムストリングスの伸張と区別する。角度と症状を記録する。"},{"name":"大腿神経伸張テスト","alias":"FNSテスト","steps":"腹臥位で膝を他動的に屈曲し、必要に応じて股関節を伸展させる。","positive":"大腿前面への放散痛","tissue":"上位腰椎神経根（L2〜L4）、大腿神経","point":"大腿四頭筋の伸張痛や股関節由来の痛みと区別する。"},{"name":"ケンプテスト","alias":"","steps":"立位または座位で、検者が体幹を後方に伸展させながら患側へ側屈・回旋させる。","positive":"腰部痛、または患側下肢への放散痛","tissue":"椎間関節・神経根（椎間孔部）","point":"局所の腰痛は椎間関節、下肢への放散痛は神経根の関与を考える。"},{"name":"ブラガードテスト","alias":"","steps":"SLRで症状が出た角度から少し下肢を下げ、足関節を他動的に背屈させる。","positive":"下肢の放散痛が再び出現・増悪する","tissue":"坐骨神経・腰仙部神経根","point":"ハムストリングスの伸張痛と神経由来の症状を区別するのに役立つ。"}]},"keypoints":["腰痛のみか、下肢症状を伴うかをまず区別する","SLRは下位、大腿神経伸張は上位腰椎の神経根をみる","筋の伸張感と神経性の放散痛を分けて記録する","皮膚分節・筋力・腱反射で障害高位を推定する","排尿・排便障害や会陰部のしびれは緊急で医師へ"],"case":{"text":"35歳男性。重い物を持ち上げた後から腰痛と右下腿外側〜足背のしびれ。SLRテストで右下肢に放散痛、ブラガードテストで増悪。母趾背屈の筋力が低下している。","answer":"L5神経根症状を疑う（腰椎椎間板ヘルニアなど）。痛みを増悪させる前屈負荷は控える。排尿・排便の異常、会陰部のしびれ、急速な筋力低下があれば緊急に医師へつなぐ。"},"questions":[{"level":"基礎","q":"SLRテストで主に伸張される神経はどれか。","options":["大腿神経","坐骨神経","閉鎖神経","陰部神経"],"answer":1,"exp":"膝伸展位で股関節を屈曲すると、下肢後面を走る坐骨神経とL5・S1神経根が伸張される。"},{"level":"基礎","q":"大腿神経伸張テストで評価する主な神経根レベルはどれか。","options":["L2〜L4","L5〜S1","S2〜S4","C5〜C6"],"answer":0,"exp":"大腿神経はL2〜L4神経根から成り、上位腰椎の神経根症状の評価に用いる。"},{"level":"中級","q":"ブラガードテストで加える操作はどれか。","options":["足関節底屈","股関節外旋","膝関節屈曲","足関節背屈"],"answer":3,"exp":"SLRで症状が出た角度から少し下げ、足関節を背屈させて神経をさらに伸張する。"},{"level":"中級","q":"ケンプテストで下肢症状がなく、局所の腰痛のみが出た場合に主に疑うのはどれか。","options":["神経根の圧迫","大腿神経の障害","椎間関節由来の痛み","梨状筋の障害"],"answer":2,"exp":"伸展・回旋で椎間関節に負荷がかかる。局所痛のみなら椎間関節由来を考える。"},{"level":"臨床","q":"40歳女性、腰痛と左足部外側〜足底のしびれ。左アキレス腱反射が低下している。最も疑われる神経根はどれか。","options":["L3","L4","L5","S1"],"answer":3,"exp":"足部外側・足底の感覚障害とアキレス腱反射の低下はS1神経根の障害を示す。"},{"level":"臨床","q":"50歳男性。腰痛に加えて会陰部のしびれと排尿困難が急に出現した。最も適切な対応はどれか。","options":["直ちに医師へつなぐ","SLRを繰り返し評価する","腰部の運動療法を始める","温熱療法で様子を見る"],"answer":0,"exp":"会陰部のしびれと膀胱直腸障害は馬尾障害を疑うレッドフラッグで、緊急の対応が必要。"}],"seccion":"部位別の特殊テスト","grupo":"脊椎・骨盤","icono":"🦴","mapa":"img/mapas/t16.jpg","fichas":[],"secuencias":[]},"17":{"id":17,"title":"仙腸関節","lead":"仙腸関節由来の痛みは腰痛と間違えられやすい部位です。痛みの場所の指示と複数の誘発テストを組み合わせて推定します。","sheet":{"kind":"tests","tests":[{"name":"パトリックテスト","alias":"FABERテスト","steps":"背臥位で患側の足部を対側の膝の上に置き、対側骨盤を固定して膝を床方向へ押す。","positive":"殿部・仙腸関節部の痛み（鼠径部痛なら股関節）","tissue":"仙腸関節・股関節","point":"痛みの部位で区別する。鼠径部は股関節、殿部・仙腸関節部は仙腸関節を考える。"},{"name":"ゲンスレンテスト","alias":"","steps":"背臥位で一側の下肢を診察台の端から下ろして股関節を伸展し、対側は屈曲位で抱えさせる。","positive":"伸展側の仙腸関節部の痛み","tissue":"仙腸関節","point":"腰椎の過伸展を避け、転落しないよう体幹を支えて行う。"},{"name":"大腿スラストテスト","alias":"サイスラストテスト","steps":"背臥位で股関節90°屈曲位とし、大腿の長軸に沿って床方向へ圧を加える。","positive":"同側の殿部・仙腸関節部の痛み","tissue":"仙腸関節","point":"痛む場所を本人に示してもらい、普段の痛みと同じかを確認する。"},{"name":"骨盤圧迫テスト","alias":"","steps":"側臥位で上側の腸骨稜に、上から床方向へ圧迫を加える。","positive":"仙腸関節部の痛み","tissue":"仙腸関節","point":"単独では判断しない。複数の誘発テストを組み合わせて仙腸関節由来の痛みを推定する。"}]},"keypoints":["痛む場所を本人に一本の指で示してもらう","上後腸骨棘付近の痛みは仙腸関節由来を考える","単独ではなく複数の誘発テストで判断する","鼠径部痛は股関節、下肢への放散痛は神経根も考える","発熱や安静時の強い痛みがあれば医師へつなぐ"],"case":{"text":"32歳女性、産後3か月。片側の殿部痛で、寝返りや片脚立ちで増悪する。痛む場所を一本の指で上後腸骨棘付近に示す。大腿スラストとゲンスレンで痛みが再現。","answer":"仙腸関節由来の痛みを疑う。下肢への放散痛や神経症状があれば腰椎由来も考える。発熱や安静時の強い痛みがあれば医師へ。骨盤帯の安定化と負荷調整から進める。"},"questions":[{"level":"基礎","q":"ワンフィンガーテストで仙腸関節由来の痛みが示されやすい部位はどれか。","options":["上前腸骨棘付近","上後腸骨棘付近","恥骨結合","坐骨結節"],"answer":1,"exp":"仙腸関節由来の痛みでは、上後腸骨棘付近を一本の指で示すことが多い。"},{"level":"基礎","q":"仙腸関節を構成する骨の組み合わせはどれか。","options":["仙骨と腸骨","仙骨と坐骨","腸骨と恥骨","第5腰椎と仙骨"],"answer":0,"exp":"仙腸関節は仙骨と左右の腸骨の間の関節で、骨盤輪の後方を構成する。"},{"level":"中級","q":"パトリックテストで鼠径部に痛みが出た場合に疑う関節はどれか。","options":["仙腸関節","股関節","膝関節","椎間関節"],"answer":1,"exp":"屈曲・外転・外旋で鼠径部が痛む場合は股関節、殿部後方なら仙腸関節を考える。"},{"level":"中級","q":"大腿スラストテストで圧を加える方向はどれか。","options":["大腿を外側へ","骨盤を前方へ","大腿長軸に沿って床方向へ","膝を内側へ"],"answer":2,"exp":"股関節90°屈曲位で大腿長軸に沿って圧を加え、仙腸関節に剪断ストレスをかける。"},{"level":"臨床","q":"28歳女性、出産後に片側の殿部痛。ゲンスレン、大腿スラスト、骨盤圧迫で痛みが再現。最も疑われる部位はどれか。","options":["股関節","L5神経根","梨状筋","仙腸関節"],"answer":3,"exp":"複数の仙腸関節誘発テストで同じ痛みが再現しており、仙腸関節由来を最も疑う。"},{"level":"臨床","q":"45歳男性、片側の殿部痛。パトリックテストのみで殿部に痛みが出た。次の判断として最も適切なのはどれか。","options":["仙腸関節障害と確定する","他の誘発テストも組み合わせる","腰椎・股関節の評価は省く","強い徒手矯正を行う"],"answer":1,"exp":"1つの陽性では判断できない。複数の誘発テストと腰椎・股関節の評価を組み合わせる。"}],"seccion":"部位別の特殊テスト","grupo":"脊椎・骨盤","icono":"🦴","mapa":"img/mapas/t17.jpg","fichas":[],"secuencias":[]},"18":{"id":18,"title":"股関節","lead":"股関節由来の痛みは鼠径部に出やすく、拘縮や筋力低下は歩き方に表れます。テストで関節内・筋・歩行への影響を確認します。","sheet":{"kind":"tests","tests":[{"name":"トーマステスト","alias":"","steps":"背臥位で一側の膝を胸に抱え込み腰椎の前弯を消した状態で、反対側の大腿の浮き上がりをみる。","positive":"反対側の大腿が床から浮く（股関節屈曲拘縮）","tissue":"腸腰筋（股関節屈筋群）の短縮","point":"膝が伸展する場合は大腿直筋の短縮も疑う。前弯を消してから判定する。"},{"name":"パトリックテスト","alias":"FABERテスト","steps":"背臥位で股関節を屈曲・外転・外旋させ（足部を対側膝の上へ）、膝を床方向へ押す。","positive":"鼠径部の痛み、または膝の下がりの制限","tissue":"股関節・仙腸関節","point":"鼠径部の痛みは股関節、殿部後方の痛みは仙腸関節を考える。健側と比較する。"},{"name":"前方インピンジメントテスト","alias":"FADIRテスト","steps":"背臥位で股関節を90°屈曲させ、他動的に内転・内旋を加える。","positive":"鼠径部の痛みの再現","tissue":"股関節前方（関節唇・寛骨臼縁）","point":"大腿骨寛骨臼インピンジメントや関節唇損傷で陽性になりやすい。画像所見と統合する。"},{"name":"トレンデレンブルグ徴候","alias":"","steps":"患側で片脚立ちをさせ、反対側（挙上側）の骨盤の高さを後方から観察する。","positive":"挙上側の骨盤が下降する","tissue":"立脚側の中殿筋（股関節外転筋）","point":"体幹を立脚側へ傾けて代償する場合はデュシェンヌ徴候。転倒に注意して支える。"}]},"keypoints":["股関節由来の痛みは鼠径部に出やすい","トーマステストは腰椎前弯を消して屈曲拘縮をみる","トレンデレンブルグは立脚側の中殿筋の筋力をみる","腰椎や仙腸関節由来の痛みとも区別する","外傷後の荷重困難や安静時痛の悪化は医師へ"],"case":{"text":"68歳女性、変形性股関節症。歩行時に右鼠径部痛。右片脚立ちで左骨盤が下降し、左膝を胸に抱えると右大腿が床から浮く。","answer":"右中殿筋の筋力低下と右股関節の屈曲拘縮が考えられる。歩行時の代償も観察し、痛みに配慮して外転筋の強化と可動域練習を進める。安静時痛の急な悪化は医師へつなぐ。"},"questions":[{"level":"基礎","q":"トーマステストで短縮を評価する主な筋はどれか。","options":["大殿筋","腸腰筋","中殿筋","ハムストリングス"],"answer":1,"exp":"反対側の大腿が浮くのは股関節屈曲拘縮を示し、主な股関節屈筋である腸腰筋の短縮をみる。"},{"level":"基礎","q":"片脚立ちで反対側の骨盤が下がるトレンデレンブルグ徴候で、筋力低下が疑われる筋はどれか。","options":["遊脚側の中殿筋","立脚側の大腿四頭筋","立脚側の中殿筋","遊脚側の腸腰筋"],"answer":2,"exp":"立脚側の中殿筋が弱いと骨盤を水平に保てず、反対側（挙上側）の骨盤が下降する。"},{"level":"中級","q":"トーマステストで膝が伸展する場合に短縮が疑われる筋はどれか。","options":["大腿直筋","縫工筋","大内転筋","大腿二頭筋"],"answer":0,"exp":"大腿直筋は股関節と膝関節をまたぐ二関節筋で、短縮があると膝が伸展してくる。"},{"level":"中級","q":"前方インピンジメントテスト（FADIR）で加える運動の組み合わせはどれか。","options":["屈曲・外転・外旋","伸展・外転・内旋","伸展・内転・外旋","屈曲・内転・内旋"],"answer":3,"exp":"股関節90°屈曲位から内転・内旋を加え、股関節前方の痛みの再現をみる。"},{"level":"臨床","q":"70歳男性。右下肢で立つたびに体幹を右へ大きく傾けて歩く。この歩行の名称はどれか。","options":["鶏歩","分回し歩行","すくみ足","デュシェンヌ歩行"],"answer":3,"exp":"中殿筋の筋力低下を、体幹を立脚側へ傾けて代償する歩行をデュシェンヌ歩行という。"},{"level":"臨床","q":"30歳男性、サッカー選手。深くしゃがむと鼠径部が痛み、股関節の屈曲・内転・内旋で痛みが再現する。最も疑われるのはどれか。","options":["変形性膝関節症","大腿骨寛骨臼インピンジメント","L5神経根症","梨状筋症候群"],"answer":1,"exp":"深屈曲での鼠径部痛と前方インピンジメントテスト陽性から、大腿骨寛骨臼インピンジメントを疑う。"}],"seccion":"部位別の特殊テスト","grupo":"股関節・膝関節","icono":"🦵","mapa":"img/mapas/t18.jpg","fichas":[],"secuencias":[]},"19":{"id":19,"title":"膝関節：靭帯","lead":"膝の靭帯テストは、前十字・後十字・内側・外側側副靭帯の損傷を見分けるための評価です。受傷機転と健側との比較が判断の土台になります。","sheet":{"kind":"tests","tests":[{"name":"ラックマンテスト","alias":"","steps":"背臥位で膝20〜30°屈曲。一方の手で大腿遠位、他方の手で脛骨近位を把持し、脛骨を前方へ引き出す。","positive":"健側より大きな前方移動、またはエンドポイントが不明瞭。","tissue":"前十字靭帯（ACL）","point":"ACL損傷に対して感度が高い。膝90°屈曲が不要で急性期にも行いやすい。"},{"name":"前方引き出しテスト","alias":"","steps":"背臥位で股45°・膝90°屈曲。足部を固定し、脛骨近位を両手で把持して前方へ引く。","positive":"健側と比べて脛骨の前方移動が大きい。","tissue":"前十字靭帯（ACL）","point":"筋の防御性収縮は偽陰性の原因。PCL損傷の後方落ち込みにも注意。"},{"name":"後方引き出しテスト","alias":"","steps":"背臥位で股45°・膝90°屈曲。足部を固定し、脛骨近位を後方へ押す。","positive":"健側より脛骨の後方移動が大きい、エンドポイントが不明瞭。","tissue":"後十字靭帯（PCL）","point":"開始前に脛骨の後方落ち込み（サグサイン）を確認し、開始位置を誤らない。"},{"name":"外反・内反ストレステスト","alias":"","steps":"背臥位で膝0°と30°屈曲位にて、大腿遠位を固定し下腿に外反または内反の力を加える。","positive":"関節裂隙の疼痛や、健側より大きな開大。","tissue":"外反＝MCL、内反＝LCL","point":"30°のみ陽性なら側副靭帯単独、0°でも陽性なら十字靭帯などの合併損傷を疑う。"}]},"keypoints":["ACLの評価はラックマンテストを優先し、必ず健側と比較する。","膝くずれ・ポップ音・急な腫脹など受傷機転を問診で確認する。","後方引き出しの前にサグサインで脛骨の位置を確認する。","側副靭帯は膝0°と30°の両方でストレスを加える。","防御性収縮で偽陰性になるため、力を抜いた肢位で行う。"],"case":{"text":"20歳女性。バスケットボールの着地で膝が内側に崩れて受傷。ポップ音と直後の腫脹あり。ラックマンテストで健側より前方移動が大きく、エンドポイントは不明瞭。","answer":"ACL損傷を疑う所見。半月板や側副靭帯の合併損傷も評価し、医師の画像診断につなぐ。腫脹や疼痛が強い時期に強いストレスを繰り返し加えない。"},"questions":[{"level":"基礎","q":"図で、膝20〜30°屈曲位で脛骨を前方へ引き出すテストはどれ？","options":["前方引き出しテスト","ラックマンテスト","後方引き出しテスト","外反ストレステスト"],"answer":1,"exp":"ラックマンテストは膝20〜30°屈曲位で脛骨を前方へ引き出し、ACLを評価する。前方引き出しは膝90°で行う。"},{"level":"基礎","q":"図で、内反ストレステストが評価する靭帯はどれ？","options":["内側側副靭帯（MCL）","前十字靭帯（ACL）","外側側副靭帯（LCL）","後十字靭帯（PCL）"],"answer":2,"exp":"内反ストレスは膝の外側を開く力となり、外側側副靭帯（LCL）を評価する。外反ストレスはMCLを評価する。"},{"level":"中級","q":"後方引き出しテストの陽性が示唆する損傷はどれ？","options":["PCL損傷","ACL損傷","LCL損傷","膝蓋骨脱臼"],"answer":0,"exp":"後方引き出しテストは膝90°屈曲位で脛骨を後方へ押し、後十字靭帯（PCL）を評価する。"},{"level":"中級","q":"外反ストレステストが膝0°でも陽性のとき、まず考えるべきことは？","options":["MCLの軽い単独損傷","外側半月板のみの損傷","膝蓋骨の不安定性","十字靭帯などの合併損傷"],"answer":3,"exp":"伸展位では十字靭帯や関節包も安定に関わる。0°でも開大があれば、MCL単独ではなく合併損傷を疑う。"},{"level":"臨床","q":"25歳男性。サッカーで膝を曲げた状態で脛骨前面を強打した。膝90°屈曲位で脛骨が後方へ落ち込んで見える。最も疑う損傷は？","options":["ACL損傷","PCL損傷","MCL損傷","内側半月板損傷"],"answer":1,"exp":"脛骨前面への外力とサグサインはPCL損傷の典型。後方引き出しテストで確認し、医師の診断につなぐ。"},{"level":"臨床","q":"30歳女性。スキーで膝を外反強制され受傷。外反ストレスで30°屈曲位では疼痛と開大があり、0°では安定。最も考えられるのは？","options":["ACL単独損傷","LCL損傷","MCL単独損傷","PCL損傷"],"answer":2,"exp":"外反強制で30°のみ陽性ならMCL単独損傷が考えられる。0°でも陽性なら合併損傷を疑う。"}],"seccion":"部位別の特殊テスト","grupo":"股関節・膝関節","icono":"🦵","mapa":"img/mapas/t19.jpg","fichas":[{"nombre":"ラックマンテスト","img":"img/fichas/lachman.jpg"}],"secuencias":[]},"20":{"id":20,"title":"膝関節：半月板・膝蓋骨","lead":"半月板と膝蓋骨のテストは、ひねりや着地で生じる膝の痛み・引っかかり・不安定感の原因を探る評価です。複数の所見を組み合わせて判断します。","sheet":{"kind":"tests","tests":[{"name":"マクマレーテスト","alias":"","steps":"背臥位で膝を最大屈曲し、下腿を外旋または内旋しながら膝を伸展していく。","positive":"関節裂隙のクリック音や疼痛。","tissue":"半月板（内側・外側）","point":"外旋で内側、内旋で外側の半月板を評価するとされる。単独で確定しない。"},{"name":"アプレーテスト","alias":"アプレー圧迫テスト","steps":"腹臥位で膝90°屈曲。踵から下方へ圧迫を加えながら下腿を内旋・外旋する。","positive":"圧迫と回旋で関節裂隙に疼痛が出る。","tissue":"半月板","point":"牽引しながら回旋して疼痛が出る場合は、靭帯など半月板以外の組織を考える。"},{"name":"テサリーテスト","alias":"","steps":"検者が両手を支え、片脚立ちで膝20°屈曲位のまま体幹と膝を内外旋させる。健側から行う。","positive":"関節裂隙の疼痛、ロッキング感や引っかかり感。","tissue":"半月板","point":"荷重位のテスト。転倒に注意し、両手の支持を確保して行う。"},{"name":"膝蓋骨アプリヘンションテスト","alias":"","steps":"背臥位で膝軽度屈曲位。大腿四頭筋を弛緩させ、膝蓋骨を外側へゆっくり押す。","positive":"不安感を示し、大腿四頭筋を収縮させて防ごうとする。","tissue":"膝蓋骨の安定機構（内側膝蓋大腿靭帯など）","point":"膝蓋骨脱臼・亜脱臼の既往の確認に有用。愛護的に行い、脱臼を誘発しない。"}]},"keypoints":["関節裂隙の痛みは半月板損傷を示唆する重要な所見。","半月板テストは単独で判断せず、複数の所見を組み合わせる。","膝が伸びきらないロッキングは医師への相談が必要なサイン。","膝蓋骨のテストは不安感の有無を観察し、愛護的に行う。","荷重位のテストは転倒予防のため支持を確保して行う。"],"case":{"text":"35歳男性。膝を曲げた状態でひねって受傷し、数時間後に腫脹。階段で膝内側に引っかかり感がある。内側関節裂隙に圧痛、マクマレーテストで疼痛とクリックあり。","answer":"内側半月板損傷を疑う。靭帯損傷の合併も評価し、医師の画像診断につなぐ。ロッキングがあるときに無理に伸展させない。"},"questions":[{"level":"基礎","q":"図で、腹臥位・膝90°で圧迫と回旋を加えるテストはどれ？","options":["マクマレーテスト","テサリーテスト","アプレーテスト","膝蓋骨アプリヘンション"],"answer":2,"exp":"アプレーテストは腹臥位・膝90°屈曲で、踵から圧迫しながら回旋し半月板を評価する。"},{"level":"基礎","q":"図のまとめで、半月板損傷を示唆するとされる所見はどれ？","options":["関節裂隙の痛み","膝蓋骨上方の痛み","脛骨粗面の痛み","大腿後面の痛み"],"answer":0,"exp":"関節裂隙（大腿骨と脛骨のすき間）の痛みは半月板損傷を示唆する。"},{"level":"中級","q":"マクマレーテストで下腿を外旋しながら伸展したとき、主に評価されるのは？","options":["外側半月板","内側半月板","前十字靭帯","膝蓋腱"],"answer":1,"exp":"外旋で内側半月板、内旋で外側半月板を評価するとされる。"},{"level":"中級","q":"膝蓋骨アプリヘンションテストの陽性所見はどれ？","options":["膝蓋骨のクリック音","内側関節裂隙の痛み","膝伸展の制限","不安感と四頭筋の防御収縮"],"answer":3,"exp":"膝蓋骨を外側へ押したときに不安感を示し、四頭筋を収縮させて防ごうとすれば陽性で、膝蓋骨不安定性を示唆する。"},{"level":"臨床","q":"18歳女性。ジャンプの着地で膝蓋骨が外れる感覚があり、自然に戻った。最も適した評価はどれ？","options":["膝蓋骨アプリヘンションテスト","後方引き出しテスト","トンプソンテスト","内反ストレステスト"],"answer":0,"exp":"膝蓋骨の脱臼・亜脱臼を疑う経過。膝蓋骨アプリヘンションテストで不安定性を確認する。"},{"level":"臨床","q":"40歳男性。膝内側の引っかかり感が続き、今朝から膝が完全に伸びない。適切な対応はどれ？","options":["強く他動伸展して戻す","医師へ相談し評価を依頼","テサリーテストを反復","すぐに筋力強化を開始"],"answer":1,"exp":"伸展できないロッキングは半月板の嵌頓の可能性があり、医師の評価が必要。無理な伸展や反復テストは避ける。"}],"seccion":"部位別の特殊テスト","grupo":"股関節・膝関節","icono":"🦵","mapa":"img/mapas/t20.jpg","fichas":[{"nombre":"マクマレーテスト","img":"img/fichas/mcmurray.jpg"}],"secuencias":[]},"21":{"id":21,"title":"足関節・足部","lead":"足関節・足部のテストは、捻挫による靭帯損傷やアキレス腱断裂を見分けるための評価です。骨折の可能性を常に念頭に置いて行います。","sheet":{"kind":"tests","tests":[{"name":"トンプソンテスト","alias":"シモンズテスト","steps":"腹臥位で足部をベッド端から出す。下腿三頭筋の筋腹をつまむように圧迫する。","positive":"足関節の底屈が起こらない、または健側より明らかに小さい。","tissue":"アキレス腱","point":"断裂していても足趾屈筋などで自動底屈できることがあり、本テストが有用。"},{"name":"前方引き出しテスト（足関節）","alias":"","steps":"座位または背臥位で足関節軽度底屈。脛骨遠位を固定し、踵を把持して距骨を前方へ引く。","positive":"健側より大きな前方移動、エンドポイントの不明瞭さ。","tissue":"前距腓靭帯","point":"内反捻挫で最も損傷しやすい靭帯の評価。急性期は疼痛に配慮して行う。"},{"name":"距骨傾斜テスト","alias":"内反ストレステスト","steps":"下腿遠位を固定し、踵骨を把持して足関節を内反方向へ傾ける。","positive":"健側より大きな距骨の傾き、疼痛。","tissue":"踵腓靭帯（前距腓靭帯）","point":"前方引き出しテストと組み合わせて外側靭帯の損傷の程度を判断する。"},{"name":"スクイーズテスト","alias":"","steps":"背臥位で下腿中央部の脛骨と腓骨を両手で挟み、圧迫する。","positive":"足関節の近位（脛骨と腓骨の間）に疼痛が出る。","tissue":"遠位脛腓靭帯","point":"高位足関節捻挫を疑うときに用いる。骨折の除外も重要。"}]},"keypoints":["内反捻挫では前距腓靭帯が最も損傷しやすい。","アキレス腱断裂でも自動底屈ができる場合がある。","骨の圧痛や荷重困難があれば骨折を疑い医師へつなぐ。","靭帯テストは必ず健側と比較して判断する。","脛骨と腓骨の間の痛みは高位捻挫を考える手がかり。"],"case":{"text":"45歳男性。テニス中に後ろから蹴られたような衝撃を感じて受傷。つま先立ちができない。腹臥位で下腿三頭筋をつまんでも足関節が底屈しない。","answer":"トンプソンテスト陽性でアキレス腱断裂を疑う。早急に医師の診察につなぐ。自動底屈ができても断裂を否定しない。"},"questions":[{"level":"基礎","q":"トンプソンテストで評価する組織はどれ？","options":["前距腓靭帯","アキレス腱","踵腓靭帯","足底腱膜"],"answer":1,"exp":"下腿三頭筋をつまんで足関節が底屈するかをみるテストで、アキレス腱の連続性を評価する。"},{"level":"基礎","q":"内反捻挫で最も損傷しやすい靭帯はどれ？","options":["後距腓靭帯","三角靭帯","踵腓靭帯","前距腓靭帯"],"answer":3,"exp":"底屈を伴う内反で受傷することが多く、前距腓靭帯が最も損傷しやすい。重症では踵腓靭帯も損傷する。"},{"level":"中級","q":"距骨傾斜テストが主に評価する靭帯はどれ？","options":["踵腓靭帯","三角靭帯","アキレス腱","後脛骨筋腱"],"answer":0,"exp":"踵骨を内反方向へ傾け、距骨の傾きをみることで主に踵腓靭帯を評価する。"},{"level":"中級","q":"スクイーズテストで足関節の近位に疼痛が出た。疑うのはどれ？","options":["アキレス腱断裂","足底腱膜炎","遠位脛腓靭帯損傷","外反母趾"],"answer":2,"exp":"下腿中央での圧迫により遠位脛腓関節部に疼痛が出れば、遠位脛腓靭帯損傷（高位捻挫）を疑う。"},{"level":"臨床","q":"22歳男性。足部を内返しして受傷。外果前方に腫脹と圧痛があり、骨の圧痛はない。前距腓靭帯の評価に最も適したテストは？","options":["前方引き出しテスト（足関節）","トンプソンテスト","ラックマンテスト","スクイーズテスト"],"answer":0,"exp":"前距腓靭帯は距骨の前方移動を制動する。足関節の前方引き出しテストで健側と比較する。"},{"level":"臨床","q":"60歳女性。転倒して足関節をひねった。外果に骨の圧痛があり、荷重して歩けない。適切な対応はどれ？","options":["前方引き出しテストを反復","骨折を疑い医師へつなぐ","すぐにバランス練習","テーピングで歩行練習"],"answer":1,"exp":"骨の圧痛と荷重困難は骨折を疑うサイン。ストレステストや運動より先に医師の評価につなぐ。"}],"seccion":"部位別の特殊テスト","grupo":"足関節・足部","icono":"🦶","mapa":"img/mapas/t21.jpg","fichas":[{"nombre":"トンプソンテスト","img":"img/fichas/thompson.jpg"}],"secuencias":[{"nombre":"トンプソンテスト","rotulo":"評価","texto":"アキレス腱","frames":["img/mov/teste-thompson-1.jpg","img/mov/teste-thompson-2.jpg","img/mov/teste-thompson-3.jpg"]}]},"22":{"id":22,"title":"神経学的テスト・神経ダイナミクステスト","lead":"神経ダイナミクステストは、神経を段階的に伸張して症状の再現をみる評価です。神経根や末梢神経由来の痛みを見分ける手がかりになります。","sheet":{"kind":"tests","tests":[{"name":"ラセーグ徴候（SLRテスト）","alias":"下肢伸展挙上テスト","steps":"背臥位で膝伸展のまま下肢を他動的に挙上する。症状が出た角度を記録し、足関節背屈などで増強を確認する。","positive":"殿部から下肢後面への放散痛など、症状が再現される。","tissue":"坐骨神経、L5・S1神経根など","point":"ハムストリングスの伸張感との区別に、足関節背屈や頸部屈曲の追加が有用。"},{"name":"大腿神経伸張テスト","alias":"FNST","steps":"腹臥位で膝を他動的に屈曲する。必要に応じて股関節伸展を加える。","positive":"大腿前面への放散痛。","tissue":"大腿神経、L2〜L4神経根","point":"大腿四頭筋の伸張感と区別する。上位腰椎の神経根障害の評価に用いる。"},{"name":"スランプテスト","alias":"","steps":"座位で体幹屈曲→頸部屈曲→膝伸展→足関節背屈と順に加え、頸部屈曲を解除して変化をみる。","positive":"症状が再現され、頸部屈曲の解除で軽減する。","tissue":"脊柱管内から下肢の神経系","point":"一段階ずつ加え、症状が出た時点で止める。左右差を比較する。"},{"name":"上肢神経動態テスト（正中神経）","alias":"ULNT1","steps":"背臥位で肩甲帯下制、肩外転、前腕回外、手関節・手指伸展、肩外旋、肘伸展を順に加え、頸部側屈で変化をみる。","positive":"上肢の症状が再現され、頸部側屈で変化する。","tissue":"正中神経、頸神経根","point":"健側と比較し、離れた部位の操作で症状が変われば神経由来の可能性が高まる。"}]},"keypoints":["神経テストは症状の再現と左右差で判断する。","離れた部位の操作で症状が変われば神経由来を考える。","筋の伸張感と神経症状を区別して記録する。","症状が出た時点で止め、強い痛みを誘発しない。","進行する麻痺や膀胱直腸障害は直ちに医師へつなぐ。"],"case":{"text":"42歳男性。重い荷物を持ち上げてから腰痛と右下肢後面の痛みが出現。SLRテストで右下肢後面に放散痛が再現され、足関節背屈で増強した。","answer":"腰椎神経根由来の症状を疑う所見。筋力・感覚・反射で障害高位を評価する。膀胱直腸障害や進行する麻痺があれば医師へ直ちにつなぐ。"},"questions":[{"level":"基礎","q":"SLRテストで主に伸張される神経はどれ？","options":["正中神経","大腿神経","坐骨神経","尺骨神経"],"answer":2,"exp":"膝伸展位で下肢を挙上すると、下肢後面を走る坐骨神経と下位腰神経根が伸張される。"},{"level":"基礎","q":"大腿神経伸張テストを行う肢位はどれ？","options":["腹臥位","背臥位","長座位","立位"],"answer":0,"exp":"腹臥位で膝を屈曲し、大腿前面を走る大腿神経を伸張する。"},{"level":"中級","q":"SLRテストで足関節背屈を加えると症状が増強した。これが示唆するのは？","options":["ハムストリングスの短縮","神経由来の症状","股関節の拘縮","足関節の捻挫"],"answer":1,"exp":"足関節背屈は筋の長さを変えずに神経の緊張を高める。症状が増強すれば神経由来を示唆する。"},{"level":"中級","q":"スランプテストで頸部屈曲を解除すると下肢の症状が軽減した。考えられるのは？","options":["筋の伸張痛","関節の不安定性","心因性の痛み","神経系の感受性亢進"],"answer":3,"exp":"頸部の操作は下肢の筋に影響しないため、症状が変化すれば神経系の関与が考えられる。"},{"level":"臨床","q":"50歳女性。大腿前面から膝内側にしびれ。腹臥位で膝を屈曲すると大腿前面の痛みが再現された。疑われる高位は？","options":["L2〜L4","L5","S1","C6"],"answer":0,"exp":"大腿神経伸張テスト陽性で大腿前面の症状があり、上位腰椎（L2〜L4）の神経根障害を疑う。"},{"level":"臨床","q":"38歳男性。SLRテストで下肢痛が再現。最近排尿しにくく、会陰部の感覚が鈍い。適切な対応はどれ？","options":["SLRテストを反復確認","腰部の筋力強化","直ちに医師へつなぐ","神経の滑走運動を継続"],"answer":2,"exp":"排尿障害や会陰部の感覚低下は馬尾障害を疑うレッドフラッグ。直ちに医師の評価が必要。"}],"seccion":"部位別の特殊テスト","grupo":"神経学的テスト","icono":"🧠","mapa":"img/mapas/t22.jpg","fichas":[{"nombre":"ラセーグ徴候（SLRテスト）","img":"img/fichas/lasegue.jpg"}],"secuencias":[{"nombre":"ラセーグ徴候","rotulo":"評価","texto":"坐骨神経（L4〜S1）","frames":["img/mov/teste-lasegue-1.jpg","img/mov/teste-lasegue-2.jpg","img/mov/teste-lasegue-3.jpg"]}]},"23":{"id":23,"title":"肩峰下インピンジメント・腱板断裂","lead":"肩峰下インピンジメントは、挙上時に腱板や肩峰下滑液包が刺激されて痛む状態です。腱板断裂との見分けと段階的な運動療法が重要です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"挙上時に腱板（特に棘上筋腱）や肩峰下滑液包が刺激されて痛む。加齢や使い過ぎ、外傷を背景に腱板断裂に至ることがある。"},{"h":"主な症状","t":"挙上時の痛み（有痛弧）、夜間痛、患側を下にして寝にくい。腱板断裂では挙上・外旋の筋力低下がみられる。"},{"h":"評価のポイント","t":"ニアー・ホーキンスでインピンジメント、ジョーブテストや外旋筋力で腱板機能をみる。肩甲骨の動きと姿勢も評価する。"},{"h":"介入の流れ","t":"疼痛管理と活動の調整→可動域の改善→腱板・肩甲骨周囲筋の段階的な強化→動作練習と仕事・スポーツへの復帰。"},{"h":"注意点・禁忌","t":"痛みを強める反復挙上は避ける。断裂の程度や医師の方針に合わせて負荷を調整し、無理なストレッチは行わない。"},{"h":"医師につなぐサイン","t":"外傷後の急な挙上不能、進行する筋力低下、安静時痛の悪化、発熱や腫脹、しびれなどの神経症状。"}]},"keypoints":["有痛弧と夜間痛はよくみられる訴え。","挙上・外旋の筋力低下は腱板断裂を疑う手がかり。","肩甲骨の動きと姿勢も合わせて評価する。","運動は痛みの範囲内で段階的に負荷を上げる。","外傷後の急な挙上不能は医師の評価につなぐ。"],"case":{"text":"62歳男性。数か月前から肩の外転時に痛みがあり、夜間痛もある。挙上の途中の範囲で痛みが強く、ジョーブテストで疼痛と筋力低下を認める。","answer":"棘上筋腱の障害や腱板断裂を疑う。医師の画像診断と方針を確認し、痛みの範囲内で可動域と腱板・肩甲骨周囲筋の運動を進める。痛みを強める反復挙上は避ける。"},"questions":[{"level":"基礎","q":"肩峰の下を通り、挙上時に刺激を受けやすい腱はどれ？","options":["棘上筋腱","小円筋腱","大胸筋腱","上腕三頭筋腱"],"answer":0,"exp":"棘上筋腱は肩峰の下を通るため、挙上時に肩峰下滑液包とともに刺激を受けやすい。"},{"level":"基礎","q":"肩の挙上の途中の範囲でのみ痛みが出る現象はどれ？","options":["肩手症候群","夜間痛","有痛弧","ドロップアームサイン"],"answer":2,"exp":"挙上の途中で痛みが出て、さらに挙げると軽減する現象を有痛弧と呼ぶ。肩峰下の障害でみられる。"},{"level":"中級","q":"ホーキンステストで主に評価するのはどれ？","options":["肩関節前方不安定性","肩峰下インピンジメント","肩鎖関節脱臼","胸郭出口症候群"],"answer":1,"exp":"肩90°屈曲位で内旋を加え、肩峰下で組織が挟まれて痛みが出るかをみるインピンジメントのテスト。"},{"level":"中級","q":"腱板断裂を疑う所見として最も適切なのはどれ？","options":["肘の屈曲制限","握力の増加","手指のしびれのみ","挙上・外旋の筋力低下"],"answer":3,"exp":"腱板は挙上や外旋に関わる。筋力低下は断裂を疑う手がかりで、医師の画像診断で確認する。"},{"level":"臨床","q":"58歳女性。転倒後から腕を挙げられない。他動では挙上できるが、自動では挙上できない。最も考えられるのは？","options":["凍結肩","腱板断裂","頸椎症","肩関節脱臼"],"answer":1,"exp":"他動では動くのに自動で挙がらないのは、筋・腱の機能障害を示す。外傷後なら腱板断裂を疑う。凍結肩は他動も制限される。"},{"level":"臨床","q":"45歳男性。挙上時痛が続く肩峰下インピンジメント。初期の運動療法として適切なのはどれ？","options":["痛みを我慢した反復挙上","重いダンベルでの挙上","痛みの範囲内の腱板運動","完全な安静の継続"],"answer":2,"exp":"痛みを強めない範囲で腱板・肩甲骨周囲筋の運動から始め、段階的に負荷を上げる。"}],"seccion":"疾患・外傷とリハビリ","grupo":"肩関節","icono":"💪","mapa":"img/mapas/t23.jpg","fichas":[],"secuencias":[]},"24":{"id":24,"title":"凍結肩（五十肩）","lead":"凍結肩は、肩の痛みと可動域制限が徐々に進む状態で中高年に多くみられます。病期に合わせて介入を変えることが大切です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"肩関節包などの炎症と線維化により、痛みと可動域制限が生じる。原因がはっきりしないことが多く、糖尿病との関連が指摘されている。"},{"h":"主な症状","t":"夜間痛、結髪・結帯動作の困難。自動・他動ともに可動域が制限され、特に外旋が制限されやすい。"},{"h":"評価のポイント","t":"自動・他動ROMを比較し、痛みの程度、夜間痛、ADLの困難さを評価する。腱板断裂など他の疾患との鑑別も重要。"},{"h":"フェーズ別リハビリ","t":"炎症期は疼痛管理と愛護的な運動、拘縮期は痛みの範囲内でのストレッチと可動域練習、回復期は可動域と筋力の再獲得。"},{"h":"注意点・禁忌","t":"炎症期に強い伸張を加えると痛みを悪化させうる。痛みを我慢させる強引な他動運動は避ける。"},{"h":"医師につなぐサイン","t":"外傷後の発症、急な筋力低下、発熱や腫脹、体重減少などの全身症状、安静時痛の急な悪化。"}]},"keypoints":["自動・他動ともに可動域が制限されるのが特徴。","特に外旋の制限が目立ちやすい。","炎症期は痛みを強める伸張を避ける。","病期ごとに介入の目標を切り替える。","腱板断裂など他の疾患との鑑別を行う。"],"case":{"text":"55歳女性。誘因なく肩の痛みが出現し、夜間痛で眠れない。数か月で結髪・結帯が困難になり、自動・他動ともに外旋が大きく制限されている。","answer":"凍結肩を疑う。医師の診断で他の疾患を除外し、現在の病期を見極める。痛みが強い時期は強い伸張を避け、疼痛管理と愛護的な運動から始める。"},"questions":[{"level":"基礎","q":"凍結肩で特に制限されやすい運動はどれ？","options":["肘屈曲","手関節背屈","肩甲骨挙上","肩関節外旋"],"answer":3,"exp":"凍結肩では関節包の拘縮により肩の多方向が制限され、特に外旋が制限されやすい。"},{"level":"基礎","q":"凍結肩で、痛みが和らぎ可動域制限が主体となる時期はどれ？","options":["炎症期","拘縮期","回復期","急性期"],"answer":1,"exp":"炎症期の強い痛みが落ち着くと、可動域制限が主体となる拘縮期に移る。その後に回復期が続く。"},{"level":"中級","q":"凍結肩と腱板断裂を見分けるのに役立つ所見はどれ？","options":["夜間痛の有無","他動可動域の制限の有無","年齢","痛みの部位"],"answer":1,"exp":"凍結肩は他動でも可動域が制限される。腱板断裂は他動では比較的動くが、自動で挙がりにくいことが多い。"},{"level":"中級","q":"凍結肩の炎症期の介入として最も適切なのはどれ？","options":["疼痛管理と愛護的な運動","強い他動ストレッチ","重負荷の筋力強化","競技復帰の練習"],"answer":0,"exp":"炎症期は痛みが強く、強い伸張は悪化させうる。疼痛管理と痛みを強めない運動を中心に行う。"},{"level":"臨床","q":"52歳女性。凍結肩の拘縮期で、痛みは軽く外旋と結帯が制限されている。適切な介入はどれ？","options":["完全な安静","三角巾で固定","痛みの範囲内の可動域練習","痛みを我慢する強い伸張"],"answer":2,"exp":"拘縮期は痛みが和らいでいるため、痛みの範囲内でストレッチや可動域練習を進める。"},{"level":"臨床","q":"60歳男性。肩の痛みと可動域制限に加え、最近の体重減少と安静時の強い痛みがある。適切な対応はどれ？","options":["医師へつなぐ","可動域練習を強化","温熱のみで経過観察","筋力強化を開始"],"answer":0,"exp":"体重減少や安静時の強い痛みは重い疾患の可能性を示すレッドフラッグ。まず医師の評価につなぐ。"}],"seccion":"疾患・外傷とリハビリ","grupo":"肩関節","icono":"💪","mapa":"img/mapas/t24.jpg","fichas":[],"secuencias":[]},"25":{"id":25,"title":"腱板修復術後","lead":"腱板修復術後のリハビリは、修復した腱を守りながら可動域と筋力を段階的に取り戻す過程です。医師が指示する時期と制限を守ることが前提です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"断裂した腱板を骨に再固定する手術。修復した腱が骨に癒合するまで時間がかかり、早すぎる負荷は再断裂の原因になりうる。"},{"h":"主な症状","t":"術後の疼痛・夜間痛、可動域制限、筋力低下。装具固定に伴う肩甲帯・頸部の緊張や、肘・手の動きの低下もみられる。"},{"h":"評価のポイント","t":"疼痛、他動・自動ROM、肩甲骨の動き、筋力、ADLを評価する。手術記録と医師の指示（禁忌肢位・時期）を確認する。"},{"h":"フェーズ別リハビリ","t":"保護期（装具・他動運動）→自動介助運動・自動運動→段階的な筋力強化→日常動作・仕事・スポーツへの復帰。"},{"h":"注意点・禁忌","t":"指示された時期より前の自動挙上や抵抗運動、修復腱を強く伸張する肢位は避ける。肘・手指は固定中も動かす。"},{"h":"医師につなぐサイン","t":"急な痛みの増悪や挙上力の低下（再断裂の疑い）、創部の発赤・腫脹・熱感、発熱、しびれの出現。"}]},"keypoints":["時期と禁忌肢位は医師の指示と手術記録で確認する。","保護期は修復腱を守り、他動運動を中心に行う。","固定中も肘・手指・肩甲骨の運動を行う。","抵抗運動は指示された時期から段階的に加える。","急な挙上力の低下は再断裂を疑い医師へつなぐ。"],"case":{"text":"60歳男性。腱板修復術後早期で装具を装着中。早く仕事に戻りたいと、自分で腕を挙げる練習をしていたという。","answer":"保護期に指示のない自動挙上は修復腱の負担となる。医師の指示を確認し、許可された他動運動と肘・手指の運動を中心に、時期を守る理由を説明する。"},"questions":[{"level":"基礎","q":"腱板修復術後の初期に装具を用いる主な目的はどれ？","options":["筋力を強化する","可動域を広げる","修復した腱を保護する","浮腫を予防する"],"answer":2,"exp":"保護期は修復した腱が骨に癒合するまで負担をかけないよう、装具で固定して腱を守る。"},{"level":"基礎","q":"腱板修復術後のリハビリで、最後の段階で導入されるのはどれ？","options":["装具固定","他動運動","自動介助運動","抵抗運動"],"answer":3,"exp":"保護期の固定・他動運動から、自動介助・自動運動を経て、最後に抵抗運動による筋力強化へ進む。"},{"level":"中級","q":"腱板修復術後の保護期に避けるべき運動はどれ？","options":["指示前の肩の自動挙上","肘の自動屈伸","手指の運動","指示された他動運動"],"answer":0,"exp":"保護期に指示のない肩の自動挙上は修復腱に負担をかける。肘・手指の運動は固定中も行う。"},{"level":"中級","q":"術後の運動の進め方を決める際、まず確認すべきものはどれ？","options":["患者の希望のみ","医師の指示と手術記録","健側の筋力","年齢のみ"],"answer":1,"exp":"断裂の大きさや修復方法により時期や禁忌肢位が異なるため、医師の指示と手術記録を確認する。"},{"level":"臨床","q":"65歳女性。腱板修復術後、経過は順調だったが、物を持ち上げた際に痛みが出て急に腕が挙がらなくなった。適切な対応は？","options":["抵抗運動を強める","同じ運動を継続","強いストレッチを行う","医師へ報告し評価を依頼"],"answer":3,"exp":"急な痛みと挙上力の低下は再断裂の可能性がある。運動を中止し、医師に報告して評価を依頼する。"},{"level":"臨床","q":"58歳男性。腱板修復術後で装具固定中。肘と手指のこわばりを訴える。適切な対応はどれ？","options":["肘・手指の運動を指導","肩の自動挙上を開始","何もせず固定を継続","肩に抵抗運動を追加"],"answer":0,"exp":"固定中も肘・手指の運動は行い、こわばりを防ぐ。肩の自動挙上や抵抗運動は指示された時期まで待つ。"}],"seccion":"疾患・外傷とリハビリ","grupo":"肩関節","icono":"💪","mapa":"img/mapas/t25.jpg","fichas":[],"secuencias":[]},"26":{"id":26,"title":"腱障害","lead":"腱障害は、繰り返す負荷に腱が適応できず、痛みと機能低下が生じる状態です。安静だけでなく、負荷の調整と段階的な負荷が回復の鍵です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"腱への反復負荷が回復を上回り、腱の構造や機能が変化して痛みが生じる。急な練習量の増加などが誘因になりやすい。"},{"h":"主な症状","t":"運動の始めや翌朝の痛み・こわばり、腱の局所的な圧痛。動くうちに軽減し、運動後に悪化することがある。"},{"h":"評価のポイント","t":"腱の圧痛、片脚踵上げや片脚スクワットなどの負荷での痛み、練習量・靴・路面の変化を確認する。"},{"h":"介入の流れ","t":"負荷の調整→等尺性運動→等張性（遠心性を含む）の筋力強化→ジャンプなど速い動作→競技復帰。"},{"h":"注意点・禁忌","t":"完全な安静は腱の負荷耐性を落としうる。痛みを大きく悪化させる負荷や、翌日まで残る強い痛みは避ける。"},{"h":"医師につなぐサイン","t":"急な断裂感やポップ音、明らかな筋力低下、強い腫脹・熱感、改善しない夜間痛や安静時痛。"}]},"keypoints":["急な練習量の増加は腱障害の誘因になりやすい。","完全な安静より、痛みに応じた負荷の調整を行う。","運動後や翌日の痛みで負荷量を見直す。","等尺性運動から段階的に高い負荷へ進める。","断裂感や急な筋力低下は医師へつなぐ。"],"case":{"text":"28歳男性ランナー。走行距離を急に増やしてから、朝のアキレス腱のこわばりと痛みが続く。走り始めに痛く、途中で軽減する。腱の中央部に圧痛あり。","answer":"アキレス腱障害を疑う。完全な安静ではなく走行量を調整し、痛みに応じて踵上げなどの段階的な負荷を進める。断裂感や筋力低下があれば医師へつなぐ。"},"questions":[{"level":"基礎","q":"腱障害の誘因として代表的なのはどれ？","options":["長期間の安静","急な練習量の増加","十分な睡眠","柔軟性の向上"],"answer":1,"exp":"腱の回復を上回る負荷、特に練習量の急な増加が腱障害の代表的な誘因となる。"},{"level":"基礎","q":"腱障害でよくみられる痛みの特徴はどれ？","options":["夜間のみの強い痛み","安静で増悪し続ける","常に一定の強さ","運動の始めの痛みと朝のこわばり"],"answer":3,"exp":"運動の始めや翌朝に痛み・こわばりが出て、動くうちに軽減することが多い。"},{"level":"中級","q":"腱障害の段階的負荷で、比較的後半に導入するのはどれ？","options":["等尺性運動","ゆっくりした筋力強化","ジャンプなど速い動作","負荷量の調整"],"answer":2,"exp":"痛みを管理しながら等尺性・等張性の運動で耐性を高め、その後にジャンプなど速い動作へ進める。"},{"level":"中級","q":"腱障害の負荷量を見直す目安として適切なのはどれ？","options":["運動翌日の痛みの変化","体重の変化","気温","練習時間帯"],"answer":0,"exp":"運動中だけでなく翌日の痛みやこわばりの変化をみて、負荷量を調整する。"},{"level":"臨床","q":"22歳女性バレーボール選手。ジャンプ後に膝蓋骨の下端が痛み、膝蓋腱に圧痛がある。最も考えられるのは？","options":["前十字靭帯損傷","膝蓋腱障害","半月板損傷","膝蓋骨脱臼"],"answer":1,"exp":"ジャンプ動作の反復と膝蓋骨下端・膝蓋腱の圧痛は膝蓋腱障害の典型的な所見。"},{"level":"臨床","q":"40歳男性。アキレス腱障害で通院中、テニス中に後ろから蹴られたような衝撃があり、つま先立ちができない。適切な対応は？","options":["遠心性運動を継続","負荷をさらに上げる","ストレッチを強化","断裂を疑い医師へつなぐ"],"answer":3,"exp":"急な衝撃感とつま先立ち不能はアキレス腱断裂を疑う所見。運動を中止し、医師の評価につなぐ。"}],"seccion":"疾患・外傷とリハビリ","grupo":"スポーツ・腱・筋","icono":"🏃","mapa":"img/mapas/t26.jpg","fichas":[],"secuencias":[]},"27":{"id":27,"title":"足関節捻挫","lead":"足関節捻挫は多いスポーツ外傷の一つで、底屈を伴う内反で起こることが多い損傷です。再発予防には固有感覚トレーニングが重要です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"底屈を伴う内反で外側靭帯が損傷する。最も損傷しやすいのは前距腓靭帯で、重症度により踵腓靭帯も損傷する。"},{"h":"主な症状","t":"外果周囲の痛み・腫脹・皮下出血、荷重時痛。不安定感や捻挫の繰り返しを訴えることもある。"},{"h":"評価のポイント","t":"受傷機転、圧痛部位、荷重の可否、前方引き出しテスト・距骨傾斜テスト。骨折や他の靭帯損傷を見落とさない。"},{"h":"フェーズ別リハビリ","t":"1 保護・冷却・圧迫・挙上→2 可動性と段階的な荷重→3 筋力強化と固有感覚→4 ランニング・ジャンプ・競技復帰。"},{"h":"注意点・禁忌","t":"急性期に痛みを強める運動は避ける。固有感覚・バランス練習を省くと、再発や不安定感が残りやすい。"},{"h":"医師につなぐサイン","t":"骨の圧痛や荷重困難（骨折の疑い）、高度な腫脹や変形、しびれ、改善しない痛みや繰り返す不安定感。"}]},"keypoints":["受傷機転は底屈を伴う内反が多い。","最も損傷しやすいのは前距腓靭帯。","骨の圧痛や荷重困難があれば骨折を疑う。","固有感覚トレーニングで再発リスクが下がる。","競技復帰は片脚での動作を確認してから段階的に。"],"case":{"text":"19歳男性。サッカーで足を内返しして受傷。翌日、外果前方に腫脹と圧痛があるが骨の圧痛はなく、荷重は可能。前方引き出しテストで健側より前方移動が大きい。","answer":"前距腓靭帯損傷を伴う内反捻挫を疑う。保護・冷却・圧迫・挙上と痛みに応じた荷重から始め、筋力と固有感覚の練習を経て段階的に復帰する。"},"questions":[{"level":"基礎","q":"図で、足関節捻挫の典型的な受傷機転はどれ？","options":["背屈を伴う外反","底屈を伴う内反","背屈を伴う内反","底屈を伴う外反"],"answer":1,"exp":"足関節捻挫は底屈を伴う内反で起こることが多く、外側の前距腓靭帯が最も損傷しやすい。"},{"level":"基礎","q":"図で、フェーズ3の内容はどれ？","options":["保護・冷却・圧迫・挙上","可動性と段階的な荷重","筋力強化と固有感覚","ランニング・競技復帰"],"answer":2,"exp":"フェーズ1は保護・冷却・圧迫・挙上、2は可動性と荷重、3は筋力強化と固有感覚、4は競技復帰。"},{"level":"中級","q":"段階的な荷重を始めるのはどのフェーズから？","options":["フェーズ1","フェーズ2","フェーズ3","フェーズ4"],"answer":1,"exp":"フェーズ1の保護の後、フェーズ2で可動性の改善とともに痛みに応じて段階的に荷重を進める。"},{"level":"中級","q":"足関節捻挫の再発予防に特に重要とされる練習はどれ？","options":["長期の固定","完全な安静","上肢の筋力強化","固有感覚トレーニング"],"answer":3,"exp":"バランスボードや片脚立ちなどの固有感覚トレーニングは、再発リスクを下げるとされる。"},{"level":"臨床","q":"24歳女性。捻挫後3週で痛みはほぼないが、片脚立ちで足関節がぐらつく。優先する介入はどれ？","options":["バランス・固有感覚練習","冷却と挙上","完全な安静","すぐに全力疾走"],"answer":0,"exp":"痛みが落ち着き不安定性が残る段階。片脚立ちなどの固有感覚・筋力練習を優先し、段階的に復帰へ進める。"},{"level":"臨床","q":"20歳男性。足関節の捻挫を何度も繰り返し、日常生活でも足首がぐらつく感じがある。考えられるのはどれ？","options":["アキレス腱断裂","足底腱膜炎","慢性足関節不安定症","外反母趾"],"answer":2,"exp":"捻挫の繰り返しと不安定感は慢性足関節不安定症を示唆する。固有感覚と筋力の練習が重要で、必要に応じ医師へ相談する。"}],"seccion":"疾患・外傷とリハビリ","grupo":"スポーツ・腱・筋","icono":"🏃","mapa":"img/mapas/t27.jpg","fichas":[],"secuencias":[]},"28":{"id":28,"title":"筋損傷","lead":"筋損傷は肉ばなれ（筋の部分断裂）と筋打撲に大別されるスポーツ外傷です。再発しやすく、段階的な負荷と復帰基準の設定が重要です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"肉ばなれは筋が収縮しながら伸ばされる遠心性収縮時に生じやすく、筋腱移行部に多い。筋打撲は外力による直達外傷で、大腿四頭筋に多い。"},{"h":"主な症状","t":"受傷時の痛みや断裂感、圧痛、腫脹・皮下出血、筋の伸張時や抵抗時の痛み、筋力低下。重症例では陥凹を触れることがある。"},{"h":"評価のポイント","t":"受傷機転、圧痛部位、伸張時痛（SLR角度などの左右差）、抵抗時痛、歩容。重症度は画像所見を含めて医師が判断する。"},{"h":"フェーズ別リハビリ","t":"急性期は保護と腫脹管理。痛みに応じて等尺性→求心性→遠心性収縮へ進め、ランニングも段階的に。復帰前に競技動作を確認する。"},{"h":"注意点・禁忌","t":"急性期の強いストレッチや強いマッサージは避ける。大腿部打撲後の強い刺激は骨化性筋炎の誘因とされる。痛みを我慢させない。"},{"h":"医師につなぐサイン","t":"明らかな陥凹や断裂感、腫脹の急速な増大、強い痛みの持続、しびれや皮膚色の変化（コンパートメント症候群の疑い）。"}]},"keypoints":["肉ばなれは遠心性収縮時に筋腱移行部で起こりやすい","急性期は保護と腫脹管理、強い伸張は避ける","負荷は等尺性→求心性→遠心性の順に進める","ハムストリングスでは遠心性トレーニングを取り入れる","復帰は痛み・柔軟性・筋力・競技動作で判断する"],"case":{"text":"20歳男性、陸上短距離選手。全力疾走中に大腿後面に痛みを感じ競技を中止した。翌日、大腿二頭筋に圧痛と皮下出血を認め、SLRで左右差と伸張時痛がある。","answer":"ハムストリングスの肉ばなれを考える。急性期は保護と腫脹管理を優先し、強いストレッチやマッサージは避ける。痛みに応じて等尺性収縮から段階的に負荷を上げる。陥凹など重症を疑う所見は医師へ。"},"questions":[{"level":"基礎","q":"肉ばなれが最も起こりやすい部位はどこか。","options":["筋腹の中央","筋腱移行部","骨膜","腱の骨付着部"],"answer":1,"exp":"肉ばなれは筋と腱の移行部に多く発生します。ハムストリングスでは大腿二頭筋長頭に多くみられます。"},{"level":"基礎","q":"肉ばなれが生じやすい筋の収縮様式はどれか。","options":["等尺性収縮","求心性収縮","遠心性収縮","等速性収縮"],"answer":2,"exp":"筋が収縮しながら引き伸ばされる遠心性収縮時に生じやすく、疾走中の遊脚期後半が典型的な場面です。"},{"level":"中級","q":"肉ばなれ後の筋力トレーニングの一般的な進め方はどれか。","options":["遠心性→求心性→等尺性","等尺性→求心性→遠心性","求心性→等尺性→遠心性","最初から全力の遠心性"],"answer":1,"exp":"痛みに応じて負荷の小さい等尺性収縮から始め、求心性収縮、遠心性収縮へと段階的に進めます。"},{"level":"中級","q":"大腿部打撲後に強いマッサージや強い伸張を避ける理由として最も適切なのはどれか。","options":["骨化性筋炎の誘因となる","筋萎縮が起こらなくなる","腱が短縮する","神経が再生しなくなる"],"answer":0,"exp":"打撲後早期の強い刺激は筋内の出血を増やし、骨化性筋炎の誘因になるとされます。"},{"level":"臨床","q":"サッカー選手。キック動作で大腿前面に痛みが出現し、翌日も圧痛と伸張時痛がある。急性期の対応として適切なのはどれか。","options":["強いストレッチを行う","保護と腫脹の管理を行う","全力スプリントで確認する","強いマッサージを行う"],"answer":1,"exp":"急性期は保護と腫脹管理を優先します。強い伸張やマッサージ、全力での動作確認は損傷を悪化させる恐れがあります。"},{"level":"臨床","q":"大腿部を強打した高校生。腫脹が急速に増大し、強い痛みと足のしびれを訴える。優先すべき対応はどれか。","options":["温熱療法を行う","ストレッチを指導する","速やかに医師へつなぐ","筋力訓練を開始する"],"answer":2,"exp":"腫脹の急速な増大、強い痛み、しびれはコンパートメント症候群を疑うサインであり、速やかな医師の評価が必要です。"}],"seccion":"疾患・外傷とリハビリ","grupo":"スポーツ・腱・筋","icono":"🏃","mapa":"img/mapas/t28.jpg","fichas":[],"secuencias":[]},"29":{"id":29,"title":"前十字靭帯・半月板損傷","lead":"ACL損傷はスポーツ中の着地や切り返しで起こりやすく、半月板損傷を合併することも多い外傷です。早期の評価と動作の再教育が予後を左右します。","sheet":{"kind":"condition","items":[{"h":"病態","t":"ACL損傷は着地や切り返し時の非接触型が多く、膝外反と下腿回旋が関与する。半月板損傷は荷重下の回旋で生じ、ACL損傷に合併しやすい。"},{"h":"主な症状","t":"ACL：受傷時の断裂音、関節血腫による腫脹、膝くずれ。半月板：関節裂隙の痛み、引っかかり感、ロッキング、可動域制限。"},{"h":"評価のポイント","t":"ACLはラックマンテスト、前方引き出しテスト、ピボットシフトテスト。半月板は関節裂隙の圧痛、マクマレーテスト。確定診断は医師が行う。"},{"h":"介入の流れ","t":"急性期は腫脹管理、伸展可動域と大腿四頭筋の収縮を確保。保存療法か再建術かは医師が判断する。術前から筋力と可動域を整えておく。"},{"h":"注意点・禁忌","t":"膝くずれを繰り返すと半月板や軟骨の損傷が進む恐れがある。ロッキング中の無理な可動域訓練は避ける。動作時のニーインに注意する。"},{"h":"医師につなぐサイン","t":"ロッキングで伸展できない、受傷直後の急な関節腫脹、膝くずれの反復、強い痛みの持続、骨折を疑う所見。"}]},"keypoints":["ACL損傷は非接触型が多く、ニーインが危険肢位","ACL評価の基本はラックマンテスト","半月板損傷は関節裂隙の圧痛と引っかかり感","ロッキングで伸展できない場合は医師へ","予防として着地・切り返し動作を指導する"],"case":{"text":"17歳女子バスケットボール選手。ジャンプの着地で膝が内側に入り、断裂音とともに転倒した。数時間で膝が腫れ、ラックマンテストで前方移動の増大と終末抵抗の消失を認める。","answer":"ACL損傷を疑う。急性期は腫脹管理と伸展可動域・大腿四頭筋収縮の確保を優先する。半月板の合併も考えロッキングの有無を確認する。保存か再建かは医師が判断し、自己判断で競技に復帰させない。"},"questions":[{"level":"基礎","q":"非接触型ACL損傷の典型的な受傷肢位はどれか。","options":["膝内反（ニーアウト）","膝外反（ニーイン）","膝の過屈曲","膝蓋骨への直達外力"],"answer":1,"exp":"非接触型ACL損傷は、着地や切り返しで膝が内側に入るニーイン（膝外反）肢位で起こりやすいです。"},{"level":"基礎","q":"半月板損傷に特徴的な症状はどれか。","options":["ロッキング","下垂足","膝蓋腱反射の消失","大腿前面の感覚低下"],"answer":0,"exp":"半月板の損傷部が関節内に挟まると、膝が一定角度で動かなくなるロッキングが起こります。"},{"level":"中級","q":"ACL損傷の評価で最も感度が高いとされる徒手検査はどれか。","options":["マクマレーテスト","後方引き出しテスト","ラックマンテスト","外反ストレステスト"],"answer":2,"exp":"ラックマンテストは膝軽度屈曲位で脛骨を前方に引き出し、前方移動量と終末抵抗を評価します。ACL評価の基本です。"},{"level":"中級","q":"マクマレーテスト陽性の所見はどれか。","options":["脛骨の前方移動の増大","回旋しながらの伸展でクリックと痛み","膝蓋骨の不安感","内側関節裂隙の開大"],"answer":1,"exp":"膝屈曲位から下腿を回旋させつつ伸展し、関節裂隙のクリック音や痛みが出れば半月板損傷を疑います。"},{"level":"臨床","q":"サッカー選手。切り返しで膝をひねった後、膝が引っかかって完全に伸展できない。最も考えられるのはどれか。","options":["膝蓋腱炎","腸脛靭帯炎","半月板損傷によるロッキング","オスグッド病"],"answer":2,"exp":"回旋外傷後に伸展できない状態はロッキングを示唆します。無理な可動域訓練は避け、医師の評価につなげます。"},{"level":"臨床","q":"ACL損傷後2日目で膝の腫脹がある。保存的管理の初期に優先する内容はどれか。","options":["ジャンプ練習","腫脹管理と伸展可動域の確保","全力の切り返し練習","深いスクワット負荷"],"answer":1,"exp":"初期は腫脹を管理し、伸展可動域と大腿四頭筋の収縮を確保します。高負荷の動作は膝くずれや二次損傷の恐れがあります。"}],"seccion":"疾患・外傷とリハビリ","grupo":"スポーツ・腱・筋","icono":"🏃","mapa":"img/mapas/t29.jpg","fichas":[],"secuencias":[]},"30":{"id":30,"title":"前十字靭帯再建術後","lead":"ACL再建術後のリハビリは、移植腱を守りながら可動域・筋力・動作を段階的に取り戻す過程です。伸展制限を残さないことが最初の目標です。","sheet":{"kind":"condition","items":[{"h":"病態・術式","t":"自家腱（膝屈筋腱や骨付き膝蓋腱など）で靭帯を作り直す手術。移植腱は術後に再構築され、時間をかけて強度を獲得していく。"},{"h":"術後の課題","t":"術後早期は腫脹、疼痛、伸展制限、大腿四頭筋の筋出力低下がみられやすい。採取部の痛みや筋力低下にも配慮する。"},{"h":"評価のポイント","t":"腫脹、膝伸展・屈曲角度の左右差、大腿四頭筋の随意収縮（エクステンションラグ）、歩容、筋力、ホップテストなどの機能テスト。"},{"h":"フェーズ別リハビリ","t":"0〜2週：完全伸展と大腿四頭筋。2〜6週：正常歩行と屈曲拡大。6〜12週：筋力と固有感覚。3〜6か月：段階的な走行とジャンプ。6か月以降：競技復帰テスト。"},{"h":"注意点・禁忌","t":"伸展制限を残さない。移植腱に負担をかける運動の開始時期は術式と医師の指示に従う。腫脹が増えたら負荷を下げ、時期だけで進めない。"},{"h":"医師につなぐサイン","t":"発熱や創部の発赤・熱感・排膿、急な腫脹の増大、ふくらはぎの痛みと腫れ（深部静脈血栓症の疑い）、膝くずれ。"}]},"keypoints":["最優先は完全伸展の獲得","早期から大腿四頭筋の随意収縮を引き出す","進行は時期だけでなく腫脹・ROM・筋力の基準で判断","競技復帰は機能テストと医師の判断で決める","再受傷予防に着地・切り返し動作を指導する"],"case":{"text":"22歳男性、ACL再建術後2週。膝に軽度の腫脹があり、伸展は−10°。大腿四頭筋の収縮が弱くエクステンションラグを認める。本人は早く走りたいと話している。","answer":"この時期の最優先は完全伸展と大腿四頭筋のコントロールの獲得。走行はまだ早い。伸展制限を残すと歩容異常や膝前面の痛みにつながる。腫脹を管理し、基準を満たしてから段階的に進める。"},"questions":[{"level":"基礎","q":"ACL再建術後のリハビリで最優先とされる目標はどれか。","options":["早期にジャンプを行う","深い屈曲を最初に獲得する","完全伸展を取り戻す","術直後から走行する"],"answer":2,"exp":"伸展制限が残ると歩容異常や膝前面の痛みにつながるため、完全伸展を取り戻すことが最優先です。"},{"level":"基礎","q":"競技復帰テストを行うのはどのフェーズか。","options":["フェーズ2（2〜6週）","フェーズ3（6〜12週）","フェーズ4（3〜6か月）","フェーズ5（6か月以降）"],"answer":3,"exp":"競技復帰テストは最終段階のフェーズ5（6か月以降）で、筋力や機能テストの結果をもとに行います。"},{"level":"中級","q":"術後早期に評価する「エクステンションラグ」とはどの状態か。","options":["膝の前方不安定性","自動伸展が他動伸展に届かない","他動屈曲の制限","膝蓋骨の外側偏位"],"answer":1,"exp":"他動では伸展できるのに自動では伸展しきれない状態で、大腿四頭筋の筋出力低下を示します。"},{"level":"中級","q":"術後リハビリの段階を進める判断として最も適切なのはどれか。","options":["腫脹・可動域・筋力の基準も確認","術後の週数のみで判断する","痛みが増えても予定通り進める","本人の希望を最優先する"],"answer":0,"exp":"時期は目安です。腫脹、可動域、筋力、動作の質などの基準を満たしているかを確認して段階を進めます。"},{"level":"臨床","q":"再建術後1週。ふくらはぎの痛みと腫れ、熱感が急に出現した。適切な対応はどれか。","options":["マッサージで腫れを流す","運動量を増やす","速やかに医師に報告する","温熱療法を行う"],"answer":2,"exp":"深部静脈血栓症の可能性があるサインです。マッサージは避け、速やかに医師へ報告します。"},{"level":"臨床","q":"術後4か月。筋力の左右差が大きく、着地時にニーインがみられる。この時点で適切な対応はどれか。","options":["すぐに試合へ復帰させる","筋力強化と着地動作の修正を続ける","リハビリを終了する","装具だけで復帰させる"],"answer":1,"exp":"筋力の左右差やニーインは再受傷のリスク因子です。筋力強化と動作修正を続け、基準を満たしてから復帰を検討します。"}],"seccion":"疾患・外傷とリハビリ","grupo":"スポーツ・腱・筋","icono":"🏃","mapa":"img/mapas/t30.jpg","fichas":[],"secuencias":[]},"31":{"id":31,"title":"変形性関節症","lead":"変形性関節症は関節軟骨の変性を中心に、痛みと機能低下が徐々に進む疾患です。膝と股関節に多く、運動療法と患者教育が保存療法の土台です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"関節軟骨の変性・摩耗を中心に、骨棘形成、軟骨下骨の硬化、滑膜炎を伴う。膝は内側型が多く、日本の股関節では臼蓋形成不全に続発するものが多い。"},{"h":"主な症状","t":"動作開始時痛、立ち上がりや階段昇降での痛み、こわばり、関節水腫、可動域制限。進行すると変形（O脚など）や歩行障害が目立つ。"},{"h":"評価のポイント","t":"疼痛の部位と誘因、ROM（膝の伸展制限、股関節の内旋制限など）、筋力、歩行（ラテラルスラスト、トレンデレンブルグ徴候）、ADL。"},{"h":"介入の流れ","t":"患者教育、運動療法（大腿四頭筋・股関節外転筋の強化、ROM維持）、有酸素運動、体重管理、杖や足底板などの補助具。保存で困難なら手術を検討。"},{"h":"注意点・禁忌","t":"炎症や水腫が強い時期は負荷を下げる。翌日まで痛みが残る負荷は過大と考える。杖は原則として患側と反対の手で持つ。"},{"h":"医師につなぐサイン","t":"急な強い腫脹と熱感（感染や偽痛風の疑い）、発熱、夜間痛の増悪、急な歩行困難、転倒後の強い痛み。"}]},"keypoints":["膝OAは内側型が多く、O脚変形を伴いやすい","日本の股関節OAは臼蓋形成不全由来が多い","運動療法と患者教育が保存療法の中心","杖は患側と反対の手で持つ","翌日まで痛みが残る負荷は見直す"],"case":{"text":"70歳女性。数年前から右膝の痛みがあり、立ち上がりの動き始めと階段で痛む。O脚変形、膝の伸展制限、歩行時の膝の外側への動揺（ラテラルスラスト）を認める。","answer":"内側型の変形性膝関節症を考える。患者教育、大腿四頭筋・股関節周囲筋の強化、ROM維持、体重管理を行い、必要に応じ左手での杖使用を検討する。急な熱感や腫脹があれば医師へ。"},"questions":[{"level":"基礎","q":"日本の変形性膝関節症で最も多いタイプはどれか。","options":["外側型（X脚）","内側型（O脚）","膝蓋大腿関節のみ","脛腓関節型"],"answer":1,"exp":"日本の変形性膝関節症は内側型が多く、O脚（内反）変形を伴いやすいのが特徴です。"},{"level":"基礎","q":"変形性関節症の画像所見として典型的なものはどれか。","options":["関節裂隙の開大","骨端線の開大","骨膜反応","骨棘形成"],"answer":3,"exp":"関節裂隙の狭小化、骨棘形成、軟骨下骨の硬化などが変形性関節症の典型的な所見です。"},{"level":"中級","q":"右膝の変形性膝関節症の患者に杖を指導する。杖を持つ手として適切なのはどれか。","options":["右手","左手","両手","どちらでもよい"],"answer":1,"exp":"杖は原則として患側と反対の手で持ち、患側の脚と同時に出すことで患側への負担を減らします。"},{"level":"中級","q":"変形性股関節症で中殿筋の筋力低下があるときにみられやすい所見はどれか。","options":["ドロップアーム徴候","ラセーグ徴候","トレンデレンブルグ徴候","ホーマンズ徴候"],"answer":2,"exp":"中殿筋の筋力低下では、患側での片脚立位時に反対側の骨盤が下がるトレンデレンブルグ徴候がみられます。"},{"level":"臨床","q":"膝OAの65歳男性。運動療法の翌日まで痛みと腫れが強く残った。適切な対応はどれか。","options":["さらに負荷を上げる","運動をすべて中止させる","負荷量を下げて調整する","安静のみを指導する"],"answer":2,"exp":"翌日まで残る痛みや腫脹は負荷過大のサインです。中止ではなく、量や強度を調整して継続します。"},{"level":"臨床","q":"膝OAの患者。急に膝が強く腫れて熱をもち、発熱もある。優先すべき対応はどれか。","options":["医師に連絡する","運動療法を強化する","温熱療法を行う","ストレッチを指導する"],"answer":0,"exp":"急な腫脹・熱感と発熱は感染や偽痛風などを疑うサインです。温熱や運動は控え、医師に連絡します。"}],"seccion":"疾患・外傷とリハビリ","grupo":"整形外科・外傷","icono":"🦴","mapa":"img/mapas/t31.jpg","fichas":[],"secuencias":[]},"32":{"id":32,"title":"人工股関節・人工膝関節置換術","lead":"人工関節置換術は傷んだ関節面を人工物に置き換え、痛みの軽減と機能改善を図る手術です。術式に合わせた動作指導と早期離床が回復の鍵です。","sheet":{"kind":"condition","items":[{"h":"病態・術式","t":"変形性関節症などで傷んだ関節面を人工物に置き換え、疼痛の軽減と機能改善を図る手術。THAでは進入法により脱臼しやすい肢位が異なる。"},{"h":"術後の課題","t":"疼痛、腫脹、可動域制限、筋力低下、歩行能力の低下。THAでは脱臼の予防、TKAでは膝の屈曲・伸展可動域の獲得が主な課題となる。"},{"h":"評価のポイント","t":"創部と腫脹、ROM、筋力（大腿四頭筋・中殿筋）、脚長差の訴え、歩容、バランス、ADL動作。荷重制限と禁忌肢位は医師の指示を確認する。"},{"h":"介入の流れ","t":"術後早期から足関節運動、等尺性運動、離床・歩行練習。ROMと筋力の訓練を進め、歩行補助具を段階的に変更し、ADLと退院後の生活を指導する。"},{"h":"注意点・禁忌","t":"後方進入のTHAは屈曲・内転・内旋、前方進入は伸展・内転・外旋の複合肢位に注意する。TKA後は腓骨神経麻痺の徴候にも注意する。"},{"h":"医師につなぐサイン","t":"脱臼を疑う急な痛みと脚の短縮・回旋、ふくらはぎの腫れと痛み、急な息切れや胸痛、創部の発赤・排膿、発熱。"}]},"keypoints":["THAの脱臼肢位は進入法によって異なる","後方進入では屈曲・内転・内旋の複合を避ける","足関節の底背屈運動で血栓予防を図る","TKAは屈曲・伸展可動域の早期獲得が重要","荷重量と禁忌肢位は必ず医師の指示を確認する"],"case":{"text":"75歳女性。変形性股関節症に対し後方進入でTHAを受けた術後3日目。歩行器で歩行練習中、床の物を拾おうとして体をひねりながら深くかがもうとした。","answer":"深い屈曲・内転・内旋の複合は後方進入THAの脱臼肢位であり、すぐに制止する。リーチャーなどの自助具を使った安全な動作を指導する。急な痛みや脚の短縮・回旋があれば医師へ。"},"questions":[{"level":"基礎","q":"後方進入のTHA後に脱臼しやすい肢位はどれか。","options":["伸展・内転・外旋","屈曲・内転・内旋","屈曲・外転・外旋","伸展・外転・内旋"],"answer":1,"exp":"後方進入のTHAでは、股関節の屈曲・内転・内旋の複合肢位で脱臼しやすくなります。"},{"level":"基礎","q":"人工膝関節置換術（TKA）の主な目的はどれか。","options":["骨の成長の促進","靭帯の再建","神経の修復","疼痛の軽減と機能改善"],"answer":3,"exp":"TKAは傷んだ関節面を人工物に置き換え、痛みの軽減と歩行などの機能改善を目的に行われます。"},{"level":"中級","q":"術後早期の深部静脈血栓症予防として指導する運動はどれか。","options":["頸部の回旋運動","手指の屈伸運動","足関節の底背屈運動","深いスクワット"],"answer":2,"exp":"足関節の底背屈運動は下腿の筋ポンプ作用で静脈還流を促し、血栓予防に役立ちます。"},{"level":"中級","q":"TKA後に注意すべき神経麻痺はどれか。","options":["腓骨神経麻痺","正中神経麻痺","顔面神経麻痺","橈骨神経麻痺"],"answer":0,"exp":"TKA後は腓骨頭付近での圧迫などにより腓骨神経麻痺が起こることがあり、下垂足やしびれに注意します。"},{"level":"臨床","q":"後方進入THA術後5日目の患者が、低い椅子に座って脚を組もうとしている。適切な対応はどれか。","options":["そのまま見守る","高い椅子にし脚組みを避ける","脚を組む練習を勧める","深くかがむ練習を行う"],"answer":1,"exp":"低い椅子での深い屈曲や脚を組む動作（内転・内旋）は脱臼肢位です。座面の高い椅子を使い、脚を組まないよう指導します。"},{"level":"臨床","q":"TKA術後2日目の患者が、歩行練習中に急な息切れと胸痛を訴えた。最も優先すべき対応はどれか。","options":["歩行練習を続ける","呼吸練習を指導する","直ちに中止し医師へ報告","休ませて様子をみる"],"answer":2,"exp":"肺塞栓症を疑うサインです。運動を直ちに中止し、医師に報告します。"}],"seccion":"疾患・外傷とリハビリ","grupo":"整形外科・外傷","icono":"🦴","mapa":"img/mapas/t32.jpg","fichas":[],"secuencias":[]},"33":{"id":33,"title":"よくある骨折","lead":"高齢者では骨粗鬆症を背景に、転倒による骨折が多くみられます。骨癒合の段階と医師の許可範囲を確認しながら、廃用を防ぎ機能を取り戻します。","sheet":{"kind":"condition","items":[{"h":"病態","t":"高齢者では骨粗鬆症を背景に、転倒で大腿骨近位部、橈骨遠位端、上腕骨近位端、脊椎椎体の骨折が起こりやすい。若年者では高エネルギー外傷が多い。"},{"h":"主な症状","t":"受傷部の痛み、腫脹、変形、皮下出血、機能障害。大腿骨近位部骨折では立てない・患肢の短縮と外旋、圧迫骨折では体動時の背部痛。"},{"h":"評価のポイント","t":"骨折型と固定法、荷重・可動域の許可範囲を医師に確認。疼痛、腫脹、隣接関節のROM、筋力、神経・循環、受傷前のADLと認知機能。"},{"h":"介入の流れ","t":"固定期は固定外の関節を動かし腫脹と拘縮を予防する。骨癒合と医師の許可に応じてROM・荷重・筋力訓練を進める。高齢者は早期離床と転倒予防。"},{"h":"注意点・禁忌","t":"許可範囲を超える荷重やROMは行わない。長期臥床による廃用、肺炎、褥瘡、せん妄に注意。橈骨遠位端骨折後は手指のこわばりに注意する。"},{"h":"医師につなぐサイン","t":"固定内の強い痛み、しびれ、指の色調変化（循環障害やコンパートメント症候群の疑い）、急な痛みの増悪や変形、ふくらはぎの腫れ、発熱。"}]},"keypoints":["高齢者は骨粗鬆症を背景とした転倒骨折が多い","荷重とROMの許可範囲は必ず医師に確認する","固定中も固定外の関節は積極的に動かす","大腿骨近位部骨折は早期離床で廃用を防ぐ","再骨折予防に転倒予防と骨粗鬆症対策を行う"],"case":{"text":"82歳女性。自宅で転倒し、右股関節痛で立てなくなった。右下肢は短縮・外旋位。大腿骨転子部骨折に対し骨接合術を受け、術翌日にリハビリが処方された。","answer":"医師に荷重の許可範囲を確認し、早期離床と歩行練習を進め、廃用・肺炎・せん妄を予防する。受傷前のADLを目標の目安とし、退院に向けて転倒予防と骨粗鬆症対策も指導する。"},"questions":[{"level":"基礎","q":"高齢者が手をついて転倒した際に起こりやすい骨折はどれか。","options":["舟状骨骨折","橈骨遠位端骨折","肘頭骨折","中手骨骨折"],"answer":1,"exp":"高齢者の手をついた転倒では橈骨遠位端骨折が代表的です。遠位骨片が背側に転位するものをコーレス骨折と呼びます。"},{"level":"基礎","q":"大腿骨近位部骨折でみられやすい患肢の肢位はどれか。","options":["患肢の延長・内旋","変化はみられない","患肢の短縮・外旋","患肢の延長・外転"],"answer":2,"exp":"大腿骨近位部骨折では、患肢の短縮と外旋がみられやすく、立位や歩行が困難になります。"},{"level":"中級","q":"骨折の固定期に行う理学療法として適切なのはどれか。","options":["固定部位の強い他動ROM","許可前の全荷重歩行","骨折部への強いマッサージ","固定外の関節の運動"],"answer":3,"exp":"固定期は骨折部を守りつつ、固定外の関節を動かして腫脹・拘縮・筋力低下を予防します。"},{"level":"中級","q":"大腿骨近位部骨折術後の高齢者で早期離床を図る主な目的はどれか。","options":["骨折型を判定するため","廃用症候群を予防するため","手術の代わりとするため","骨癒合を不要にするため"],"answer":1,"exp":"高齢者は臥床が続くと筋力低下、肺炎、褥瘡、せん妄などの廃用が進みやすいため、早期離床を図ります。"},{"level":"臨床","q":"橈骨遠位端骨折でギプス固定中の70歳女性。手指が強く腫れ、しびれと色調変化を訴える。適切な対応はどれか。","options":["手指の運動を強化する","温熱療法を行う","速やかに医師に報告する","次回まで様子をみる"],"answer":2,"exp":"固定内の強い腫脹、しびれ、色調変化は循環障害やコンパートメント症候群を疑うサインです。速やかに医師へ報告します。"},{"level":"臨床","q":"85歳女性。腰椎圧迫骨折で背部痛があり、医師から離床の許可が出た。適切な対応はどれか。","options":["許可範囲で離床を進める","臥床を続けて様子をみる","体幹の強い屈曲運動を行う","重い物を持ち上げる練習"],"answer":0,"exp":"許可範囲で離床を進め、廃用を防ぎます。圧迫骨折では体幹の強い屈曲や重量物の持ち上げは負担となるため避けます。"}],"seccion":"疾患・外傷とリハビリ","grupo":"整形外科・外傷","icono":"🦴","mapa":"img/mapas/t33.jpg","fichas":[],"secuencias":[]},"34":{"id":34,"title":"腰痛・椎間板ヘルニア","lead":"腰痛の多くは原因を特定できない非特異的腰痛ですが、神経根症状や重篤な疾患を見分けることが重要です。危険信号を除外し、活動を保つ支援をします。","sheet":{"kind":"condition","items":[{"h":"病態","t":"腰痛の多くは原因を特定できない非特異的腰痛。椎間板ヘルニアは髄核が線維輪を破って突出し、神経根を圧迫する。L4/5、L5/S1に多い。"},{"h":"主な症状","t":"腰痛と片側の下肢痛（坐骨神経痛）、しびれ、前屈や座位での増悪。障害された神経根に応じた感覚低下、筋力低下、反射低下。"},{"h":"評価のポイント","t":"SLRテスト（上位腰椎ではFNST）、デルマトーム、MMT（L5：母趾背屈、S1：足関節底屈）、腱反射（S1：アキレス腱反射）。"},{"h":"介入の流れ","t":"患者教育で不安を減らし、可能な範囲で活動を保つ。症状を軽くする姿勢や運動を探し、体幹・下肢の運動療法と段階的な活動量の増加を行う。"},{"h":"注意点・禁忌","t":"長期の安静は勧めない。下肢症状が足先へ広がる運動は中止する。恐怖回避などの心理社会的要因が慢性化に関与する。"},{"h":"医師につなぐサイン","t":"膀胱直腸障害やサドル麻痺（馬尾症候群）、進行する筋力低下、発熱、原因不明の体重減少、がんの既往、外傷後の強い痛み。"}]},"keypoints":["腰痛の多くは非特異的腰痛","L4/5ヘルニアではL5神経根が障害されやすい","SLRテストは下位腰椎の神経根症状を評価する","長期安静より可能な範囲で活動を保つ","膀胱直腸障害・サドル麻痺は緊急で医師へ"],"case":{"text":"35歳男性、デスクワーク。重い物を持ち上げた後から腰痛と左下腿外側〜足背のしびれが出現。左SLRで下肢痛が再現し、左母趾背屈の筋力低下を認める。排尿障害はない。","answer":"L4/5椎間板ヘルニアによるL5神経根障害を疑う。教育と可能な範囲での活動維持、症状を悪化させない運動を行い、筋力低下の推移を再評価する。麻痺の進行や膀胱直腸障害が出たら直ちに医師へ。"},"questions":[{"level":"基礎","q":"腰椎椎間板ヘルニアが最も多い高位はどれか。","options":["L1/2","L2/3","L3/4","L4/5"],"answer":3,"exp":"腰椎椎間板ヘルニアはL4/5に最も多く、次いでL5/S1に多くみられます。"},{"level":"基礎","q":"椎間板ヘルニアで突出するのは主にどの組織か。","options":["髄核","黄色靭帯","椎弓","棘突起"],"answer":0,"exp":"椎間板中心部の髄核が線維輪の亀裂から突出し、神経根などを圧迫します。"},{"level":"中級","q":"L5神経根障害で筋力低下がみられやすい運動はどれか。","options":["足関節底屈","母趾背屈","膝伸展","股関節屈曲"],"answer":1,"exp":"L5神経根は長母趾伸筋を支配し、障害されると母趾背屈の筋力が低下します。足関節底屈はS1です。"},{"level":"中級","q":"S1神経根障害で低下しやすい腱反射はどれか。","options":["膝蓋腱反射","上腕二頭筋反射","アキレス腱反射","腕橈骨筋反射"],"answer":2,"exp":"アキレス腱反射はS1が主に関与します。膝蓋腱反射は主にL4の評価に用います。"},{"level":"臨床","q":"急性腰痛の40歳女性。レッドフラッグはない。適切な指導はどれか。","options":["2週間の絶対安静","痛みが消えるまで休職","すべての運動を禁止","可能な範囲で活動を保つ"],"answer":3,"exp":"レッドフラッグのない急性腰痛では、長期の安静より可能な範囲で日常活動を保つことが勧められます。"},{"level":"臨床","q":"腰痛と両下肢のしびれがある患者が、尿が出にくく肛門周囲の感覚が鈍いと訴えた。対応はどれか。","options":["運動療法を続ける","牽引療法を行う","直ちに医師に連絡する","次回まで様子をみる"],"answer":2,"exp":"膀胱直腸障害とサドル麻痺は馬尾症候群を疑う緊急のサインです。直ちに医師に連絡します。"}],"seccion":"疾患・外傷とリハビリ","grupo":"脊椎","icono":"🧍","mapa":"img/mapas/t34.jpg","fichas":[],"secuencias":[]},"35":{"id":35,"title":"頸部痛","lead":"頸部痛の多くは非特異的な痛みですが、神経根症や脊髄症を見分けることが重要です。危険なサインを確認したうえで、運動療法と姿勢の調整を行います。","sheet":{"kind":"condition","items":[{"h":"病態","t":"非特異的頸部痛が多い。椎間板や骨棘で神経根が圧迫されると神経根症、脊髄が圧迫されると脊髄症となる。外傷では外傷性頸部症候群がある。"},{"h":"主な症状","t":"頸部痛、可動域制限、肩甲部痛。神経根症では片側上肢の痛み・しびれ。脊髄症では両手のしびれ、巧緻性低下（箸・ボタン）、歩行障害。"},{"h":"評価のポイント","t":"頸部ROM、スパーリングテスト、デルマトーム、MMT、腱反射（C6：腕橈骨筋、C7：上腕三頭筋）、ホフマン反射、歩行、姿勢。"},{"h":"介入の流れ","t":"教育と活動の維持、頸部・肩甲帯の運動療法（深部頸部屈筋の運動など）、姿勢と作業環境の調整。徒手療法は評価に基づき慎重に行う。"},{"h":"注意点・禁忌","t":"脊髄症が疑われる場合は頸部への強い手技を避ける。めまい、複視、構音障害などが出る手技や運動はすぐに中止する。"},{"h":"医師につなぐサイン","t":"両手のしびれと巧緻性低下・歩行障害、進行する麻痺、外傷後の痛み、発熱、めまい・構音障害・嚥下障害、原因不明の体重減少。"}]},"keypoints":["頸部痛の多くは非特異的頸部痛","スパーリングテストは神経根症の評価に用いる","両手の巧緻性低下と歩行障害は脊髄症を疑う","深部頸部屈筋と肩甲帯の運動療法を行う","脊髄症が疑われるときは頸部への強い手技を避ける"],"case":{"text":"45歳女性、事務職。1か月前から頸部痛と右母指のしびれがある。頸部を右へ伸展・側屈すると右上肢に放散痛が出る。右腕橈骨筋反射の低下を認める。","answer":"右C6神経根症を考える。症状を悪化させない範囲で教育、運動療法、姿勢・作業環境の調整を行う。筋力低下の進行や、両手のしびれ・歩行障害など脊髄症のサインがあれば医師へ。"},"questions":[{"level":"基礎","q":"頸椎症性脊髄症を示唆する症状はどれか。","options":["片側の肩甲部痛のみ","両手の巧緻性低下","頸部の筋のこり","頭痛のみ"],"answer":1,"exp":"脊髄の圧迫では両手のしびれや巧緻性低下（箸・ボタン操作の困難）、歩行障害がみられます。"},{"level":"基礎","q":"深部頸部屈筋の運動として代表的なものはどれか。","options":["頸部の強い伸展運動","頸部の急速な回旋","顎を引く頭頸部屈曲運動","肩をすくめる運動"],"answer":2,"exp":"顎を軽く引く頭頸部屈曲運動は、頸長筋などの深部頸部屈筋の活動を高める代表的な運動です。"},{"level":"中級","q":"スパーリングテストの陽性所見はどれか。","options":["頸部伸展・側屈で上肢に放散痛","頸部屈曲で背部に電撃痛","肩外転で症状が軽減する","手関節屈曲でしびれが出る"],"answer":0,"exp":"頸部を患側へ伸展・側屈し軸圧を加え、上肢に放散痛やしびれが出れば神経根症を疑います。"},{"level":"中級","q":"C7神経根障害で低下しやすい腱反射はどれか。","options":["上腕二頭筋反射","腕橈骨筋反射","上腕三頭筋反射","膝蓋腱反射"],"answer":2,"exp":"上腕三頭筋反射は主にC7、上腕二頭筋反射はC5、腕橈骨筋反射はC6の評価に用います。"},{"level":"臨床","q":"60歳男性。最近ボタンがかけにくく、歩行がふらつく。ホフマン反射陽性。最も疑う病態はどれか。","options":["非特異的頸部痛","胸郭出口症候群","手根管症候群","頸椎症性脊髄症"],"answer":3,"exp":"巧緻性低下、歩行障害、病的反射は脊髄症を示唆します。頸部への強い手技は避け、医師の評価につなげます。"},{"level":"臨床","q":"頸部痛の患者。頸部回旋の運動中にめまいと複視が出現した。適切な対応はどれか。","options":["運動を続けて慣らす","直ちに中止し医師へ","可動域をさらに広げる","温熱療法に切り替える"],"answer":1,"exp":"めまいや複視は血管性・神経学的な問題の可能性があるサインです。直ちに中止し、医師の評価につなげます。"}],"seccion":"疾患・外傷とリハビリ","grupo":"脊椎","icono":"🧍","mapa":"img/mapas/t35.jpg","fichas":[],"secuencias":[]},"36":{"id":36,"title":"側弯症","lead":"側弯症は脊柱が側方に弯曲し、椎体の回旋を伴う三次元的な変形です。成長期に進行しやすく、早期発見と定期的な経過観察が重要です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"脊柱が前額面で側方に弯曲し、椎体の回旋を伴う三次元的な変形。原因不明の特発性が多く、思春期の女子に多い。機能性側弯とは区別する。"},{"h":"主な症状","t":"多くは痛みが少なく、肩の高さ、肩甲骨、ウエストラインの左右差や、前屈時の肋骨隆起・腰部隆起で気づかれる。高度になると呼吸機能に影響する。"},{"h":"評価のポイント","t":"立位での肩・骨盤・ウエストの対称性、前屈テスト、脚長差（機能性との鑑別）、柔軟性、呼吸。弯曲の程度はX線のコブ角で医師が評価する。"},{"h":"介入の流れ","t":"経過観察・装具療法・手術の方針は成長段階とコブ角をもとに医師が決める。理学療法は体幹の運動療法、呼吸練習、装具装着の継続支援を行う。"},{"h":"注意点・禁忌","t":"成長期は進行しやすく定期的な経過観察が重要。運動療法だけで矯正できるとは説明しない。装具の装着時間は医師の指示に従う。"},{"h":"医師につなぐサイン","t":"強い痛みや夜間痛、しびれ・筋力低下などの神経症状、急速な進行、非典型的なカーブ（左凸の胸椎カーブなど）、発熱。"}]},"keypoints":["側弯症は椎体の回旋を伴う三次元的な変形","代表は思春期の女子に多い特発性側弯症","前屈テストで肋骨隆起を確認する","成長期は進行しやすく定期的な経過観察が重要","痛みや神経症状を伴う側弯は医師へつなぐ"],"case":{"text":"13歳女子。学校検診で側弯を指摘された。立位で右肩が高く、前屈で右背部に肋骨隆起を認める。痛みや神経症状はない。整形外科で装具療法が処方された。","answer":"思春期特発性側弯症を考える。理学療法では装具装着の継続を支援し、体幹の運動療法や呼吸練習を行う。運動だけで治るとは説明しない。痛みや神経症状、急な進行があれば医師へ。"},"questions":[{"level":"基礎","q":"側弯症のスクリーニングで前屈テストを行うとき観察する所見はどれか。","options":["膝の過伸展","肋骨隆起","足部の扁平化","頸部前弯の増強"],"answer":1,"exp":"前屈テストでは背部を後方から観察し、椎体の回旋に伴う肋骨隆起や腰部隆起の有無を確認します。"},{"level":"基礎","q":"側弯の弯曲の程度を評価する指標はどれか。","options":["Q角","頸体角","コブ角","大腿脛骨角"],"answer":2,"exp":"側弯の程度はX線像でカーブの上下端の椎体から角度を測るコブ角で評価します。"},{"level":"中級","q":"特発性側弯症の特徴として正しいのはどれか。","options":["高齢男性に多い","思春期の女子に多い","必ず強い痛みを伴う","前額面だけの変形である"],"answer":1,"exp":"特発性側弯症は思春期の女子に多く、多くは痛みが少ないです。椎体の回旋を伴う三次元的な変形です。"},{"level":"中級","q":"機能性側弯の原因として考えられるのはどれか。","options":["椎体の先天奇形","神経筋疾患","椎体の回旋変形","脚長差"],"answer":3,"exp":"脚長差や疼痛による逃避姿勢などで生じる機能性側弯は、原因を取り除くと改善し、構築性側弯とは区別します。"},{"level":"臨床","q":"装具療法中の14歳女子。装具がきついため、自己判断で装着時間を減らしている。理学療法士の対応はどれか。","options":["装具をやめて運動のみ","装着継続を支援し医師と相談","装着時間をさらに減らす","問題ないと伝える"],"answer":1,"exp":"装着時間は医師の指示に従うことが重要です。困りごとを聞いて継続を支援し、装具の適合は医師や義肢装具士と相談します。"},{"level":"臨床","q":"12歳男子。側弯があり、夜間に強い背部痛で目が覚める。適切な対応はどれか。","options":["ストレッチを指導する","様子をみる","運動量を増やす","医師の評価につなぐ"],"answer":3,"exp":"強い痛みや夜間痛を伴う側弯は、腫瘍など他の原因が隠れている可能性があるため、医師の評価につなげます。"}],"seccion":"疾患・外傷とリハビリ","grupo":"脊椎","icono":"🧍","mapa":"img/mapas/t36.jpg","fichas":[],"secuencias":[]},"37":{"id":37,"title":"脳卒中","lead":"脳の血管が詰まる、または破れることで神経症状が急に生じる疾患です。早期離床と課題指向型の反復練習が機能回復の土台になります。","sheet":{"kind":"condition","items":[{"h":"病態","t":"脳梗塞（アテローム血栓性・心原性塞栓・ラクナ）、脳出血、くも膜下出血に大別されます。病変の部位と大きさで症状が異なります。"},{"h":"主な症状","t":"片麻痺、感覚障害、痙縮、失語、半側空間無視、構音障害、嚥下障害、注意障害などの高次脳機能障害がみられます。"},{"h":"評価のポイント","t":"ブルンストロームステージ、SIAS、FMAで麻痺を、MASで痙縮を、BBSでバランスを、FIMでADLを評価します。"},{"h":"フェーズ別","t":"急性期はリスク管理下での早期離床、回復期は課題指向型練習と歩行練習、生活期は活動と参加の維持を図ります。"},{"h":"注意点・禁忌","t":"急性期は血圧・意識・神経症状の変動に注意します。麻痺側上肢の牽引や不適切な介助は肩の痛みを招きます。"},{"h":"医師につなぐ","t":"意識レベルの低下、麻痺や構音障害の急な悪化、激しい頭痛、嘔吐、血圧の急変がみられたら直ちに報告します。"}]},"keypoints":["離床の開始と中止は医師の指示と中止基準に沿う","麻痺側の肩は引っ張らず、ポジショニングで保護する","半側空間無視には無視側への注意を促す課題と環境調整","課題指向型の反復練習が機能回復の基本となる","装具は歩行能力と目標に合わせて段階的に検討する"],"case":{"text":"68歳男性、右中大脳動脈領域の脳梗塞で発症後3週。左片麻痺（下肢ブルンストロームステージIII）。車椅子で左側の物によくぶつかり、左側の食事を残す。","answer":"考え方: 左半側空間無視が疑われ、転倒や接触の危険が高い状態です。左側への注意を促す課題と環境調整を行い、見守り下で練習します。無視が残るうちに自立移動を許可することは避けます。"},"questions":[{"level":"基礎","q":"中大脳動脈領域の脳梗塞で典型的にみられる片麻痺の分布はどれか？","options":["下肢優位の片麻痺","上肢・顔面優位の片麻痺","両下肢の対麻痺","左右対称の四肢麻痺"],"answer":1,"exp":"中大脳動脈は大脳半球の外側面を灌流し、上肢・顔面の運動野を含むため上肢・顔面優位になります。下肢優位は前大脳動脈領域です。"},{"level":"基礎","q":"左半側空間無視が生じやすい病変部位はどれか？","options":["左前頭葉","小脳","右頭頂葉","脳幹"],"answer":2,"exp":"左半側空間無視は右大脳半球、特に右頭頂葉の病変で生じやすい症状です。"},{"level":"中級","q":"ブルンストロームステージで、共同運動が随意的に十分出現する段階はどれか？","options":["ステージII","ステージIV","ステージVI","ステージIII"],"answer":3,"exp":"ステージIIIは共同運動が随意的に十分出現する段階です。IIは連合反応や共同運動が出始める段階、IVは分離運動が一部可能な段階です。"},{"level":"中級","q":"脳卒中後の痙縮の評価に用いる尺度はどれか？","options":["MAS","FIM","BBS","MMSE"],"answer":0,"exp":"MASは他動運動時の抵抗で筋緊張を段階づけます。FIMはADL、BBSはバランス、MMSEは認知機能の評価です。"},{"level":"臨床","q":"脳卒中後、麻痺側の肩に亜脱臼があり、移乗介助時に肩の痛みを訴える。適切な対応はどれか？","options":["麻痺側の腕を引いて介助する","肩を支持し上肢を牽引しない","痛みが消えるまで完全に固定","肩の強い他動伸張を毎日行う"],"answer":1,"exp":"亜脱臼肩は牽引で痛みや損傷を招きます。支持具やポジショニングで保護し、痛みのない範囲で可動域を維持します。"},{"level":"臨床","q":"急性期脳梗塞の患者。離床練習中に構音障害と麻痺が急に悪化した。適切な対応はどれか？","options":["そのまま歩行練習を続ける","休憩後に練習を再開する","中止して直ちに医師へ報告","翌日に再評価する"],"answer":2,"exp":"神経症状の急な悪化は病変の拡大や再発の可能性があります。練習を中止して安全を確保し、直ちに医師へ報告します。"}],"seccion":"疾患・外傷とリハビリ","grupo":"神経","icono":"🧠","mapa":"img/mapas/t37.jpg","fichas":[],"secuencias":[]},"38":{"id":38,"title":"パーキンソン病","lead":"中脳黒質のドパミン神経細胞が変性し、運動症状が生じる進行性の神経変性疾患です。外部キューを使った運動と転倒予防が重要です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"中脳黒質のドパミン神経細胞が変性し、線条体のドパミンが不足して運動の調節が障害されます。症状はゆっくり進行します。"},{"h":"主な症状","t":"安静時振戦、筋強剛、無動・寡動、姿勢反射障害。すくみ足、小刻み歩行、前傾姿勢、便秘などの非運動症状もみられます。"},{"h":"評価のポイント","t":"ホーエン・ヤール重症度分類、MDS-UPDRS、BBS、TUG、歩行速度、すくみ足の有無、転倒歴、薬の効果の日内変動を確認します。"},{"h":"介入の流れ","t":"初期は全身運動と体力維持、進行に応じて視覚・聴覚キューを使った歩行練習、バランス練習、転倒予防と環境調整を行います。"},{"h":"注意点・禁忌","t":"薬の効果の変動（ウェアリングオフ、ジスキネジア）に合わせて練習時間を調整します。起立性低血圧にも注意します。"},{"h":"医師につなぐ","t":"症状の急な悪化、薬の効く時間の短縮、幻覚、転倒の反復、嚥下障害の進行、高熱と強い筋強剛がみられたら報告します。"}]},"keypoints":["練習は薬が効いている「オン」の時間帯に設定する","床の線やリズム音などの外部キューですくみ足を軽減","大きく、ゆっくりした動きを意識して反復練習する","方向転換と二重課題の場面は転倒の危険が高い","体幹の伸展と回旋の運動で前傾姿勢に対応する"],"case":{"text":"72歳女性、パーキンソン病（ホーエン・ヤールIII度）。狭い出入口や方向転換で足がすくみ、自宅で転倒をくり返している。薬が切れる時間帯に症状が強い。","answer":"考え方: すくみ足と姿勢反射障害による転倒の危険が高い状態です。オンの時間帯に視覚・聴覚キューを用いた歩行と方向転換を練習し、住環境を整えます。薬の調整は医師に相談し、自己判断で変更させません。"},"questions":[{"level":"基礎","q":"パーキンソン病で主に変性する部位はどれか？","options":["小脳","中脳黒質","脊髄前角","大脳皮質運動野"],"answer":1,"exp":"中脳黒質のドパミン神経細胞が変性し、線条体のドパミンが減少することで運動症状が生じます。"},{"level":"基礎","q":"パーキンソン病の振戦の特徴として正しいのはどれか？","options":["企図振戦","動作時に強くなる","安静時振戦","睡眠中も続く"],"answer":2,"exp":"安静時に出現し、随意運動で軽くなるのが特徴です。企図振戦は小脳障害でみられます。"},{"level":"中級","q":"ホーエン・ヤール重症度分類のIII度の特徴はどれか？","options":["姿勢反射障害が出現","一側性の症状のみ","車椅子・寝たきり","両側性で姿勢反射は正常"],"answer":0,"exp":"III度は両側性の症状に姿勢反射障害が加わる段階です。I度は一側性、II度は両側性で姿勢反射は正常、V度は車椅子・寝たきりです。"},{"level":"中級","q":"すくみ足の軽減に用いられる方法はどれか？","options":["目を閉じて歩く","急に歩行速度を上げる","狭い通路をくり返し歩く","床の線などの視覚キュー"],"answer":3,"exp":"床の線やメトロノームの音などの外部キューは、すくみ足の軽減や歩幅の改善に用いられます。"},{"level":"臨床","q":"パーキンソン病の患者。服薬は朝と昼で、午後遅くになると動作が遅くなり練習が進まない。適切な対応はどれか？","options":["午後の練習量を増やす","練習をオンの時間帯に合わせる","服薬量を本人に調整させる","理学療法を中止する"],"answer":1,"exp":"薬の効果の変動（ウェアリングオフ）が疑われます。練習は効果のある時間帯に設定し、変動は医師に報告します。服薬の調整は医師が行います。"},{"level":"臨床","q":"服薬を急に中断したパーキンソン病の患者に、高熱、著しい筋強剛、意識障害がみられた。対応はどれか？","options":["軽い運動で様子を見る","ストレッチを強化する","練習を中止し直ちに医師へ","翌日の練習で再評価する"],"answer":2,"exp":"薬の急な中断後の高熱・筋強剛・意識障害は悪性症候群が疑われ、緊急の対応が必要です。直ちに医師へ報告します。"}],"seccion":"疾患・外傷とリハビリ","grupo":"神経","icono":"🧠","mapa":"img/mapas/t38.jpg","fichas":[],"secuencias":[]},"39":{"id":39,"title":"多発性硬化症","lead":"中枢神経の髄鞘が炎症で障害され、再発と寛解をくり返すことの多い疾患です。疲労と体温の上昇に配慮して運動量を調整することが鍵です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"脳・脊髄・視神経に脱髄病変が時間的・空間的に多発する自己免疫性の疾患です。若年成人、特に女性に多いとされます。"},{"h":"主な症状","t":"視力障害（視神経炎）、筋力低下、感覚障害、痙縮、運動失調、疲れやすさ、膀胱直腸障害、レルミット徴候などがみられます。"},{"h":"評価のポイント","t":"EDSS、MMT、MAS、バランス、歩行能力、疲労の程度を評価します。症状の日内変動と体温による変化も確認します。"},{"h":"介入の流れ","t":"再発期は安静と愛護的な可動域運動、寛解期は有酸素運動・筋力増強・バランス練習を疲労に応じて段階的に行います。"},{"h":"注意点・禁忌","t":"体温の上昇で症状が一時的に悪化する（ウートフ現象）ため、高温の環境と過負荷を避け、休息を挟んで実施します。"},{"h":"医師につなぐ","t":"新たな視力低下、しびれや麻痺の出現・急な悪化が24時間以上続く場合は再発の可能性があり、医師へ報告します。"}]},"keypoints":["運動は涼しい環境で行い、体温の上昇を避ける","疲労が強い日は運動量を減らし、休息を挟む","再発期と寛解期で運動の内容を切り替える","エネルギー温存の工夫をADL指導に取り入れる","痙縮にはストレッチとポジショニングで対応する"],"case":{"text":"32歳女性、多発性硬化症（寛解期）。室温の高い訓練室で運動中、下肢の脱力としびれが強くなったが、休憩して体を冷やすと30分ほどで元に戻った。","answer":"考え方: 体温の上昇による一時的な症状の悪化（ウートフ現象）が考えられます。涼しい環境で休息を挟み、運動強度を調整します。休息しても改善せず症状が続く場合は再発を疑い、医師へ報告します。"},"questions":[{"level":"基礎","q":"多発性硬化症で主に障害される構造はどれか？","options":["末梢神経の髄鞘","中枢神経の髄鞘","神経筋接合部","骨格筋線維"],"answer":1,"exp":"脳・脊髄・視神経など中枢神経の髄鞘が障害されます。末梢神経の脱髄はギラン・バレー症候群などでみられます。"},{"level":"基礎","q":"体温の上昇で症状が一時的に悪化する現象はどれか？","options":["レルミット徴候","ロンベルグ徴候","バビンスキー反射","ウートフ現象"],"answer":3,"exp":"ウートフ現象は体温の上昇で症状が一時的に悪化する現象です。レルミット徴候は頸部前屈で背部から四肢に電撃痛が走る徴候です。"},{"level":"中級","q":"多発性硬化症の再発期の理学療法として適切なのはどれか？","options":["高強度の筋力増強運動","長時間の有酸素運動","愛護的な関節可動域運動","高温の環境での運動"],"answer":2,"exp":"再発期は炎症が活動的なため、過負荷を避け、愛護的な可動域運動とポジショニングを中心にします。"},{"level":"中級","q":"頸部前屈で背部から四肢に電撃様の痛みが走る徴候はどれか？","options":["レルミット徴候","ウートフ現象","ホフマン反射","トレンデレンブルグ徴候"],"answer":0,"exp":"レルミット徴候は頸髄の病変で生じやすく、多発性硬化症でみられる代表的な徴候です。"},{"level":"臨床","q":"多発性硬化症の患者。夕方になると疲労が強く歩行が不安定になる。適切な指導はどれか？","options":["夕方に運動量を増やす","活動を体調のよい時間に配分","休息をとらずに続けさせる","温かい部屋で運動する"],"answer":1,"exp":"疲れやすさにはエネルギー温存の考え方で対応し、活動を体調のよい時間帯に配分して休息を計画的に入れます。"},{"level":"臨床","q":"寛解期の多発性硬化症の患者。数日前から片眼の視力低下と新たな下肢のしびれが続いている。対応はどれか？","options":["運動強度を上げる","温熱療法を追加する","再発を疑い医師へ報告","1か月後に再評価する"],"answer":2,"exp":"新たな神経症状が続く場合は再発の可能性があります。運動の負荷を上げず、速やかに医師へ報告します。"}],"seccion":"疾患・外傷とリハビリ","grupo":"神経","icono":"🧠","mapa":"img/mapas/t39.jpg","fichas":[],"secuencias":[]},"40":{"id":40,"title":"脊髄損傷","lead":"脊髄の損傷により、損傷高位より下の運動・感覚・自律神経の機能が障害されます。残存機能に応じた目標設定と合併症の予防が中心です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"転落や交通事故などの外傷や疾患で脊髄が損傷され、完全損傷と不全損傷に分かれます。頸髄損傷は四肢麻痺、胸腰髄損傷は対麻痺となります。"},{"h":"主な症状","t":"損傷高位以下の運動麻痺と感覚障害、膀胱直腸障害、自律神経障害（起立性低血圧、体温調節障害）、痙縮がみられます。"},{"h":"評価のポイント","t":"ASIAの基準で神経学的高位とAISを判定し、髄節ごとの主要筋のMMTと感覚検査を行います。ADLはFIMやSCIMで評価します。"},{"h":"介入の流れ","t":"急性期は呼吸管理・ポジショニング・可動域の維持、回復期は残存筋の強化と、起き上がり・移乗・車椅子駆動などのADL練習を行います。"},{"h":"注意点・禁忌","t":"T6以上の損傷では自律神経過反射に注意します。褥瘡予防の除圧を指導し、起立性低血圧には段階的な起立で対応します。"},{"h":"医師につなぐ","t":"急な血圧上昇と頭痛・発汗・顔面紅潮、神経症状の悪化、発熱、褥瘡の悪化、下肢の腫脹（深部静脈血栓症の疑い）は報告します。"}]},"keypoints":["神経学的高位は機能が正常な最も尾側の髄節","C6損傷ではテノデーシスアクションを把持に使う","自律神経過反射は座位にして膀胱充満などの誘因を除く","定期的な除圧動作で褥瘡を予防する","頸髄損傷では呼吸機能の評価と排痰の援助を行う"],"case":{"text":"25歳男性、C6完全損傷（AIS A）で受傷後2か月。練習中に急に激しい頭痛、顔面紅潮、発汗が出現し、血圧が著明に上昇した。導尿の予定時刻を過ぎていた。","answer":"考え方: 膀胱充満を誘因とした自律神経過反射が疑われます。練習を中止して座位（頭部挙上）にし、衣服をゆるめ、誘因の確認と除去を行いながら直ちに医師・看護師へ報告します。臥位のまま様子を見ることは避けます。"},"questions":[{"level":"基礎","q":"C7髄節の主要筋で、プッシュアップによる移乗を可能にする筋はどれか？","options":["上腕二頭筋","上腕三頭筋","腸腰筋","大腿四頭筋"],"answer":1,"exp":"C7の主要筋は上腕三頭筋（肘伸展）です。上腕二頭筋はC5、腸腰筋はL2、大腿四頭筋はL3の主要筋です。"},{"level":"基礎","q":"テノデーシスアクションを把持に利用する代表的な損傷高位はどれか？","options":["C4","T6","C6","L3"],"answer":2,"exp":"C6損傷では手関節の背屈が可能で、背屈すると手指が受動的に屈曲するテノデーシスアクションを把持に使います。"},{"level":"中級","q":"ASIA機能障害尺度（AIS）のAが意味するのはどれか？","options":["感覚のみ残る不全損傷","運動機能が一部残る","神経学的に正常","S4-5の運動・感覚もない"],"answer":3,"exp":"AIS Aは仙髄最下部（S4-5）の運動・感覚機能が残っていない完全損傷です。Bは感覚のみ残る不全損傷です。"},{"level":"中級","q":"自律神経過反射が起こりやすい損傷高位はどれか？","options":["T6以上","T12以下","L3以下","馬尾"],"answer":0,"exp":"T6以上の損傷では、損傷部以下の刺激（膀胱充満など）で交感神経が過剰に反応し、急激な血圧上昇が起こります。"},{"level":"臨床","q":"C6損傷の患者。起立台で傾斜を上げたところ、めまいと顔面蒼白、血圧低下がみられた。対応はどれか？","options":["傾斜をさらに上げて慣らす","直ちに起立台を水平に戻す","そのまま練習を続ける","座位で頸部を前屈させる"],"answer":1,"exp":"起立性低血圧が疑われます。傾斜を戻して症状と血圧を確認します。腹帯や弾性ストッキング、段階的な起立で予防します。"},{"level":"臨床","q":"胸髄完全損傷の車椅子使用者。仙骨部の発赤が押しても消えずに続いている。適切な対応はどれか？","options":["発赤部を強くマッサージ","座位時間を延ばして慣らす","除圧の方法と頻度を見直す","特に対応は不要"],"answer":2,"exp":"持続する発赤は褥瘡の初期徴候です。除圧動作やクッションを見直し、医療チームに報告します。発赤部のマッサージは組織損傷を悪化させます。"}],"seccion":"疾患・外傷とリハビリ","grupo":"神経","icono":"🧠","mapa":"img/mapas/t40.jpg","fichas":[],"secuencias":[]},"41":{"id":41,"title":"末梢神経損傷","lead":"外傷や圧迫で末梢神経が障害され、支配領域の運動・感覚・自律神経の機能が低下します。損傷の程度と回復の経過を把握することが大切です。","sheet":{"kind":"condition","items":[{"h":"病態","t":"セドンの分類で、一過性の伝導障害（ニューラプラキシア）、軸索断裂（アクソノトメーシス）、神経断裂（ニューロトメーシス）に分けます。"},{"h":"主な症状","t":"支配筋の弛緩性麻痺と筋萎縮、支配領域の感覚障害、発汗障害がみられます。腱反射は低下または消失します。"},{"h":"評価のポイント","t":"MMT、感覚検査（触覚・痛覚・2点識別覚）、ティネル徴候の位置の推移、筋電図・神経伝導検査の結果を確認します。"},{"h":"介入の流れ","t":"装具で麻痺筋の過伸張を防ぎ、関節可動域を維持します。再神経支配に合わせて自動介助運動から筋力増強へ段階的に進めます。"},{"h":"注意点・禁忌","t":"感覚障害部位は熱傷や圧迫による損傷に注意します。麻痺筋への過負荷や、神経縫合術後の過度な伸張は避けます。"},{"h":"医師につなぐ","t":"麻痺の急な進行、強い痛みや腫脹、皮膚の色の変化、回復が予想される時期を過ぎても改善がない場合は報告します。"}]},"keypoints":["ティネル徴候が遠位へ移動すれば神経再生の目安","下垂手・下垂足には装具で拘縮と過伸張を予防する","感覚が低下した部位は目で確認して保護するよう指導","回復は損傷部に近い筋から遠い筋へ順に進む","神経縫合術後は医師が指示する固定期間を守る"],"case":{"text":"45歳男性、上腕骨骨幹部骨折の後から、手関節と手指の伸展ができない。手背の母指と示指の間に感覚低下がある。肘の伸展は可能。","answer":"考え方: 上腕骨骨幹部での橈骨神経麻痺（下垂手）が疑われます。手関節背屈位の装具で過伸張と拘縮を防ぎ、可動域を維持します。回復の経過はティネル徴候やMMTで追い、改善がなければ医師に報告します。"},"questions":[{"level":"基礎","q":"下垂手を生じる神経麻痺はどれか？","options":["正中神経","尺骨神経","橈骨神経","筋皮神経"],"answer":2,"exp":"橈骨神経は手関節と手指の伸筋群を支配し、麻痺すると手関節を背屈できない下垂手になります。"},{"level":"基礎","q":"環指・小指が変形する鷲手を生じる神経麻痺はどれか？","options":["尺骨神経","橈骨神経","腋窩神経","大腿神経"],"answer":0,"exp":"尺骨神経麻痺では骨間筋や環指・小指の虫様筋が麻痺し、環指・小指のかぎ爪変形（鷲手）が生じます。"},{"level":"中級","q":"セドンの分類で、軸索は保たれ伝導のみが一時的に障害された状態はどれか？","options":["神経断裂","ニューラプラキシア","軸索断裂","ワーラー変性"],"answer":1,"exp":"ニューラプラキシアは軸索の連続性が保たれた一過性の伝導障害で、ワーラー変性を伴わず比較的早く回復します。"},{"level":"中級","q":"末梢神経の再生の経過観察に用いられる所見はどれか？","options":["腱反射の亢進","バビンスキー反射","筋強剛","ティネル徴候の位置の移動"],"answer":3,"exp":"再生している軸索の先端部を叩くと放散するしびれが生じ、その位置が遠位へ移動することが再生の目安になります。"},{"level":"臨床","q":"下腿のギプス固定後、腓骨頭部の圧迫で足関節の背屈ができなくなった。適切な対応はどれか？","options":["足関節を底屈位で保持する","短下肢装具で下垂足に対応","麻痺筋に高負荷の抵抗運動","感覚低下部に強い温熱"],"answer":1,"exp":"総腓骨神経麻痺による下垂足には、短下肢装具で歩行時のつまずきと底屈拘縮を防ぎます。感覚低下部への温熱は熱傷の危険があります。"},{"level":"臨床","q":"手関節掌側の切創の後、母指の対立ができず母指球が萎縮してきた。障害が疑われる神経はどれか？","options":["尺骨神経","橈骨神経浅枝","正中神経","筋皮神経"],"answer":2,"exp":"正中神経は母指対立筋などの母指球筋を支配し、麻痺すると母指の対立が困難な猿手となります。"}],"seccion":"疾患・外傷とリハビリ","grupo":"神経","icono":"🧠","mapa":"img/mapas/t41.jpg","fichas":[],"secuencias":[]},"42":{"id":42,"title":"徒手療法（メイトランド）","lead":"関節の副運動を評価し、段階づけた振動的な他動運動で痛みと可動域に働きかける手技の体系です。評価と再評価のくり返しが特徴です。","sheet":{"kind":"method","items":[{"h":"目的","t":"関節の副運動を利用して痛みを軽減し、関節の可動性を改善します。患者の反応に基づいて手技と強さを選びます。"},{"h":"主な手技","t":"振動的な他動運動（オシレーション）をグレードI〜IVで行います。グレードVは高速・小振幅のスラスト（マニピュレーション）です。"},{"h":"適応","t":"関節由来の痛みや、関節包・靭帯の短縮による可動域制限（腰痛、頸部痛、凍結肩など）が主な対象です。"},{"h":"禁忌・注意","t":"骨折、悪性腫瘍、感染、炎症性疾患の急性期、高度の骨粗鬆症、進行する神経症状、頸部の血管障害の疑いでは行いません。"},{"h":"実施のポイント","t":"痛みが主体ならグレードI・II、こわばりが主体ならIII・IVを選びます。施行前後に比較徴候を確認し、効果を判定します。"},{"h":"エビデンス","t":"運動療法と組み合わせると短期的な痛みの軽減に有用とする報告があります。単独での長期的な効果は限定的とされます。"}]},"keypoints":["痛みが主体ならグレードI・II、硬さならIII・IV","施行前後に比較徴候を確認して効果を判定する","副運動は左右差と最終域感をみて評価する","レッドフラッグを除外してから手技を行う","得られた可動域は自主運動で維持させる"],"case":{"text":"50歳男性、慢性的な右頸部のこわばり。安静時痛はほとんどなく、右回旋の最終域で抵抗感と軽い痛みがある。レッドフラッグは認めない。","answer":"考え方: 痛みよりこわばりが主体のため、抵抗の中に入るグレードIII・IVの選択が考えられます。施行前後に回旋可動域と痛みを再評価し、自主運動につなげます。評価なしに強いスラストを行うことは避けます。"},"questions":[{"level":"基礎","q":"メイトランドのグレードIVの説明として正しいのはどれか？","options":["抵抗の手前で大きな振幅","可動域の始めで小さな振幅","可動域の終わりで小さな振幅","抵抗の中で大きな振幅"],"answer":2,"exp":"グレードIVは抵抗の中、可動域の終わりで行う小さな振幅の運動です。可動域の始めの小振幅はI、抵抗の中の大振幅はIIIです。"},{"level":"基礎","q":"主に痛みの軽減を目的として選ぶグレードはどれか？","options":["グレードI・II","グレードIII・IV","グレードVのみ","グレードIVのみ"],"answer":0,"exp":"グレードI・IIは抵抗に入らない範囲で行い、主に痛みの軽減に用います。III・IVはこわばりや可動域制限に用います。"},{"level":"中級","q":"メイトランドのグレードVが示す手技はどれか？","options":["抵抗の手前の大振幅","高速・小振幅のスラスト","持続的な牽引","軟部組織の揉捏"],"answer":1,"exp":"グレードVは可動域の終わりで行う高速・小振幅のスラストで、マニピュレーションにあたります。"},{"level":"中級","q":"手技の効果判定のため、施行前後に比べる指標はどれか？","options":["血液検査の値","画像所見の変化","体重の変化","比較徴候（アスタリスク）"],"answer":3,"exp":"施行前に再現性のある症状や可動域を比較徴候として記録し、施行後にその変化を確認して効果を判定します。"},{"level":"臨床","q":"急性腰痛の患者。動かすと強い痛みと防御性収縮がある。最初に選ぶグレードはどれか？","options":["グレードIV","グレードV","グレードI・II","グレードIII"],"answer":2,"exp":"痛みが強く反応しやすい状態では、抵抗に入らないグレードI・IIで痛みの軽減を図ります。"},{"level":"臨床","q":"頸部痛の患者。頸部を回旋するとめまい、複視、構音障害が出現した。対応はどれか？","options":["手技を中止し医師へ報告","グレードIVを強める","スラストで改善を図る","施行回数を増やす"],"answer":0,"exp":"めまい・複視・構音障害は頸部の血管障害を疑うサインです。徒手療法を中止し、医師へ報告します。"}],"seccion":"治療と介入","grupo":"手技と物理療法","icono":"🤲","mapa":"img/mapas/t42.jpg","fichas":[],"secuencias":[]},"43":{"id":43,"title":"固有受容性神経筋促通法（PNF）","lead":"固有受容器への刺激を利用して神経と筋の反応を促す治療手技です。らせん・対角線の運動パターンが特徴で、筋力・協調性・可動域の改善に用います。","sheet":{"kind":"method","items":[{"h":"目的","t":"固有受容器を刺激して運動の反応を促通し、筋力、協調性、安定性、関節可動域の改善を図ります。"},{"h":"主な手技","t":"肩甲帯・骨盤帯・四肢の対角線パターンに、リズミックイニシエーション、ホールドリラックス、リズミックスタビリゼーションなどを組み合わせます。"},{"h":"適応","t":"中枢神経疾患、整形外科疾患、スポーツ障害などで、筋力低下、協調性の低下、可動域制限、関節の不安定性がある場合に用います。"},{"h":"禁忌・注意","t":"骨癒合前の骨折部、術後で抵抗が許可されていない部位、強い痛みでは行いません。循環器のリスクがあれば息こらえに注意します。"},{"h":"実施のポイント","t":"用手接触、言語指示、視覚、牽引・圧縮、伸張、最適な抵抗、タイミングを組み合わせます。抵抗は円滑に動ける範囲にします。"},{"h":"エビデンス","t":"可動域の改善や筋機能の向上に有用とする報告があります。効果は疾患や目的で異なり、他の運動療法と組み合わせて用います。"}]},"keypoints":["痛みで可動域が制限される場合はホールドリラックス","運動の開始が困難な場合はリズミックイニシエーション","抵抗は円滑な運動を妨げない「最適な抵抗」にする","正常なタイミングでは運動は遠位から始まる","息こらえを避け、呼吸を止めずに実施させる"],"case":{"text":"60歳女性、肩関節周囲炎の後の外転制限。運動時の痛みが強く、他動的に伸張すると防御性収縮が強くなる。","answer":"考え方: 痛みを伴う可動域制限には、等尺性収縮を用いるホールドリラックスが適しています。痛みが強くならない範囲で行い、施行前後に可動域を再評価します。強い他動伸張をくり返すことは避けます。"},"questions":[{"level":"基礎","q":"PNFの運動パターンの特徴として正しいのはどれか？","options":["単一平面の直線運動","らせん・対角線の運動","等速性の運動のみ","他動運動のみ"],"answer":1,"exp":"PNFの運動パターンは、屈曲・伸展、内転・外転、回旋の要素を組み合わせたらせん・対角線の運動です。"},{"level":"基礎","q":"PNFで療法士の手を介して運動の方向を伝える基本要素はどれか？","options":["寒冷刺激","電気刺激","用手接触","超音波"],"answer":2,"exp":"用手接触は運動方向への圧を手で伝え、患者の筋収縮と運動の方向を導く基本要素です。"},{"level":"中級","q":"運動の開始が困難な患者に用いるPNFの技術はどれか？","options":["ホールドリラックス","コントラクトリラックス","リズミックスタビリゼーション","リズミックイニシエーション"],"answer":3,"exp":"リズミックイニシエーションは他動→自動介助→自動→抵抗運動の順に進め、運動の開始と学習を促します。"},{"level":"中級","q":"等尺性の交互収縮で関節の安定性を高める技術はどれか？","options":["リズミックスタビリゼーション","リズミックイニシエーション","コントラクトリラックス","反復伸張"],"answer":0,"exp":"リズミックスタビリゼーションは動かさずに拮抗筋群を交互に等尺性収縮させ、安定性を高めます。"},{"level":"臨床","q":"膝の屈曲可動域が痛みで制限されている患者。可動域の改善に適したPNFの技術はどれか？","options":["コントラクトリラックス","ホールドリラックス","反復伸張","リズミックイニシエーション"],"answer":1,"exp":"ホールドリラックスは制限している筋を等尺性に収縮させた後に弛緩させる技術で、痛みを伴う可動域制限に用います。"},{"level":"臨床","q":"PNFの抵抗運動中、患者が息を止めて顔が赤くなった。適切な対応はどれか？","options":["抵抗をさらに強める","反復回数を増やす","呼吸を止めないよう指導","運動の速度を上げさせる"],"answer":2,"exp":"息こらえは血圧の上昇を招きます。抵抗を調整し、呼吸を続けながら行うよう指導します。"}],"seccion":"治療と介入","grupo":"手技と物理療法","icono":"🤲","mapa":"img/mapas/t43.jpg","fichas":[],"secuencias":[]},"44":{"id":44,"title":"電気療法","lead":"電気刺激を用いて痛みの軽減や筋収縮の誘発を図る物理療法です。目的に応じて刺激の種類と条件を選び、禁忌を必ず確認します。","sheet":{"kind":"method","items":[{"h":"目的","t":"痛みの軽減、筋収縮の誘発による筋力の維持・増強、運動の再学習、浮腫の軽減などを目的とします。"},{"h":"主な種類","t":"TENS（経皮的電気神経刺激）、NMES（神経筋電気刺激）、FES（機能的電気刺激）、干渉波療法、高電圧パルス電流療法などがあります。"},{"h":"適応","t":"急性・慢性の痛み、術後や不動による筋力低下、脳卒中後の麻痺筋の促通、下垂足に対する歩行時の刺激などに用います。"},{"h":"禁忌・注意","t":"心臓ペースメーカーなどの植込み型電子機器、妊婦の腹部・腰部、頸動脈洞部、悪性腫瘍部、皮膚損傷部、感覚障害部位は避けます。"},{"h":"実施のポイント","t":"皮膚の状態と感覚を確認し、電極の位置と大きさ、周波数、パルス幅、強度、通電時間を目的に合わせて設定します。"},{"h":"エビデンス","t":"術後の大腿四頭筋の筋力低下や脳卒中後の機能回復に有用とする報告があります。痛みへの効果は報告によりばらつきがあります。"}]},"keypoints":["通電前に皮膚の状態と感覚障害の有無を確認する","植込み型電子機器の有無を必ず問診で確認する","痛みにはTENS、筋収縮の誘発にはNMESを選ぶ","終了後は電極の下に発赤や熱感がないか観察する","電気刺激は自動運動の練習と組み合わせて使う"],"case":{"text":"65歳男性、人工膝関節置換術後。大腿四頭筋の随意収縮が弱く、SLRで膝が伸びきらない（伸展不全）。心臓ペースメーカーはなく、皮膚の異常もない。","answer":"考え方: 大腿四頭筋の筋力低下と収縮不全に対し、NMESを自動運動と組み合わせて用いることが考えられます。術創を避けて電極を貼り、皮膚と痛みの反応を確認します。創部や感覚低下部への通電は避けます。"},"questions":[{"level":"基礎","q":"感覚レベルの刺激で、主に痛みの軽減を目的とする電気療法はどれか？","options":["FES","TENS","NMES","超音波療法"],"answer":1,"exp":"TENSは経皮的に感覚神経を刺激して痛みの軽減を図ります。NMESは筋収縮の誘発、FESは動作の補助が目的です。"},{"level":"基礎","q":"歩行などの動作に合わせて筋を刺激し、機能を補う電気療法はどれか？","options":["TENS","超音波療法","FES","ホットパック"],"answer":2,"exp":"FES（機能的電気刺激）は動作のタイミングに合わせて筋を刺激し、下垂足の歩行などの機能を補います。"},{"level":"中級","q":"電気療法の禁忌として正しいのはどれか？","options":["慢性腰痛","術後の筋力低下","下垂足","心臓ペースメーカーの植込み"],"answer":3,"exp":"植込み型電子機器は電気刺激で誤作動のおそれがあり禁忌とされます。ほかの選択肢は電気療法の適応です。"},{"level":"中級","q":"2つの中周波電流を交差させ、深部に低周波の刺激を生じさせる方法はどれか？","options":["干渉波療法","TENS","FES","イオントフォレーシス"],"answer":0,"exp":"干渉波療法は周波数の異なる2つの中周波電流を交差させ、その差の低周波刺激を深部に生じさせます。"},{"level":"臨床","q":"人工膝関節置換術後、大腿四頭筋の随意収縮が弱い患者。適切な選択はどれか？","options":["温熱療法のみを行う","NMESを自動運動と併用","創部の上に電極を貼る","筋収縮が戻るまで安静"],"answer":1,"exp":"NMESは術後の大腿四頭筋の収縮不全に用いられ、自動運動と組み合わせます。電極は術創を避けて貼ります。"},{"level":"臨床","q":"電気刺激の終了後、電極を貼っていた部位の皮膚に発赤と水疱がみられた。対応はどれか？","options":["強度を上げて続ける","同じ位置に再度貼る","中止し皮膚を確認・報告","温めて様子を見る"],"answer":2,"exp":"電極部の発赤や水疱は皮膚損傷の可能性があります。通電を中止し、皮膚の状態を記録して報告します。"}],"seccion":"治療と介入","grupo":"手技と物理療法","icono":"🤲","mapa":"img/mapas/t44.jpg","fichas":[],"secuencias":[]},"45":{"id":45,"title":"超音波・レーザー・温熱・寒冷療法","lead":"熱、音波、光、冷却を用いて痛みや組織の状態に働きかける物理療法です。時期と目的に応じて温めるか冷やすかを選び、禁忌を確認します。","sheet":{"kind":"method","items":[{"h":"目的","t":"痛みの軽減、筋緊張の緩和、組織の伸張性の向上、急性炎症による腫れの抑制などを目的に、運動療法の前後に用います。"},{"h":"主な種類","t":"超音波療法（連続・パルス）、低出力レーザー、表在温熱（ホットパック・パラフィン浴）、極超短波、寒冷療法（アイスパックなど）。"},{"h":"適応","t":"温熱は慢性期の痛み・こわばり・拘縮、寒冷は急性外傷後の痛みと腫れ、超音波は軟部組織の伸張性の向上などに用います。"},{"h":"禁忌・注意","t":"急性炎症・出血傾向・悪性腫瘍部への温熱、眼・妊婦の腹部・成長期の骨端線への超音波、レイノー現象がある部位への寒冷は避けます。"},{"h":"実施のポイント","t":"実施前に皮膚と温冷覚を確認し、施行中も皮膚を観察します。超音波のプローブは動かし続け、同じ部位にとどめません。"},{"h":"エビデンス","t":"運動療法の補助として短期的な痛みの軽減に用いられます。単独での効果は限定的とする報告が多く、中心は運動療法です。"}]},"keypoints":["急性期の腫れと熱感には寒冷、慢性のこわばりには温熱","施行前に温冷覚を確認し、感覚障害部位は避ける","超音波のプローブは止めずに動かし続ける","温熱の後に伸張や運動を行うと組み合わせやすい","物理療法は運動療法の補助として位置づける"],"case":{"text":"22歳男性、サッカー中に足関節を内反捻挫し、受傷翌日。外果周囲に腫れと熱感、圧痛があり、荷重時の痛みが強い。骨折は医師により否定されている。","answer":"考え方: 急性期の炎症所見があり、寒冷療法と圧迫・挙上で痛みと腫れの軽減を図ります。温熱は腫れを悪化させるおそれがあるため、この時期は避けます。凍傷を防ぐため、施行中は皮膚を観察します。"},"questions":[{"level":"基礎","q":"急性期の腫れと痛みの軽減に用いる物理療法はどれか？","options":["ホットパック","パラフィン浴","寒冷療法","極超短波"],"answer":2,"exp":"寒冷療法は血管を収縮させ、急性期の痛みと腫れを抑えます。ほかの選択肢は温熱療法で、急性炎症には避けます。"},{"level":"基礎","q":"表在温熱に分類されるものはどれか？","options":["極超短波","ホットパック","連続超音波","低出力レーザー"],"answer":1,"exp":"ホットパックやパラフィン浴は皮膚から浅い組織を温める表在温熱です。極超短波や連続超音波は深部温熱に分類されます。"},{"level":"中級","q":"超音波療法の禁忌部位として正しいのはどれか？","options":["大腿四頭筋","肩関節周囲","下腿三頭筋","眼球"],"answer":3,"exp":"眼球は超音波療法の禁忌部位です。妊婦の腹部、成長期の骨端線、悪性腫瘍部なども避けます。"},{"level":"中級","q":"超音波療法の実施方法として正しいのはどれか？","options":["プローブを動かし続ける","同じ部位で静止させる","ゲルを使わずに当てる","痛みが出ても続ける"],"answer":0,"exp":"プローブを一か所に止めると熱が集中して組織を傷める危険があるため、ゲルを用いて動かし続けます。"},{"level":"臨床","q":"受傷翌日の足関節捻挫で、腫れと熱感が強い。適切な物理療法はどれか？","options":["ホットパック","寒冷療法と圧迫・挙上","パラフィン浴","極超短波"],"answer":1,"exp":"急性期の炎症所見には寒冷療法と圧迫・挙上で痛みと腫れを抑えます。温熱は腫れを悪化させるおそれがあります。"},{"level":"臨床","q":"糖尿病性神経障害で足部の感覚が低下した患者に、足部へのホットパックが検討されている。適切な対応はどれか？","options":["温度を上げて短時間行う","通常どおり実施する","感覚低下部への温熱は避ける","就寝中に長時間当てる"],"answer":2,"exp":"感覚障害部位は熱さを感じにくく熱傷の危険が高いため、温熱療法は避け、ほかの方法を検討します。"}],"seccion":"治療と介入","grupo":"手技と物理療法","icono":"🤲","mapa":"img/mapas/t45.jpg","fichas":[],"secuencias":[]},"46":{"id":46,"title":"水治療法・マッサージ・用手的リンパドレナージ","lead":"水の浮力・水圧・温度を利用する水治療法と、手で軟部組織に働きかけるマッサージ・用手的リンパドレナージです。適応と禁忌の見極めが要になります。","sheet":{"kind":"method","items":[{"h":"目的","t":"水治療法は浮力・水圧・温熱で運動や疼痛緩和を助けます。マッサージは筋緊張の緩和、用手的リンパドレナージはリンパ浮腫の軽減を目的とします。"},{"h":"主な手技・種類","t":"渦流浴、ハバードタンク、プールでの運動療法。マッサージは軽擦法・揉捏法・圧迫法など。リンパ浮腫には複合的治療（スキンケア・用手的排液・圧迫・運動）。"},{"h":"適応","t":"荷重を制限したい関節疾患や術後、疼痛・筋緊張の亢進、がん術後などの続発性リンパ浮腫、原発性リンパ浮腫。"},{"h":"禁忌・注意","t":"発熱、急性感染症（蜂窩織炎など）、急性の深部静脈血栓症、開放創、非代償性の心不全。水中では静水圧で心負荷が増す点に注意します。"},{"h":"実施のポイント","t":"リンパ排液は浮腫部より中枢側から始め、皮膚をずらす程度の軽い圧で行います。水中運動は水温・時間・体調を確認し、入水前後のバイタルを見ます。"},{"h":"エビデンス","t":"リンパ浮腫では圧迫療法を含む複合的治療として行うことが勧められます。マッサージ単独の効果は限定的で、運動療法と組み合わせて用います。"}]},"keypoints":["浮力は荷重を軽くし、水深で負担が変わる","静水圧は静脈還流を促すが心負荷も増える","リンパ排液は中枢側から軽い圧で始める","発赤・熱感・発熱は感染を疑い中止する","リンパ浮腫は圧迫療法を含む複合的治療で"],"case":{"text":"65歳女性。乳がん術後の続発性リンパ浮腫で患側上肢の周径が健側より大きい。皮膚の発赤・熱感や発熱はなく、深部静脈血栓症の診断もない。","answer":"感染や血栓の徴候がないため複合的治療の適応と考えます。スキンケア、中枢側から軽い圧の用手的排液、圧迫療法、圧迫下の運動を組み合わせます。発赤や発熱が出たら中止し医師へ。"},"questions":[{"level":"基礎","q":"水中で関節にかかる体重の負担を軽くする水の性質はどれか。","options":["浮力","粘性","比熱","表面張力"],"answer":0,"exp":"浮力は体重を打ち消す方向に働き、荷重を軽くします。粘性は動きへの抵抗、比熱は温熱効果に関係します。"},{"level":"基礎","q":"用手的リンパドレナージで最初に施術する部位として適切なのはどれか。","options":["浮腫の最も強い遠位部","浮腫部より中枢側の部位","手指・足趾の先端","疼痛が強い部位のみ"],"answer":1,"exp":"まず中枢側（リンパ節や体幹側）を排液して流れ道をつくり、その後に遠位へ進めます。"},{"level":"中級","q":"用手的リンパドレナージの禁忌として最も適切なのはどれか。","options":["慢性の続発性リンパ浮腫","維持期の上肢リンパ浮腫","急性の深部静脈血栓症","軽度の皮膚乾燥"],"answer":2,"exp":"急性の深部静脈血栓症では血栓が移動するおそれがあり禁忌です。慢性のリンパ浮腫は適応、皮膚乾燥はスキンケアで対応します。"},{"level":"中級","q":"リンパ浮腫の複合的治療に含まれないものはどれか。","options":["スキンケア","用手的リンパドレナージ","圧迫療法","患肢の長期間の安静固定"],"answer":3,"exp":"複合的治療はスキンケア・用手的排液・圧迫療法・圧迫下の運動療法で構成されます。長期の安静固定は含まれません。"},{"level":"臨床","q":"60代女性。乳がん術後の上肢浮腫で排液中、患肢に急な発赤・熱感と発熱が出現した。対応として適切なのはどれか。","options":["排液の圧を強める","施術を中止し医師に報告する","温熱療法を追加する","圧迫を強めて継続する"],"answer":1,"exp":"蜂窩織炎などの急性感染症を疑う所見です。排液・圧迫・温熱は中止し、速やかに医師へつなぎます。"},{"level":"臨床","q":"70代男性。心不全があり安静時にも息切れがある。プールでの運動療法を検討する際の判断として適切なのはどれか。","options":["静水圧で心負荷が増すため医師と適応を確認する","浮力があるので制限なく行う","深い水深で長時間行う","水温を高めにして行う"],"answer":0,"exp":"水中では静水圧により静脈還流が増え心負荷が上がります。症状が安定していない心不全では、医師と適応を確認します。"}],"seccion":"治療と介入","grupo":"手技と物理療法","icono":"🤲","mapa":"img/mapas/t46.jpg","fichas":[],"secuencias":[]},"47":{"id":47,"title":"キネシオテーピング","lead":"伸縮性テープを皮膚に貼り、感覚入力や関節運動の補助をねらう方法です。貼り方の基本と皮膚トラブルの予防を押さえて、運動療法の補助として使います。","sheet":{"kind":"method","items":[{"h":"目的","t":"皮膚への感覚入力による筋活動の補助、関節運動の誘導、姿勢の気づき、浮腫や内出血の軽減の補助をねらいます。強い固定は目的としません。"},{"h":"主な手技・種類","t":"I字・Y字・X字・扇形（リンパ用）などの型。筋に対する貼り方、関節を補助する貼り方、浮腫に対する貼り方があります。固定には非伸縮性テープを用います。"},{"h":"適応","t":"スポーツ外傷後の疼痛や腫脹の軽減の補助、筋の使い方の再学習、姿勢・アライメントの意識づけ、運動療法と並行した使用。"},{"h":"禁忌・注意","t":"皮膚の損傷・感染・湿疹、テープかぶれの既往、深部静脈血栓症の疑い、皮膚が脆弱な高齢者。感覚障害がある部位は皮膚トラブルに気づきにくく注意します。"},{"h":"実施のポイント","t":"皮膚を清潔・乾燥させ、角を丸く切ります。両端は張力をかけずに貼ります。初回は小さく試し、かゆみや発赤が出たらすぐはがすよう指導します。"},{"h":"エビデンス","t":"疼痛などへの効果は短期的・限定的とする報告が多く、単独の治療ではなく運動療法の補助として位置づけるのが妥当です。"}]},"keypoints":["伸縮性テープは固定ではなく補助が目的","両端は張力をかけずに皮膚にのせて貼る","皮膚を清潔・乾燥させ、角を丸く切る","かゆみ・発赤が出たらすぐにはがす","効果は限定的で運動療法と組み合わせる"],"case":{"text":"22歳男性。足関節内反捻挫の受傷3日後で、外果周囲に腫脹と内出血がある。荷重時痛は軽度。テーピングの経験はなく、皮膚疾患の既往はない。","answer":"まず皮膚の状態を確認し、小さく試し貼りします。腫脹部には扇形を張力少なめで貼り、運動療法と並行します。テープで治るとは説明せず、かゆみや発赤が出たらはがすよう伝えます。"},"questions":[{"level":"基礎","q":"伸縮性テープの両端を貼るときの張力として適切なのはどれか。","options":["最大まで伸ばして貼る","端だけ強く伸ばす","張力をかけずに貼る","皮膚をつまんで貼る"],"answer":2,"exp":"両端（アンカー）は張力をかけずに皮膚にのせて貼ります。端に張力があると皮膚が引っ張られ、はがれやかぶれの原因になります。"},{"level":"基礎","q":"テープを2本に切り分け、筋腹を囲むように貼る型はどれか。","options":["I字","X字","扇形","Y字"],"answer":3,"exp":"Y字は根元を1か所に貼り、2本に分かれた部分で筋腹を囲みます。扇形は細く分けて浮腫部に広げる型です。"},{"level":"中級","q":"テーピング後にすぐはがすよう指導すべき所見はどれか。","options":["貼付部のかゆみや発赤","運動後の軽い筋のはり","姿勢を意識しやすくなった","動きやすさを感じる"],"answer":0,"exp":"かゆみや発赤はテープかぶれなどの皮膚トラブルの徴候です。悪化を防ぐため、すぐにはがすよう指導します。"},{"level":"中級","q":"関節の動きを強く制限して固定したい場合に適したものはどれか。","options":["伸縮性テープのI字","非伸縮性テープ","伸縮性テープの扇形","張力なしのY字"],"answer":1,"exp":"強い固定には非伸縮性テープを用います。伸縮性テープは関節の動きを妨げにくく、補助や感覚入力が目的です。"},{"level":"臨床","q":"20代男性。足関節捻挫後の腫脹にテーピングを予定している。貼付前に確認すべきこととして最も重要なのはどれか。","options":["歩行速度","安静時心拍数","皮膚の状態とかぶれの既往","利き足"],"answer":2,"exp":"貼付前には皮膚の損傷・湿疹やテープかぶれの既往を確認します。皮膚トラブルがあれば貼付を見合わせます。"},{"level":"臨床","q":"30代女性。肩のテーピング後に「痛みが軽くなった」と話す。説明として適切なのはどれか。","options":["組織が修復されて治った","効果は一時的なことが多く運動療法と併用する","ずっと貼り続ける必要がある","筋力がすぐに強くなった"],"answer":1,"exp":"テーピングの効果は短期的で限定的とされます。過大な期待を持たせず、運動療法の補助であると説明します。"}],"seccion":"治療と介入","grupo":"手技と物理療法","icono":"🤲","mapa":"img/mapas/t47.jpg","fichas":[],"secuencias":[]},"48":{"id":48,"title":"運動療法","lead":"運動を処方して筋力・柔軟性・持久力・バランスを改善し、ADLの向上をめざす理学療法の中核です。負荷の原則と中止基準を理解して安全に進めます。","sheet":{"kind":"method","items":[{"h":"目的","t":"関節可動域、筋力、筋持久力、全身持久力、柔軟性、バランス・協調性を改善し、基本動作やADL、生活の参加を高めることです。"},{"h":"主な手技・種類","t":"関節可動域運動（他動・自動介助・自動）、筋力増強運動（等尺性・等張性〈求心性・遠心性〉・等速性）、ストレッチング、有酸素運動、バランス・協調性練習。"},{"h":"適応","t":"筋骨格系疾患、術後、神経疾患、内部障害、廃用症候群、高齢者の機能低下など、幅広い対象に用います。"},{"h":"禁忌・注意","t":"不安定な心疾患、コントロール不良の高血圧、急性炎症、未固定の骨折部位などは注意・禁忌です。アンダーソン・土肥の基準など中止基準を確認します。"},{"h":"実施のポイント","t":"過負荷・特異性・可逆性の原則で負荷を設定し、自覚的運動強度やバイタルを確認します。代償運動を見逃さず、息こらえを避けて呼吸を続けさせます。"},{"h":"エビデンス","t":"多くの筋骨格系疾患や慢性疾患で、運動療法は治療の中核として推奨されています。継続できる内容にすることが効果に直結します。"}]},"keypoints":["過負荷・特異性・可逆性の原則で負荷を組む","術後早期は関節を動かさない等尺性運動から","息こらえ（いきみ）を避けて呼吸を続ける","代償運動を見逃さず正しい動きで行う","胸痛・冷汗・強い息切れは即中止して報告"],"case":{"text":"72歳女性。人工膝関節置換術後3週。大腿四頭筋のMMTは3で、自動運動で全可動域を動かせるが抵抗には耐えられない。バイタルは安定している。","answer":"重力に抗する自動運動から始め、軽い抵抗を段階的に加えます。代償運動と疼痛を確認し、息こらえを避けます。初日から最大負荷の運動は行いません。"},"questions":[{"level":"基礎","q":"筋が張力を発揮しながら引き伸ばされる収縮様式はどれか。","options":["求心性収縮","遠心性収縮","等尺性収縮","等速性収縮"],"answer":1,"exp":"遠心性収縮は筋が伸張されながら力を発揮する収縮です。求心性は短縮しながら、等尺性は筋長を変えずに力を発揮します。"},{"level":"基礎","q":"筋力を高めるために日常より大きい負荷をかけるという原則はどれか。","options":["特異性の原則","可逆性の原則","過負荷の原則","個別性の原則"],"answer":2,"exp":"過負荷の原則は、日常的な負荷を超える刺激を与えることで適応が起こるという考え方です。"},{"level":"中級","q":"関節運動を伴わずに筋力を高めるため、術後早期に用いやすい運動はどれか。","options":["等尺性運動","等速性運動","ジャンプ運動","高負荷の遠心性運動"],"answer":0,"exp":"等尺性運動は関節を動かさずに筋を収縮させるため、関節や術創への負担を抑えて早期から行えます。"},{"level":"中級","q":"筋力増強運動の実施中に避けるべきことはどれか。","options":["呼吸を続ける","代償運動を確認する","準備運動を行う","息こらえをする"],"answer":3,"exp":"息こらえ（いきみ）は血圧を急上昇させます。特に高齢者や心疾患のある人では、呼吸を止めずに行います。"},{"level":"臨床","q":"70代男性。大腿四頭筋のMMTは3。筋力増強運動の開始として適切なのはどれか。","options":["最大抵抗での等速性運動","重力に抗する自動運動から段階的に負荷を加える","他動運動のみを行う","高強度のジャンプ運動"],"answer":1,"exp":"MMT3は重力に抗して全可動域を動かせる段階です。自動運動から始め、軽い抵抗を段階的に加えます。"},{"level":"臨床","q":"60代男性。自転車エルゴメーター運動中に胸痛と冷汗が出現した。対応として適切なのはどれか。","options":["運動を中止しバイタルを確認して医師に報告する","負荷を下げて継続する","休憩後に同じ負荷で再開する","ストレッチに切り替える"],"answer":0,"exp":"胸痛と冷汗は運動の中止基準に当たり、心疾患の可能性があります。直ちに中止し、バイタルを確認して医師へ報告します。"}],"seccion":"治療と介入","grupo":"運動療法と専門領域","icono":"🩺","mapa":"img/mapas/t48.jpg","fichas":[],"secuencias":[{"nombre":"ブリッジ","rotulo":"鍛える部位","texto":"殿筋群・ハムストリングス","frames":["img/mov/ponte-1.jpg","img/mov/ponte-2.jpg","img/mov/ponte-3.jpg"]},{"nombre":"下肢伸展挙上エクササイズ","rotulo":"鍛える部位","texto":"大腿四頭筋","frames":["img/mov/elevacao-1.jpg","img/mov/elevacao-2.jpg","img/mov/elevacao-3.jpg"]},{"nombre":"スクワット","rotulo":"鍛える部位","texto":"大腿四頭筋・殿筋群","frames":["img/mov/agachamento-1.jpg","img/mov/agachamento-2.jpg","img/mov/agachamento-3.jpg"]}]},"49":{"id":49,"title":"呼吸理学療法","lead":"呼吸法の指導、排痰の援助、運動療法で換気と呼吸困難を改善する理学療法です。COPDや術後の肺合併症予防で中心的な役割を担います。","sheet":{"kind":"method","items":[{"h":"目的","t":"換気の改善、気道クリアランスの促進、呼吸困難の軽減、運動耐容能とADLの向上、術後肺合併症の予防をめざします。"},{"h":"主な手技・種類","t":"口すぼめ呼吸、横隔膜呼吸、体位排痰法、ハフィング・咳嗽指導、呼吸介助、呼吸筋トレーニング、全身持久力運動・筋力増強運動。"},{"h":"適応","t":"COPDなどの慢性呼吸器疾患、肺炎、胸部・腹部手術の前後、神経筋疾患による換気障害、痰の多い気管支拡張症など。"},{"h":"禁忌・注意","t":"頭低位の体位排痰は頭蓋内圧亢進・不安定な循環・喀血などで避けます。未処置の気胸、重い不整脈にも注意し、SpO2と症状を確認します。"},{"h":"実施のポイント","t":"聴診や画像所見で痰の部位を確認して体位を選びます。SpO2・呼吸数・脈拍・修正ボルグスケールを確認し、動作は呼吸に合わせてペースを配分します。"},{"h":"エビデンス","t":"COPDでは運動療法を中心とした呼吸リハビリテーションが呼吸困難や運動耐容能の改善に推奨されています。"}]},"keypoints":["口すぼめ呼吸は呼気時の気道虚脱を防ぐ","体位排痰は痰のある肺区域を上にする","ハフィングは声門を開いたまま強く速く吐く","頭低位は頭蓋内圧亢進や喀血で避ける","COPDの呼吸リハは運動療法が中心となる"],"case":{"text":"74歳男性。COPDで在宅酸素なし。歩行や更衣で息切れが強く、急いで動いた後にSpO2が低下する。痰は少なく、安静時の状態は安定している。","answer":"口すぼめ呼吸と動作のペース配分を指導し、SpO2と呼吸困難をみながら持久力運動と下肢筋力増強を進めます。息を止めて急いで動くことは避けるよう伝えます。"},"questions":[{"level":"基礎","q":"COPDで呼気時の気道の虚脱を防ぐ目的で指導する呼吸法はどれか。","options":["速く浅い胸式呼吸","息止め","口すぼめ呼吸","過換気"],"answer":2,"exp":"口すぼめ呼吸は呼気に抵抗を加えて気道内圧を保ち、気道の虚脱を防いで呼出を助けます。"},{"level":"基礎","q":"痰のある肺区域を上にした姿勢をとり、重力で痰の移動を促す方法はどれか。","options":["ハフィング","体位排痰法","呼吸筋トレーニング","口すぼめ呼吸"],"answer":1,"exp":"体位排痰法（体位ドレナージ）は痰が貯留した肺区域を上にし、重力を利用して中枢気道へ移動させます。"},{"level":"中級","q":"声門を開いたまま強く速く呼出して痰を移動させる手技はどれか。","options":["咳嗽の抑制","横隔膜呼吸","バルサルバ法","ハフィング"],"answer":3,"exp":"ハフィングは声門を開いたまま強制的に呼出する手技で、咳より胸腔内圧の上昇が少なく痰を移動させます。"},{"level":"中級","q":"頭低位の体位排痰法を避けるべき状態はどれか。","options":["頭蓋内圧亢進","慢性の気管支拡張症","痰の多い肺炎","下葉の無気肺"],"answer":0,"exp":"頭低位は頭蓋内圧を上げるため、頭蓋内圧亢進では避けます。他の選択肢は体位排痰の適応となりうる状態です。"},{"level":"臨床","q":"70代男性、COPD。歩行中に息切れが強くなりSpO2が低下する。指導として適切なのはどれか。","options":["速く歩いて早く終える","口すぼめ呼吸と動作のペース配分","息を止めて動作する","歩行を一切やめる"],"answer":1,"exp":"呼吸に合わせて動作のペースを配分し、口すぼめ呼吸を併用します。活動を完全にやめると廃用が進みます。"},{"level":"臨床","q":"腹部手術の翌日の患者。術後肺合併症の予防として適切なのはどれか。","options":["数日間のベッド上安静","痛みがあるので呼吸練習は控える","早期離床と深呼吸・咳嗽の指導","頭低位を長時間保持する"],"answer":2,"exp":"早期離床と深呼吸・咳嗽（創部を押さえての咳）の指導は、無気肺や肺炎の予防に重要です。"}],"seccion":"治療と介入","grupo":"運動療法と専門領域","icono":"🩺","mapa":"img/mapas/t49.jpg","fichas":[],"secuencias":[]},"50":{"id":50,"title":"心臓リハビリテーション","lead":"運動療法・患者教育・生活指導を組み合わせた包括的なプログラムです。運動耐容能とQOLを高め、再発予防をめざします。安全管理が最優先です。","sheet":{"kind":"method","items":[{"h":"目的","t":"運動耐容能とQOLの向上、冠危険因子の是正、再発・再入院の予防、心理的な不安の軽減、社会復帰の支援をめざします。"},{"h":"主な手技・種類","t":"有酸素運動（歩行・自転車エルゴメーター）、レジスタンストレーニング、患者教育、服薬・食事・禁煙などの生活指導。急性期・回復期・維持期の3つの時期で進めます。"},{"h":"適応","t":"急性心筋梗塞後、狭心症、心臓手術後、慢性心不全、大血管疾患、末梢動脈疾患など。病状が安定していることが前提です。"},{"h":"禁忌・注意","t":"不安定狭心症、コントロールされていない不整脈、非代償性の心不全、症状のある重症大動脈弁狭窄症、急性心筋炎などは運動療法の禁忌です。"},{"h":"実施のポイント","t":"強度は心肺運動負荷試験の嫌気性代謝閾値（AT）や自覚的運動強度で設定します。β遮断薬服用中は心拍数が上がりにくく、自覚症状と血圧・心電図も確認します。"},{"h":"エビデンス","t":"冠動脈疾患や慢性心不全では、運動療法を含む包括的心臓リハビリテーションがガイドラインで推奨されています。"}]},"keypoints":["運動・教育・生活指導を組み合わせて行う","強度はATや自覚的運動強度で設定する","β遮断薬では心拍数だけで強度を決めない","胸痛・ST変化・不整脈の出現で中止する","急な体重増加・浮腫は心不全増悪を疑う"],"case":{"text":"63歳男性。急性心筋梗塞で治療後、回復期に外来で運動療法中。β遮断薬を服用している。自転車エルゴメーター中、胸部症状はないが心拍数があまり上がらない。","answer":"β遮断薬で心拍数の反応が鈍いため、心拍数だけで負荷を上げず、自覚的運動強度・血圧・心電図で判断します。胸痛やST変化が出れば中止して医師に報告します。"},"questions":[{"level":"基礎","q":"心臓リハビリテーションの構成要素に含まれないものはどれか。","options":["運動療法","患者教育","冠危険因子の是正","長期間の安静臥床"],"answer":3,"exp":"心臓リハは運動療法・患者教育・生活指導・カウンセリングを含む包括的プログラムです。長期の安静臥床は廃用を招きます。"},{"level":"基礎","q":"心肺運動負荷試験から得られ、運動強度の設定に用いる指標はどれか。","options":["徒手筋力検査","嫌気性代謝閾値（AT）","関節可動域","握力"],"answer":1,"exp":"嫌気性代謝閾値（AT）は有酸素運動の強度設定によく用いられる指標で、心肺運動負荷試験で求めます。"},{"level":"中級","q":"運動療法の禁忌として適切なのはどれか。","options":["安定した慢性心不全","冠動脈バイパス術後の回復期","不安定狭心症","心筋梗塞後の安定期"],"answer":2,"exp":"不安定狭心症は運動療法の禁忌です。病状が安定した慢性心不全や術後・梗塞後の回復期は適応となります。"},{"level":"中級","q":"β遮断薬を服用している患者で運動強度の目安として有用なのはどれか。","options":["自覚的運動強度（ボルグスケール）","心拍数のみ","体重","体温"],"answer":0,"exp":"β遮断薬は心拍数の上昇を抑えるため、心拍数だけでは強度を過大に設定するおそれがあります。自覚的運動強度を併用します。"},{"level":"臨床","q":"60代男性。心筋梗塞後の回復期。歩行練習中に胸痛と心電図のST低下が出現した。対応として適切なのはどれか。","options":["歩行速度を上げる","そのまま継続して様子を見る","水分補給後に同じ負荷で再開する","運動を中止し医師に報告する"],"answer":3,"exp":"胸痛とST低下は心筋虚血を示す中止の所見です。直ちに運動を中止し、医師へ報告します。"},{"level":"臨床","q":"70代女性、慢性心不全。数日で体重が急に増え、下腿浮腫と息切れが悪化した。対応として適切なのはどれか。","options":["運動強度を上げる","心不全の増悪を疑い医師に報告する","通常通り実施する","筋力トレーニングのみ追加する"],"answer":1,"exp":"短期間の体重増加・浮腫・息切れの悪化は心不全増悪のサインです。運動療法を見合わせ、医師へ報告します。"}],"seccion":"治療と介入","grupo":"運動療法と専門領域","icono":"🩺","mapa":"img/mapas/t50.jpg","fichas":[],"secuencias":[]},"51":{"id":51,"title":"骨盤底・ウィメンズヘルス","lead":"骨盤底筋の機能障害による尿失禁や骨盤臓器脱、妊娠・産後の身体の変化などに対応する領域です。正しい収縮の指導とレッドフラッグの確認が基本です。","sheet":{"kind":"method","items":[{"h":"目的","t":"骨盤底筋の筋力・持久力・協調性を改善し、尿失禁や骨盤臓器脱の症状を軽減します。妊娠・産後の腰骨盤帯痛や体幹機能の回復も支援します。"},{"h":"主な手技・種類","t":"骨盤底筋トレーニング、バイオフィードバック、腹圧と呼吸のコントロール指導、姿勢・動作指導、生活指導（排尿習慣・体重管理など）。"},{"h":"適応","t":"腹圧性尿失禁、混合性尿失禁、軽度の骨盤臓器脱、産後の骨盤底機能低下、腹直筋離開、前立腺全摘術後の男性の尿失禁。"},{"h":"禁忌・注意","t":"内診による評価は専門の研修と十分な説明・同意が前提です。妊娠後期の長い仰臥位は仰臥位低血圧症候群に注意。血尿・発熱・会陰部のしびれは医師へ。"},{"h":"実施のポイント","t":"締めて引き上げる収縮を確認し、腹筋・殿筋・内転筋の力みや息こらえを避けます。速い収縮と持続する収縮を練習し、日常で継続できる方法にします。"},{"h":"エビデンス","t":"腹圧性尿失禁に対して、骨盤底筋トレーニングは保存療法の第一選択として推奨されています。継続できるかが効果を左右します。"}]},"keypoints":["骨盤底筋は「締めて引き上げる」で指導する","息こらえや殿筋の力みは代償として避ける","咳・くしゃみでの漏れは腹圧性尿失禁","妊娠後期の長い仰臥位は低血圧に注意","急な排尿障害・会陰部のしびれは医師へ"],"case":{"text":"38歳女性。出産後1年。咳やくしゃみで尿が漏れる。上体を起こすと腹部正中が膨隆する。血尿・発熱・会陰部の感覚異常はない。","answer":"腹圧性尿失禁と腹直筋離開を考えます。正しい骨盤底筋の収縮と、息こらえを避けた腹圧のコントロールを指導します。いきなり強い上体起こしを繰り返す運動は避けます。"},"questions":[{"level":"基礎","q":"骨盤底を構成する主要な筋はどれか。","options":["腸腰筋","大殿筋","肛門挙筋","大腿直筋"],"answer":2,"exp":"肛門挙筋は尾骨筋とともに骨盤隔膜をつくる骨盤底の主要な筋です。他は股関節周囲の筋です。"},{"level":"基礎","q":"咳やくしゃみなどで腹圧が高まったときに尿が漏れる失禁はどれか。","options":["切迫性尿失禁","腹圧性尿失禁","溢流性尿失禁","機能性尿失禁"],"answer":1,"exp":"腹圧性尿失禁は腹圧上昇時に尿道の閉鎖が不十分となって起こります。切迫性は強い尿意を伴う失禁です。"},{"level":"中級","q":"骨盤底筋トレーニングの収縮の指導として適切なのはどれか。","options":["息を止めて腹に力を入れる","殿筋を強く締める","腹部を前に押し出す","尿道・腟・肛門を締めて引き上げる"],"answer":3,"exp":"骨盤底筋は締めて引き上げるように収縮させます。息こらえ・殿筋の力み・腹部を押し出す動きは代償です。"},{"level":"中級","q":"妊娠後期に長時間の仰臥位をとる際に注意すべきものはどれか。","options":["仰臥位低血圧症候群","腹直筋離開の改善","骨盤底筋の肥大","尿失禁の消失"],"answer":0,"exp":"妊娠後期の仰臥位では子宮が下大静脈を圧迫し、血圧が低下することがあります。側臥位などに姿勢を変えます。"},{"level":"臨床","q":"38歳女性。産後1年で咳による尿漏れがあり、上体を起こすと腹部正中が膨隆する。介入として適切なのはどれか。","options":["強い上体起こし運動を毎日多く行う","骨盤底筋トレーニングと腹圧コントロールの指導","水分摂取を極端に減らす","安静のみを勧める"],"answer":1,"exp":"腹圧性尿失禁と腹直筋離開が考えられます。正しい骨盤底筋の収縮と腹圧のコントロールから始めます。"},{"level":"臨床","q":"50代女性。腰痛で通院中に、急な排尿困難と会陰部のしびれを訴えた。対応として適切なのはどれか。","options":["骨盤底筋トレーニングを強化する","次回まで様子を見る","直ちに医師に連絡する","腰部のストレッチを行う"],"answer":2,"exp":"急な排尿障害と会陰部の感覚障害は馬尾症候群を疑うレッドフラッグです。直ちに医師へつなぎます。"}],"seccion":"治療と介入","grupo":"運動療法と専門領域","icono":"🩺","mapa":"img/mapas/t51.jpg","fichas":[],"secuencias":[]},"52":{"id":52,"title":"小児理学療法","lead":"発達途上の子どもを対象に、運動発達と活動・参加を支える理学療法です。正常発達の知識を土台に、遊びと家族との協働で進めます。","sheet":{"kind":"method","items":[{"h":"目的","t":"運動発達の促進、基本動作と移動能力の獲得、拘縮や変形などの二次障害の予防、家庭・園・学校での活動と参加の拡大、家族支援です。"},{"h":"主な手技・種類","t":"神経発達学的アプローチ、課題指向型練習、遊びを取り入れた運動、姿勢管理、装具・座位保持装置・歩行器の活用、家族への指導。"},{"h":"適応","t":"脳性麻痺、発達の遅れ、ダウン症候群、二分脊椎、デュシェンヌ型筋ジストロフィー、低出生体重児、整形外科疾患など。"},{"h":"禁忌・注意","t":"痙直型脳性麻痺では股関節の亜脱臼・脱臼の確認が重要です。筋ジストロフィーでは疲労を残す高負荷運動を避けます。てんかん発作や疲労に注意します。"},{"h":"実施のポイント","t":"評価にはGMFMやGMFCS、原始反射・姿勢反応を用います。子どもが楽しめる遊びの中で練習し、家族と生活場面の目標を共有して家庭でも続けられる形にします。"},{"h":"エビデンス","t":"目標を明確にした課題指向型の練習や、家族と協働した介入が支持される傾向にあります。手技単独より生活での実践を重視します。"}]},"keypoints":["定頸は生後3〜4か月ごろが目安","GMFCSは脳性麻痺の粗大運動を5段階で分類","痙直型脳性麻痺は股関節脱臼を定期的に確認","筋ジストロフィーは疲労を残す高負荷を避ける","目標は家族と共有し遊びの中で練習する"],"case":{"text":"5歳男児。痙直型両麻痺。歩行器で室内を移動しているが、つま先接地が目立つ。家族は「保育園で友だちと一緒に移動したい」と希望している。","answer":"家族の希望を生活場面の目標にし、歩行器での移動練習を遊びや園での活動に結びつけます。下腿三頭筋の短縮予防や装具の検討、股関節の確認も行います。正常発達の順序だけにこだわりません。"},"questions":[{"level":"基礎","q":"定頸（首がすわる）の獲得時期の目安はどれか。","options":["生後1か月","生後3〜4か月","生後7〜8か月","生後12か月"],"answer":1,"exp":"定頸は生後3〜4か月ごろが目安です。その後、寝返り・座位・つかまり立ち・独歩の順に進みます。"},{"level":"基礎","q":"脳性麻痺児の粗大運動能力を5つのレベルに分類する尺度はどれか。","options":["GMFM","MMT","FIM","GMFCS"],"answer":3,"exp":"GMFCSは粗大運動能力を5段階で分類します。GMFMは粗大運動能力を得点で測定する評価尺度です。"},{"level":"中級","q":"デュシェンヌ型筋ジストロフィーで避けるべき運動はどれか。","options":["疲労を残す高負荷の運動","関節可動域運動","呼吸練習","遊びを取り入れた運動"],"answer":0,"exp":"筋線維が損傷しやすいため、疲労を強く残す高負荷運動は避けます。拘縮予防や呼吸練習は重要です。"},{"level":"中級","q":"痙直型脳性麻痺児で定期的な確認が重要な合併症はどれか。","options":["前十字靭帯断裂","腱板断裂","股関節の亜脱臼・脱臼","足関節捻挫"],"answer":2,"exp":"股関節周囲筋の痙縮と筋の不均衡により、股関節の亜脱臼・脱臼が起こりやすく定期的な確認が必要です。"},{"level":"臨床","q":"4歳児。痙直型両麻痺。歩行の目標を設定する方法として適切なのはどれか。","options":["療法士だけで決める","家族と共有し生活場面の目標を立てる","正常発達の順序だけを厳守する","遊びを除いて反復練習のみ行う"],"answer":1,"exp":"目標は家族と共有し、家庭や園での具体的な活動に結びつけます。遊びを取り入れることで練習が続きやすくなります。"},{"level":"臨床","q":"7歳男児、デュシェンヌ型筋ジストロフィー。階段昇降が難しくなってきた。運動の考え方として適切なのはどれか。","options":["疲労を残さない範囲で活動を維持し拘縮を予防する","高負荷の遠心性運動で筋力を増強する","運動をすべて禁止する","毎日限界まで歩かせる"],"answer":0,"exp":"過度な負荷は筋損傷を進めるおそれがあります。疲労を残さない範囲で活動量を保ち、拘縮予防を続けます。"}],"seccion":"治療と介入","grupo":"運動療法と専門領域","icono":"🩺","mapa":"img/mapas/t52.jpg","fichas":[],"secuencias":[]},"53":{"id":53,"title":"高齢者の理学療法","lead":"加齢に伴う機能低下、フレイル、サルコペニア、転倒への対応が中心です。生活機能と参加を守るため、評価に基づいて安全に運動を続けられるよう支援します。","sheet":{"kind":"method","items":[{"h":"目的","t":"ADLと生活機能・参加の維持・向上、転倒予防、フレイル・サルコペニアの予防と改善、廃用症候群の予防、介護者の負担軽減です。"},{"h":"主な手技・種類","t":"下肢・体幹の筋力増強運動、バランス練習、歩行練習、二重課題練習、起居・移乗動作練習、福祉用具の選定、住環境の調整。"},{"h":"適応","t":"フレイル、サルコペニア、転倒歴のある人、骨折や手術の後、慢性疾患による活動低下、入院による廃用、認知症のある人の活動支援。"},{"h":"禁忌・注意","t":"起立性低血圧、骨粗鬆症による椎体骨折、多剤服用による副作用、脱水、皮膚の脆弱性、認知機能の低下に注意します。急な痛みや症状の変化は医師へ。"},{"h":"実施のポイント","t":"TUG、片脚立位、椅子からの立ち上がり、歩行速度、握力などで評価し、個別の目標を立てます。負荷は段階的に上げ、栄養と組み合わせて継続を促します。"},{"h":"エビデンス","t":"バランスと筋力の要素を含む運動介入は、地域の高齢者の転倒予防に有効とされています。継続できる内容にすることが重要です。"}]},"keypoints":["Friedのフレイル基準には歩行速度の低下がある","サルコペニアは筋量と筋力・身体機能の低下","転倒予防はバランスと筋力を組み合わせる","長期臥床後の離床は起立性低血圧に注意","骨粗鬆症の急な背部痛は椎体骨折を疑う"],"case":{"text":"82歳女性。この1年で2回転倒。TUGは延長し、椅子からの立ち上がりに手の支えが必要。骨粗鬆症の治療中で、背部痛はない。独居で外出を控えている。","answer":"転倒リスクが高い状態です。バランス練習と下肢筋力増強を段階的に組み合わせ、住環境の調整や外出の機会づくりも行います。安静を勧めることや初日からの高負荷運動は避けます。"},"questions":[{"level":"基礎","q":"Friedのフレイル基準に含まれる項目はどれか。","options":["視力の低下","血圧の上昇","歩行速度の低下","身長の増加"],"answer":2,"exp":"Friedの基準は体重減少・疲労感・活動量低下・歩行速度低下・筋力（握力）低下の5項目です。"},{"level":"基礎","q":"加齢などにより筋量が減少し、筋力や身体機能が低下した状態はどれか。","options":["サルコペニア","骨粗鬆症","変形性関節症","起立性低血圧"],"answer":0,"exp":"サルコペニアは筋量の減少に筋力または身体機能の低下を伴う状態です。骨粗鬆症は骨量の減少です。"},{"level":"中級","q":"TUG（Timed Up and Go Test）で評価する内容として適切なのはどれか。","options":["握力","立ち上がり・歩行・方向転換を含む動作","認知機能のみ","呼吸機能"],"answer":1,"exp":"TUGは椅子から立ち、歩いて方向転換し、戻って座るまでの時間を測り、移動能力や転倒リスクを評価します。"},{"level":"中級","q":"長期臥床後の高齢者が初めて座位・立位をとるときに特に注意すべきものはどれか。","options":["腱板断裂","低体温","手指の拘縮","起立性低血圧"],"answer":3,"exp":"臥床が続くと血圧調節が低下し、起き上がりや立位で血圧が下がりやすくなります。症状と血圧を確認します。"},{"level":"臨床","q":"80代女性。転倒歴があり、TUGが延長し下肢筋力が低下している。介入として適切なのはどれか。","options":["バランス練習と下肢筋力増強を組み合わせる","ストレッチのみを行う","安静を勧める","初日から最大負荷の筋力トレーニング"],"answer":0,"exp":"転倒予防にはバランスと筋力の要素を組み合わせた運動が有効です。負荷は段階的に上げます。"},{"level":"臨床","q":"85歳女性、骨粗鬆症。軽い尻もちの後から急に強い背部痛が出た。対応として適切なのはどれか。","options":["体幹の屈曲運動を強化する","温熱で様子を見る","医師に報告し画像評価につなぐ","背筋のストレッチを行う"],"answer":2,"exp":"骨粗鬆症のある高齢者の軽微な外傷後の急な背部痛は、椎体圧迫骨折を疑います。運動を進めず医師へつなぎます。"}],"seccion":"治療と介入","grupo":"運動療法と専門領域","icono":"🩺","mapa":"img/mapas/t53.jpg","fichas":[],"secuencias":[]},"54":{"id":54,"title":"臨床ケース","lead":"臨床推論は、問診から仮説を立て、評価で検証し、統合と解釈を経て目標と介入を決める流れです。再評価で仮説を見直し続けることが大切です。","sheet":{"kind":"basics","items":[{"h":"問診","t":"主訴、発症の経過、痛みの部位と性質、悪化・軽減因子、既往歴、服薬、生活背景、本人の希望を聴きます。レッドフラッグもここで確認します。"},{"h":"仮説の立案","t":"問診から考えられる原因や病態を複数挙げ、確かめるべき評価項目を決めます。最初から1つに決めつけないことが大切です。"},{"h":"評価","t":"視診・触診、関節可動域、MMT、特殊テスト、神経学的検査、動作分析などで仮説を検証します。左右差と再現性を確認します。"},{"h":"統合と解釈","t":"評価結果をICFの枠組み（心身機能・活動・参加・環境）で整理し、問題点の関連と優先順位を考えます。"},{"h":"目標設定","t":"本人・家族と共有し、具体的で測定でき、期限のある短期目標と長期目標を立てます。生活場面の目標を重視します。"},{"h":"介入と再評価","t":"目標に沿って介入を選び、同じ指標で変化を再評価します。改善しない場合は仮説と評価に立ち返って見直します。"}]},"keypoints":["問診の段階でレッドフラッグを必ず確認する","仮説は複数挙げ、評価で1つずつ検証する","問題点はICFの枠組みで整理する","目標は本人と共有し測定可能・期限付きに","改善しなければ仮説と評価から見直す"],"case":{"text":"68歳男性。両膝の変形性膝関節症。歩行時に右膝痛があり、右大腿四頭筋の筋力低下と膝伸展制限を認める。希望は「孫と近所の公園まで歩きたい」。","answer":"痛み・筋力低下・可動域制限と歩行の制限を整理し、公園までの歩行を目標に期限を決めます。筋力増強と可動域運動を行い、痛みと歩行距離で再評価します。画像所見だけで介入を決めません。"},"questions":[{"level":"基礎","q":"臨床推論の流れで、問診の次に行うこととして適切なのはどれか。","options":["介入を開始する","仮説を立てる","目標を最終決定する","退院指導を行う"],"answer":1,"exp":"問診で得た情報から原因や病態の仮説を立て、それを検証する評価項目を選びます。"},{"level":"基礎","q":"目標設定の方法として適切なのはどれか。","options":["療法士だけで決める","抽象的な表現にとどめる","期限を設けない","測定でき期限のある目標にする"],"answer":3,"exp":"目標は本人・家族と共有し、具体的で測定可能、期限のあるものにします。これにより再評価で変化を判断できます。"},{"level":"中級","q":"ICFで「階段の昇降ができない」はどれに分類されるか。","options":["活動","参加","心身機能・身体構造","環境因子"],"answer":0,"exp":"階段昇降などの個人が行う動作の遂行は「活動」に分類されます。社会的な役割への関わりは「参加」です。"},{"level":"中級","q":"介入後の再評価で改善がみられない場合の対応として適切なのはどれか。","options":["同じ介入を続ける","評価を省略する","仮説と評価を見直す","患者の努力不足と判断する"],"answer":2,"exp":"改善しない場合は、仮説や評価が適切だったかに立ち返り、病態の捉え方と介入を見直します。"},{"level":"臨床","q":"50代男性。上肢挙上の途中の範囲で肩外側痛が出て、ホーキンステストが陽性。他動可動域は保たれている。最も疑われるのはどれか。","options":["凍結肩","肩峰下インピンジメント","頸椎症性神経根症","胸郭出口症候群"],"answer":1,"exp":"挙上途中の有痛弧とホーキンステスト陽性は肩峰下インピンジメントを示唆します。凍結肩では他動可動域も制限されます。"},{"level":"臨床","q":"60代女性。腰痛でがんの既往があり、夜間痛と原因不明の体重減少がある。対応として適切なのはどれか。","options":["腰部の運動療法を開始する","マニピュレーションを行う","温熱で様子を見る","医師に情報提供し評価を依頼する"],"answer":3,"exp":"がんの既往・夜間痛・体重減少は重大な疾患を疑うレッドフラッグです。介入の前に医師へつなぎます。"}],"seccion":"治療と介入","grupo":"臨床ケース","icono":"🧩","mapa":"img/mapas/t54.jpg","fichas":[],"secuencias":[]}}};
